import type { RoleRouteItem } from "./role-routes";

/**
 * -------------------------------------------------------------------------
 * ROLE ROUTE DESCRIPTIONS
 *
 * The one-line summary stored next to each route in `role-routes.ts` answers
 * "what is this link?" — too short for the right rail, where the reader has no
 * app in front of them. This map carries the LONG form used by the Role-based
 * Dashboards right rail: a five-to-eight line paragraph per route (Bangla +
 * English) explaining what the section shows, what can be done there, and who
 * it serves. Grounded in the route's own label + summary — no invented
 * features.
 *
 * Keyed by route path so it stays readable and survives label changes.
 * Anywhere a long text is missing, the short one-line summary is used instead,
 * so a newly added route never renders an empty row.
 * -------------------------------------------------------------------------
 */
export const ROLE_ROUTE_DESCRIPTIONS: Record<
  string,
  { bn: string; en: string }
> = {
  "/dashboard/admin/academic-calendar": { bn: "সেশনজুড়ে ছুটি, পরীক্ষা, অনুষ্ঠান ও কর্মদিবসের তালিকা এই পাতায় দেখা যায়। তারিখ অনুযায়ী সাজানো ক্যালেন্ডার থেকে বোঝা যায় কোন দিন কী আছে এবং কত দিন ক্লাস হবে। প্রয়োজনে নতুন দিন যোগ করা বা তারিখ বদলানো যায়, ফলে পরিবর্তন হলে সবাই হালনাগাদ তথ্য পায়। শিক্ষক, শিক্ষার্থী ও অভিভাবক সবাই এই ক্যালেন্ডার অনুসরণ করেন। পরীক্ষার সময়সূচি আর ছুটির দিন পাশাপাশি দেখে সেশন পরিকল্পনা করা যায়। কোনো তারিখ বদলালে ক্যালেন্ডারেই তা সংশোধিত অবস্থায় থাকে।", en: "Holidays, examinations, events and working days for the session appear on this page. A date-ordered calendar shows what falls on which day and how many teaching days remain. Days can be added or dates shifted when plans change, so everyone works from updated information. Teachers, students and guardians all rely on this calendar. Exam schedules and holidays side by side make session planning easier." },
  "/dashboard/admin/ai-pathshala/ai-tutor": { bn: "এই পাতায় একটি চ্যাট টিউটর আছে, যার কাছে প্রশ্ন করা যায়। এটি কেবল অনুমোদিত লেসন কনটেন্ট থেকেই উত্তর দেয়, তাই বাইরের অনুমান বা ভুল তথ্য আসার সুযোগ কম। উত্তর না পাওয়া গেলে জানিয়ে দেয়, ফাঁপা উত্তর বানিয়ে দেয় না। পড়ার সময় আটকে গেলে দ্রুত ব্যাখ্যা পেতে এই টিউটর ব্যবহার করা যায়। শিক্ষার্থীরা ক্লাসের পড়ার পাশাপাশি এখানে প্রশ্ন করে নিজের বোঝাপড়া যাচাই করতে পারে। একই প্রশ্ন ধরে ধরে এগোলে পাঠের ভেতরের অংশগুলো আলাদা করে বোঝা সহজ হয়।", en: "A chat tutor is available on this page to answer questions. It replies only from approved lesson content, which keeps outside guesswork and wrong information out of the answers. When it cannot answer, it says so instead of inventing a reply. The tutor is useful for getting a quick explanation whenever reading gets stuck. Readings that accompany class work can be checked here by asking questions on the same lesson." },
  "/dashboard/admin/ai-pathshala/assessments": { bn: "অ্যাসেসমেন্ট ও প্রত্যেক শিক্ষার্থীর প্রাপ্ত নম্বর এই পাতায় দেখা যায়। কোন অ্যাসেসমেন্ট কবে হয়েছে এবং তাতে কে কত পেয়েছে, তা একসাথে পাওয়া যায়। ফল দেখে বোঝা যায় কোন বিষয়ে বা কোন অংশে শিক্ষার্থীরা দুর্বল। প্রয়োজনে ফল যাচাই করে পরবর্তী পাঠ পরিকল্পনা সাজানো যায়। শিক্ষক ও প্রশাসন উভয়ের কাছেই এই তথ্য কাজে লাগে, আর অ্যাসেসমেন্টভিত্তিক ফল একসঙ্গে দেখে কোনো শিক্ষার্থীর ধারাবাহিক অবস্থা বোঝা যায়। দুর্বল ফল দেখা গেলে সেই অংশটি পরে আবার পড়ানো যায়।", en: "Assessments and the marks each student obtained appear on this page. It shows when an assessment was held and what every learner scored in it, all in one view. The results point to the subject or the part where learners are weak. They can be reviewed and used to shape the next round of teaching. Both teachers and the administration draw on this information. A weak result can be followed by teaching that part again." },
  "/dashboard/admin/ai-pathshala/lesson-planner": { bn: "দিন ধরে সাজানো লেসন প্ল্যান এই পাতায় তৈরি ও দেখা যায়। কোন দিনে কোন ক্লাসে কী পড়ানো হবে তা আগেই ঠিক করে রাখা যায়, ফলে শিক্ষক ক্লাসে ঢোকার আগে প্রস্তুতি নিতে পারেন। প্রয়োজনে পরিকল্পনা বদলানো বা পরের দিনের জন্য এগিয়ে নেওয়া যায়। পাঠদান সুশৃঙ্খল ও সময়সীমার মধ্যে রাখতে শিক্ষকেরা এই প্ল্যান অনুসরণ করেন। কোন দিনের প্ল্যান কতটা সম্পন্ন হয়েছে, তা দেখে পিছিয়ে থাকা অংশ দ্রুত ধরা পড়ে। নতুন দিন যোগ করলে সেটি চলতি ক্রমেই বসে যায়।", en: "Day-by-day lesson plans are created and reviewed on this page. It fixes in advance what will be taught in which class on which day, so a teacher can prepare before entering the room. A plan can be adjusted or carried forward to the next day when needed. Teachers follow these plans to keep delivery orderly and within the schedule. Seeing how much of a day plan is done reveals what has slipped behind." },
  "/dashboard/admin/ai-pathshala/lessons": { bn: "ক্লাস ও বিষয় অনুযায়ী সাজানো কাঠামোবদ্ধ এআই লেসন এই পাতায় পাওয়া যায়। প্রতিটি লেসন খুলে পড়া যায় এবং কোন ক্লাসের কোন বিষয়ে কোন লেসন আছে তা সহজেই খুঁজে নেওয়া যায়। লেসনের ভেতরের কনটেন্ট অনুমোদিত, তাই পড়ানোর কাজে সরাসরি ব্যবহার করা যায়। পাঠদান পরিকল্পনা বা শ্রেণিকক্ষের প্রস্তুতিতে এই লেসনগুলো কাজে লাগে। লেসনগুলো ক্রম অনুযায়ী সাজানো থাকে, তাই শুরুর লেসন থেকে ধাপে ধাপে এগোনো যায়। প্রয়োজনে একই বিষয়ের একাধিক লেসন পাশাপাশি রেখে দেখাও যায়।", en: "Structured AI lessons arranged by class and subject are available on this page. Each lesson opens for reading, and it is easy to find which lessons exist for a given class and subject. The content inside a lesson is approved, so it can be used directly for teaching. These lessons support lesson preparation and classroom delivery. Lessons follow a sequence, so one can move from the first lesson onward in order." },
  "/dashboard/admin/ai-pathshala/progress": { bn: "টপিক ধরে মাস্টারি অগ্রগতি এই পাতায় দেখা যায়, তবে কেবল লগইন করা ব্যবহারকারীর নিজেরটাই। কোন টপিকে দখল ভালো হয়েছে আর কোনটি এখনো দুর্বল, তা স্পষ্ট হয়। অগ্রগতির ধরন দেখে বোঝা যায় কোথায় আরও অনুশীলন দরকার। নিজের অবস্থা বুঝে পড়ার পরিকল্পনা সাজাতে এই পাতা সহায়ক। কোন টপিকে সময় দিলে ফল দ্রুত বদলায়, তা অগ্রগতির ধরনেই বোঝা যায়। একই টপিক বারবার দুর্বল দেখালে বুঝতে হয় ভিত্তি আরও মজবুত করা দরকার।", en: "Topic-by-topic mastery progress is shown on this page, but only for the user who is logged in. It makes clear which topics are well within grasp and which still sit weak. The pattern of progress shows where more practice is needed. The page helps in planning study around one's actual standing. Where practice quickly moves the figure, the pattern of progress shows it plainly." },
  "/dashboard/admin/ai-pathshala/quizzes": { bn: "এআই দিয়ে তৈরি কুইজের তালিকা এই পাতায় থাকে। শিক্ষার্থী জমা দেওয়ার সঙ্গে সঙ্গেই কুইজ যাচাই হয়ে যায়, তাই ফলের জন্য আলাদা করে অপেক্ষা করতে হয় না। কোন বিষয়ের কুইজ কেমন হয়েছে এবং কে কতটা উত্তর করেছে তা দেখা যায়। শ্রেণিকক্ষের অনুশীলন ও সংক্ষিপ্ত মূল্যায়নে এই কুইজগুলো ব্যবহার করা যায়। কোন কুইজ কতজনের কাছে গেছে এবং কতজন জমা দিয়েছে, তা দেখা যায়। ভুল উত্তরগুলোর ধরন দেখে সাধারণ দুর্বলতা চিহ্নিত করা যায়।", en: "Quizzes generated with AI are listed on this page. A quiz is checked the moment a student submits it, so results do not wait on manual marking. It shows how a quiz for a subject turned out and how each learner answered. These quizzes suit classroom practice and short checks of understanding. Wrong answers across a quiz reveal the weakness that is common in the class." },
  "/dashboard/admin/ai-pathshala/study-plan": { bn: "সবচেয়ে দুর্বল টপিকগুলো চিহ্নিত করে একটি ব্যক্তিগত স্টাডি প্ল্যান এই পাতায় তৈরি হয়। কোন টপিক আগে ধরতে হবে এবং কোন ক্রমে এগোলে সুবিধা হবে, তা পরিকল্পনায় সাজানো থাকে। অগ্রগতি বাড়ার সঙ্গে সঙ্গে পরিকল্পনাও হালনাগাদ হয়, ফলে অপ্রয়োজনীয় অংশে সময় নষ্ট হয় না। নিজের দুর্বলতা কাটাতে ধাপে ধাপে এগোনোর রাস্তা এখানেই পাওয়া যায়। প্রতিটি ধাপে কী করতে হবে, তা পরিকল্পনার ভেতরেই লেখা থাকে। কোনো টপিক সহজ হয়ে গেলে সেটি সরে গিয়ে পরেরটির জায়গা করে দেয়।", en: "A personal study plan built from the weakest topics is produced on this page. It sets out which topic to take first and in what order to move, so effort is not spread at random. The plan updates as progress improves, which keeps time off unnecessary ground. It offers a step-by-step route out of one's weak areas. Once a topic eases, it drops out and the next one takes its place." },
  "/dashboard/admin/analytics": { bn: "ভর্তি, উপস্থিতি ও মাস্টারি জুড়ে প্রতিষ্ঠানের সার্বিক চিত্র এই পাতায় একসাথে দেখা যায়। কোন দিক ভালো চলছে আর কোথায় ঘাটতি তৈরি হচ্ছে, তা সংখ্যা ও প্রবণতার মাধ্যমে বোঝা যায়। সময়ের তুলনায় পরিবর্তন দেখে প্রয়োজনীয় সিদ্ধান্ত নেওয়া সহজ হয়। প্রতিষ্ঠান পরিচালনার দায়িত্বে থাকা ব্যক্তিরা সামগ্রিক অবস্থা বুঝতে এই পাতা ব্যবহার করেন। কোন ক্লাস বা সেকশনে মনোযোগ দরকার, তা এখান থেকেই বোঝা যায়। প্রতিষ্ঠানের সামগ্রিক অগ্রগতি সময়ের সঙ্গে তুলনা করাও সম্ভব।", en: "A consolidated picture of the institution across enrolment, attendance and mastery is presented here. Figures and trends show which areas are moving well and where a gap is forming. Seeing how things change over time makes it easier to take the decisions that are needed. Those responsible for running the institution use this page to judge overall health. It also points to the class or section that needs attention." },
  "/dashboard/admin/attendance": { bn: "ক্লাসভিত্তিক হাজিরা খাতা এই পাতায় রাখা হয়। নির্দিষ্ট ক্লাস ও তারিখ বেছে নিয়ে শিক্ষার্থীদের উপস্থিতি নেওয়া যায়, আর আগের কোনো ভুল হলে তা সংশোধনও করা যায়। প্রতিটি ক্লাসের হাজিরার অবস্থা এক জায়গা থেকেই দেখা যায়, তাই কোন ক্লাসের হাজিরা বাকি আছে তা বুঝতে সুবিধা হয়। স্কুল নিজেই এই খাতা পরিচালনা করে, বাইরের কোনো পক্ষ নয়। একই দিনে একাধিক ক্লাসের হাজিরা নেওয়ার সুবিধা থাকে। হাজিরার ধরন দেখে অনুপস্থিতির প্রবণতাও বোঝা যায়।", en: "Class-wise attendance registers are kept on this page. By picking a class and a date, attendance is marked for the learners of that class, and any earlier mistake can be corrected. The attendance state of every class is visible from one place, which makes it easier to see which class is still pending. The school itself runs this register rather than any outside party. Absence patterns become visible across the register." },
  "/dashboard/admin/classes": { bn: "এই পাতায় শিক্ষককে বরাদ্দ করা ক্লাস ও সেকশনগুলোর তালিকা দেখা যায়। প্রতিটি সারিতে ক্লাসের নাম ও সেকশন থাকে, ফলে তিনি এক নজরে বুঝতে পারেন কোথায় ক্লাস নিতে হবে। তালিকা থেকে নির্দিষ্ট ক্লাসে ঢুকে সংশ্লিষ্ট সেকশন ও শিক্ষার্থীদের অবস্থা দেখা যায়। প্রয়োজনে ক্লাসভিত্তিক তথ্য যাচাই করাও এখান থেকেই সম্ভব। প্রতিটি ক্লাসে কতজন শিক্ষার্থী আছেন, তা সারির পাশে দেখে বোঝা যায়। কোনো ক্লাসে ঢুকলে সেখানকার সেকশন ও বিষয়ের তালিকাও পাওয়া যায়।", en: "This page lists the classes and sections assigned to the teacher. Each row shows the class name together with its section, so the teacher can see at a glance where lessons are to be taken. From the list one can open a class and review its sections and the learners within them. It also serves as a quick check on class-level information whenever that is needed. Each class can be opened to reach its sections and subjects." },
  "/dashboard/admin/curriculum": { bn: "কোন ক্লাসে কোন বিষয় পড়ানো হবে এবং কোন ক্রমে সেগুলো এগোবে, তা এই পাতায় নির্ধারিত হয়। বিষয়গুলোর পাশাপাশি তাদের ধারাবাহিকতা সাজিয়ে রাখা যায়, যাতে পুরো সেশন ধরে পড়ানোর পরিকল্পনা স্পষ্ট থাকে। প্রয়োজনে ক্রম বদলানো বা কোনো বিষয় বাদ দেওয়া যায়। শিক্ষক ও পরিকল্পনা প্রণেতারা এই কাঠামো অনুসরণ করে এগিয়ে চলেন। কোন বিষয়ে কত সময় দেওয়া হবে, তা ক্রমের পাশেই দেখা যায়। নতুন সেশনে এই কাঠামো হালনাগাদ করে নিলে পুরোনো পরিকল্পনা আর বিভ্রান্তি তৈরি করে না।", en: "This page decides which subjects are taught in a given class and in what order they progress. Subjects are arranged along with their sequence so the teaching plan for the whole session stays clear. The order can be changed or a subject dropped when required. Teachers and planners follow this structure when preparing their work. Refreshing the structure for a new session prevents confusing carry-over." },
  "/dashboard/admin/notifications": { bn: "এই ভূমিকার জন্য পাঠানো ঘোষণা ও সতর্কবার্তার তালিকা এই পাতায় জমা থাকে। প্রতিটি বার্তা খুলে বিস্তারিত পড়া যায় এবং কোনটি নতুন আর কোনটি আগে পড়া হয়েছে তা আলাদা করে বোঝা যায়। জরুরি ঘোষণা যাতে চোখ এড়িয়ে না যায়, সেদিকেও লক্ষ্য রাখা যায়। নিজের ভূমিকার প্রাসঙ্গিক সব বার্তা এক জায়গায় পেতে এই পাতা কাজে লাগে। ঘোষণা পাঠানোর সময় কোন ভূমিকা লক্ষ্য করা হয়েছে, তা সারিতে দেখা যায়। পুরোনো বার্তা মুছে না গিয়ে ইতিহাস হিসেবে জমা থাকে।", en: "Announcements and alerts issued for this role collect on this page. Each message can be opened and read in full, and new items are distinguishable from ones already read. Attention can be kept on urgent announcements so they do not slip past. The page is the single place to receive everything relevant to one's own role. Each item notes which role it targets, and older messages stay in place as history." },
  "/dashboard/admin/profile": { bn: "লগইন করা ব্যক্তির নিজের অ্যাকাউন্ট তথ্য এই পাতায় দেখা যায়। নাম, যোগাযোগের বিবরণ ও অন্যান্য পরিচিতি নিজেই সম্পাদনা করার সুযোগ থাকে, তাই তথ্য বদলালে অফিসে আলাদা করে জানাতে হয় না। অন্য কারও তথ্য এখানে দেখা যায় না, শুধু নিজেরটাই। নিজের অ্যাকাউন্ট হালনাগাদ ও সঠিক রাখতে প্রত্যেকে এই পাতা ব্যবহার করেন। যোগাযোগের নম্বর বদলালে তা সঙ্গে সঙ্গেই নিজের রেকর্ডে দেখা যায়। যেসব তথ্য নিজে বদলানো যায় না, সেগুলোর জন্য অফিসে অনুরোধ করতে হয়।", en: "The logged-in person's own account details appear on this page. Name, contact information and other identifiers can be edited directly, so a change of details does not have to be reported to the office. No one else's information is shown here, only one's own. Everyone uses this page to keep their account accurate and up to date. Details a person cannot change themselves have to be requested from the office." },
  "/dashboard/admin/reports/institution-analytics": { bn: "নির্বাচিত সময়ের জন্য পুরো প্রতিষ্ঠানের প্রবণতা এই প্রতিবেদনে দেখা যায়। সময়সীমা বদলে আগের কোনো মাস বা সেশনের সঙ্গে বর্তমান অবস্থার তুলনা করা যায়। কোন দিক উন্নত হচ্ছে আর কোথায় স্থবিরতা আছে, তা সংখ্যার মাধ্যমে স্পষ্ট হয়। প্রতিষ্ঠান পরিচালনার সিদ্ধান্ত নেওয়ার আগে এই প্রতিবেদন দেখে পরিস্থিতি যাচাই করা হয়। কোন সময়ে কোন পরিবর্তন ঘটেছে, তা প্রবণতার রেখা ধরে দেখা যায়। প্রতিষ্ঠানের পুরো চিত্র এক জায়গায় পাওয়া যায়, তাই আলাদা করে হিসাব করতে হয় না।", en: "Trends for the whole institution over a selected period appear in this report. Changing the period allows the present position to be compared with an earlier month or session. Figures make it clear which areas are improving and where things have stalled. The report is reviewed before decisions on running the institution are taken. The whole picture sits in one place, so separate calculations are not needed." },
  "/dashboard/admin/reports/intervention-plans": { bn: "শিক্ষার্থীদের জন্য তৈরি সহায়তা পরিকল্পনার তালিকা এই প্রতিবেদনে দেখা যায়। কোন পরিকল্পনা এখনো খোলা, কোনটি চলমান এবং কোনটি সমাপ্ত হয়েছে, তা আলাদা করে বোঝা যায়। প্রতিটি পরিকল্পনা কাদের জন্য এবং কী উদ্দেশ্যে তৈরি, তাও দেখা যায়। কোন সহায়তা কাজ করছে আর কোনটি থেমে আছে, তা যাচাই করতে প্রশাসন এই তালিকা ব্যবহার করে। প্রতিটি পরিকল্পনায় কে দায়িত্বে আছেন এবং কী ধরনের সহায়তা দেওয়া হচ্ছে, তা দেখা যায়। সমাপ্ত পরিকল্পনা আলাদা রাখায় চলমান কাজগুলো স্পষ্ট থাকে।", en: "Support plans created for students are listed in this report. It separates plans that are still open, those under way, and those completed. It also shows who each plan was made for and with what aim. The administration uses this list to check which support is working and which has stalled. Separating completed plans keeps the ones still running clearly in view." },
  "/dashboard/admin/reports/mastery-records": { bn: "প্রত্যেক শিক্ষার্থীর টপিক-ভিত্তিক মাস্টারি রেকর্ড এই প্রতিবেদনে রাখা হয়। কোন শিক্ষার্থী কোন টপিকে কতটা দখল অর্জন করেছে, তা এক জায়গা থেকে দেখা যায়। শিক্ষার্থী ধরে বা টপিক ধরে তালিকা দেখে দুর্বলতা চিহ্নিত করা যায়। যাদের অতিরিক্ত সহায়তা দরকার, তাদের বেছে নিতে শিক্ষক ও প্রশাসন এই রেকর্ড ব্যবহার করেন। একই শিক্ষার্থীর বিভিন্ন টপিকের অবস্থা পাশাপাশি রেখে সামগ্রিক দখল বোঝা যায়। সময়ের সঙ্গে মাস্টারি বদলালে সেই পরিবর্তনও এখানে ধরা পড়ে।", en: "Topic-level mastery records for every student are kept in this report. It shows in one place how much of each topic a given learner has secured. The list can be read by student or by topic to identify weaknesses. Teachers and the administration use these records to pick out those who need extra support. Placing a student's topics side by side shows overall command of the subject." },
  "/dashboard/admin/reports/parent-reach": { bn: "কতজন অভিভাবক প্ল্যাটফর্মের সঙ্গে যুক্ত হয়েছেন এবং কতজন নিয়মিত অন্তর্দৃষ্টি পড়ছেন, তা এই প্রতিবেদনে দেখা যায়। যুক্ত হওয়া আর সত্যিই পড়া, এই দুইয়ের পার্থক্যও এখানে ধরা পড়ে। যেসব অভিভাবক এখনো যুক্ত হননি, তাঁদের দিকে আলাদা নজর দেওয়া যায়। অভিভাবকদের সঙ্গে যোগাযোগ কার্যকর হচ্ছে কি না, তা বুঝতে প্রশাসন এই প্রতিবেদন ব্যবহার করে। কোন ক্লাসের অভিভাবকরা বেশি যুক্ত হয়েছেন, তা তুলনা করে দেখা যায়। যুক্ত হওয়ার হার কম হলে সেখানে যোগাযোগ বাড়ানোর উদ্যোগ নেওয়া যায়।", en: "This report shows how many guardians have joined the platform and how many read the insights regularly. The gap between joining and actually reading is visible here as well. Guardians who have not yet connected can be given separate attention. The administration uses the report to judge whether communication with families is working. Where the joining rate is low, communication can be stepped up." },
  "/dashboard/admin/reports/parent-weekly-insights": { bn: "প্রত্যেক অভিভাবক সপ্তাহে যে অন্তর্দৃষ্টি পেয়েছেন, তার রেকর্ড এই প্রতিবেদনে থাকে। কোন অভিভাবক কী তথ্য পেয়েছেন এবং সেটি কবে পাঠানো হয়েছে, তা দেখা যায়। কেউ বার্তা না পেলে বা পেতে দেরি হলে সেটিও ধরা পড়ে। অভিভাবকদের কাছে তথ্য সঠিকভাবে পৌঁছাচ্ছে কি না, তা নিশ্চিত করতে প্রশাসন এই প্রতিবেদন ব্যবহার করে। সপ্তাহে কতজন অভিভাবক অন্তর্দৃষ্টি পেয়েছেন, তার হিসাবও এই তালিকা থেকেই আসে। একই অভিভাবক বারবার বাদ পড়লে সেটি আলাদা করে লক্ষ্য করা যায়।", en: "A record of the weekly insights each guardian received is kept in this report. It shows what information went to which guardian and when it was sent. Missing or delayed messages become visible here as well. The administration uses the report to confirm that information reaches families as intended. A guardian repeatedly left out becomes noticeable in this list." },
  "/dashboard/admin/reports/safety-events": { bn: "রেকর্ড করা প্রতিটি এআই নিরাপত্তা ঘটনা এই প্রতিবেদনে দেখা যায়, নতুনটি সবার আগে। প্রতিটি ঘটনার ধরন ও সময় দেখে বোঝা যায় কী ধরনের সমস্যা কোথায় তৈরি হচ্ছে। বারবার একই ধরনের ঘটনা ঘটলে সেদিকে আলাদা নজর দেওয়া যায়। নিরাপত্তা ব্যবস্থা কতটা কাজ করছে, তা মূল্যায়ন করতে প্রশাসন এই তালিকা ব্যবহার করে। ঘটনার সময় ও ধরন পাশাপাশি দেখে বোঝা যায় কোনো নির্দিষ্ট সময়ে সমস্যা বেড়েছে কি না। একই ধরনের ঘটনা বারবার এলে নিয়ম বা ফিল্টার কঠোর করার কথা ভাবা যায়।", en: "Every recorded AI safety event appears in this report, with the newest at the top. The type and timing of each event show what kind of problem is arising and where. Repeated events of the same kind can then be given closer attention. The administration uses this list to judge whether the safety measures are holding. Repeated events of one kind suggest the rules or filters need to be tightened." },
  "/dashboard/admin/reports/teacher-activity": { bn: "প্রতিটি শিক্ষক প্ল্যাটফর্ম কতটা সক্রিয়ভাবে ব্যবহার করছেন, তা এই প্রতিবেদনে দেখা যায়। কার্যক্রমের পরিমাণ দেখে বোঝা যায় কে নিয়মিত কাজ করছেন আর কে পিছিয়ে আছেন। প্রয়োজনে নির্দিষ্ট শিক্ষকের অবস্থা আলাদা করে যাচাই করা যায়। প্রয়োজনে সহায়তা বা প্রশিক্ষণ দেওয়ার আগে এই প্রতিবেদন ভিত্তি হিসেবে কাজ করে। কোন শিক্ষক কোন অংশ বেশি ব্যবহার করছেন, তা ধরন দেখে বোঝা যায়। একসঙ্গে সব শিক্ষকের অবস্থা দেখে প্রতিষ্ঠানের সার্বিক ব্যবহারের চিত্র পাওয়া যায়।", en: "This report shows how actively each teacher uses the platform. The volume of activity indicates who is working regularly and who has fallen behind. The position of a particular teacher can be examined separately when needed. The report serves as a basis before support or training is offered. Seeing all teachers together gives the overall picture of platform use." },
  "/dashboard/admin/roles": { bn: "ভূমিকা ও অনুমতির বণ্টন এই পাতায় নির্ধারিত হয়। কোন ভূমিকা কোন অংশ দেখতে পারবে এবং কী কাজ করতে পারবে, তা ঠিক করা যায়। প্রয়োজনে কোনো ভূমিকার অনুমতি বাড়ানো বা কমানো যায়, যাতে প্রত্যেকে কেবল নিজের দায়িত্বের অংশেই পৌঁছায়। প্রতিষ্ঠানের তথ্য সুরক্ষিত রাখতে প্রশাসন এই বণ্টন নিয়মিত পর্যালোচনা করে। কোন ভূমিকায় কে আছেন, তা দেখে অনুমতি বণ্টন যাচাই করা যায়। স্পর্শকাতর অংশ কেবল দায়িত্বপ্রাপ্ত ভূমিকার হাতেই রাখা যায়।", en: "Roles and the permissions attached to them are defined on this page. It sets which part of the system a role may see and which actions it may perform. Permissions for a role can be widened or narrowed so that each person reaches only the area their duty covers. The administration reviews this allocation regularly to keep institutional data protected. Sensitive sections stay with the roles that are responsible for them." },
  "/dashboard/admin/sections": { bn: "প্রতিটি ক্লাসের ভেতরের সেকশনগুলো এই পাতায় পরিচালিত হয়। প্রতিটি সেকশনের নাম, ধারণক্ষমতা এবং কোন শিক্ষক ক্লাস টিচার হিসেবে দায়িত্বে আছেন তা দেখা যায়। প্রয়োজনে নতুন সেকশন খোলা, ধারণক্ষমতা বদলানো বা ক্লাস টিচার বদলানো যায়। শিক্ষার্থী বণ্টন ও শ্রেণিকক্ষ ব্যবস্থাপনার ভিত্তি এই তথ্যের ওপরই দাঁড়ায়। কোন সেকশনে কতজন শিক্ষার্থী আছেন, তা দেখে ধারণক্ষমতার সঙ্গে মিলিয়ে নেওয়া যায়। সেকশনপ্রতি শিক্ষার্থীর চাপ সমান রাখতে এই তথ্য কাজে লাগে।", en: "Sections that sit inside each class are managed on this page. For every section the name, seating capacity and the teacher acting as class teacher are visible. New sections can be opened, capacity revised, or the class teacher changed as required. Student distribution and day-to-day classroom management both rest on this information. Filling against capacity can then be balanced across sections." },
  "/dashboard/admin/settings": { bn: "প্রতিষ্ঠানের মূল সেটিংস এই পাতায় রাখা হয়। প্রতিষ্ঠানের পরিচিতি, চলতি সেশন, গ্রেডিং পদ্ধতি ও যোগাযোগের তথ্য এখান থেকে দেখা ও সম্পাদনা করা যায়। কোনো পরিবর্তন সেভ করলে তার প্রভাব পুরো সিস্টেমে ছড়িয়ে পড়ে, তাই সতর্কভাবে করা উচিত। প্রশাসনিক দায়িত্বে থাকা ব্যক্তিরা প্রতিষ্ঠানের কার্যক্রম সঠিকভাবে চালাতে এই সেটিংস ব্যবহার করেন। গ্রেডিং পদ্ধতি বদলালে নম্বর কীভাবে দেখাবে, তা আগেই বুঝে নেওয়া ভালো।", en: "The core settings of the institution live on this page. Identity details, the running session, the grading scheme and contact information can all be reviewed and edited here. Any saved change carries through the whole system, so it should be made deliberately. Staff holding administrative responsibility use these settings to keep the institution running correctly. It is worth checking the grading change before saving." },
  "/dashboard/admin/students": { bn: "এই পাতায় প্রতিষ্ঠানের সব শিক্ষার্থীর পূর্ণ তালিকা থাকে। ভর্তি নম্বর, ক্লাস, সেকশন, রোল ও অভিভাবকের তথ্য দিয়ে প্রতিটি রেকর্ড তৈরি বা সম্পাদনা করা যায়। ক্লাস বা সেকশন ধরে তালিকা ছেঁকে নির্দিষ্ট শিক্ষার্থী দ্রুত খুঁজে নেওয়া সহজ। রেকর্ড সেভ করলেই শিক্ষার্থীর লগইন তৈরি হয়ে যায়, ফলে সে নিজের ড্যাশবোর্ডে ঢুকতে পারে। নতুন ভর্তি এবং পুরোনো তথ্য হালনাগাদের কাজ মূলত অফিস এই পাতাতেই সম্পন্ন করে। প্রয়োজনে পুরোনো রেকর্ড খুলে আগের তথ্য যাচাই করাও যায়।", en: "This page holds the master list of every student enrolled in the institution. Each record carries the admission number, class, section, roll number and guardian details, and can be created or edited from here. The list narrows by class or section so a single student is found quickly. Saving a record also creates the student login, letting that student sign in straight away. The office uses it for admissions and updates." },
  "/dashboard/admin/subjects": { bn: "রুটিন, কারিকুলাম ও অ্যাসেসমেন্টে যে বিষয়গুলো ব্যবহৃত হয়, তার তালিকা এখানে রাখা হয়। প্রতিটি বিষয়ের নাম ও সংক্ষিপ্ত পরিচিতি দেখা যায়, আর দরকার হলে নতুন বিষয় যোগ বা পুরোনো বিষয় সংশোধন করা যায়। একই বিষয় যাতে দুইবার না থাকে, সেদিকেও খেয়াল রাখা যায়। বিষয়ভিত্তিক সব হিসাব ও প্রতিবেদন এই তালিকার ওপর নির্ভর করে। বিষয়ের নাম বদলালে তা রুটিন ও অ্যাসেসমেন্টেও একসঙ্গে বদলে যায়। কোন ক্লাসে বিষয়টি পড়ানো হয়, তাও দেখে নেওয়া যায়।", en: "The subjects used in routines, curriculum and assessments are listed here. Each subject appears with its name and a short identifier, and subjects can be added or existing ones corrected as needed. Care can be taken that the same subject is not entered twice. Every subject-wise calculation and report in the system draws on this list. A subject can also be traced to the classes where it is taught." },
  "/dashboard/admin/teacher-class-assignments": { bn: "কোন শিক্ষক কোন ক্লাস ও কোন বিষয় নেবেন, তা এই পাতা থেকে ঠিক করা হয়। বরাদ্দ সেভ হলে সেই শিক্ষকের শিক্ষার্থী-তালিকা স্বয়ংক্রিয়ভাবে তৈরি হয়, তাই তিনি কেবল নিজের ক্লাসের শিক্ষার্থীদেরই দেখতে পান। ভুল বরাদ্দ থাকলে সংশোধন করা যায় এবং প্রয়োজনে বরাদ্দ সরিয়ে নেওয়া যায়। একাডেমিক রুটিন ও পাঠদান বণ্টনের ভিত্তি তৈরি হয় এখানেই। কোন শিক্ষকের কাছে কত ক্লাস আছে, তা দেখে কাজের চাপও বোঝা যায়। একই ক্লাসে দুই শিক্ষক বরাদ্দ হয়ে গেলে সেটিও এখানেই চোখে পড়ে।", en: "This page fixes which teacher takes which class and subject. Once an assignment is saved, that teacher's student list is built automatically, so the teacher only sees learners from their own classes. Wrong assignments can be corrected and an assignment withdrawn when needed. This is where the basis of the academic routine and teaching load is set. It also shows how many classes sit with each teacher, making workload visible." },
  "/dashboard/admin/teachers": { bn: "শিক্ষকদের তথ্য এখানে এক জায়গায় সংরক্ষিত থাকে। প্রতিটি রেকর্ডে শিক্ষকের নাম, যোগাযোগের বিবরণ এবং তিনি কোন বিষয় পড়ান ও কোন ক্লাসে বরাদ্দ আছেন তা দেখা যায়। প্রয়োজনে নতুন শিক্ষক যোগ করা, পুরোনো তথ্য সংশোধন করা বা তালিকা থেকে নির্দিষ্ট শিক্ষক খোঁজা যায়। প্রতিষ্ঠানের শিক্ষক-তালিকা হালনাগাদ রাখতে প্রশাসন এই পাতা ব্যবহার করে। যোগাযোগের তথ্য বদলালে তা এই রেকর্ডেই হালনাগাদ করা যায়। তালিকাটি শিক্ষকদের নাম ধরে সাজানো থাকে, তাই খুঁজতে ঝামেলা হয় না।", en: "Teacher information is kept in one place here. Each record shows the teacher's name, contact details, the subjects taught and the classes already assigned. New teachers can be added, existing entries corrected, and a particular teacher located from the list. The administration uses this page to keep the faculty directory accurate and current. Contact details can be corrected right in the record." },
  "/dashboard/admin/users": { bn: "যাদের সিস্টেমে লগইন আছে, তাদের তালিকা এই পাতায় দেখা যায়। নতুন লগইন তৈরি করা, অপ্রয়োজনে লগইন বন্ধ করা এবং প্রত্যেকের ভূমিকা কী তা যাচাই করা এখান থেকেই হয়। কে শিক্ষক, কে শিক্ষার্থী বা কে অভিভাবক, তা এক নজরে বোঝা যায়। প্রতিষ্ঠানের অ্যাকাউন্ট ব্যবস্থাপনা পরিষ্কার ও নিয়ন্ত্রিত রাখতে প্রশাসন এই পাতা ব্যবহার করে। ভুল করে কেউ লগইন পেলে তা বন্ধ করে দেওয়া যায়। কোন অ্যাকাউন্ট কোন ভূমিকায় আছে, তা দেখে ভূমিকা বদলানোও সহজ হয়।", en: "Everyone who has a login to the system is listed on this page. New logins are created here, logins are switched off when no longer needed, and each person's role can be checked. It shows at a glance who is a teacher, a student or a guardian. The administration uses this page to keep account management clean and controlled. A login created by mistake can be disabled, and roles are easy to change once visible." },
  "/dashboard/ai-safety-reviewer/ai-data": { bn: "এআই-সাইড ডেটাসেট এবং কোন সেশনে তা কীভাবে ব্যবহার হয়েছে তার বিবরণ এখানে পাওয়া যায়। প্রতিটি ডেটাসেটের উদ্দেশ্য ও সংশ্লিষ্ট সেশন মিলিয়ে দেখা যায়, ফলে কোথায় কী তথ্য ঢুকেছে তা বোঝা যায়। কোনো ব্যবহার নিয়মের বাইরে মনে হলে তা চিহ্নিত করে পর্যালোচনা করা যায়। সামগ্রিকভাবে এটি এআই ব্যবহারের স্বচ্ছতা ও জবাবদিহি রক্ষা করে। কোন সেশনে কী ধরনের প্রশ্ন এসেছে তা মিলিয়ে দেখলে বোঝা যায় ডেটা ব্যবহারের ধরন প্রত্যাশিত সীমার ভেতরেই আছে কি না।", en: "Describes the AI-side datasets and shows how each has been used across sessions. Matching a dataset to its stated purpose and to the sessions that drew on it makes it possible to see where particular information entered. Any use that looks outside the rules can be flagged and examined on that basis. Overall this page is what keeps AI use transparent and accountable." },
  "/dashboard/ai-safety-reviewer/ai-pathshala/ai-tutor": { bn: "এটি একটি চ্যাটভিত্তিক টিউটর, যা কেবল অনুমোদিত লেসন কনটেন্ট থেকেই উত্তর দেয়। শিক্ষার্থী প্রশ্ন লিখলে টিউটর সেই লেসনের ভেতরের তথ্যের ভিত্তিতে ব্যাখ্যা দেয়, তাই উত্তরগুলো পাঠ্যক্রমের বাইরে গিয়ে বিভ্রান্তি তৈরি করে না। আলাপের ধারা ধরে আগের উত্তরের সূত্রে নতুন প্রশ্ন করা যায় এবং বোঝা না গেলে আরও সহজ ভাষায় ব্যাখ্যা চাওয়া যায়। এতে পড়ার সময় তাৎক্ষণিক সহায়তা মেলে, তবে তা সর্বদা নির্ধারিত পাঠসীমার ভেতরেই থাকে।", en: "This chat-based tutor answers only from approved lesson content. A learner types a question and gets an explanation drawn from that lesson's material, so replies stay inside the curriculum. Follow-up questions can build on the earlier answer, or ask for simpler wording. Help arrives while reading, bounded by the approved lesson scope." },
  "/dashboard/ai-safety-reviewer/ai-pathshala/assessments": { bn: "এই পাতায় অ্যাসেসমেন্টের তালিকা এবং প্রত্যেক শিক্ষার্থীর প্রাপ্ত নম্বর দেখা যায়। কোন অ্যাসেসমেন্ট কখন নেওয়া হয়েছে, কে কত নম্বর পেয়েছে এবং কোন প্রশ্নে দুর্বলতা দেখা গেছে তা একসঙ্গে পাওয়া যায়। শিক্ষক এই তথ্য দেখে বুঝতে পারেন কোন বিষয়টি পুরো শ্রেণির জন্য কঠিন হয়েছে এবং কোথায় আলাদা সহায়তা দরকার। একই শিক্ষার্থীর ধারাবাহিক ফলাফল মিলিয়ে দেখলে অগ্রগতি বা পিছিয়ে পড়ার ধরনও স্পষ্ট হয়।", en: "The assessment list and each learner's marks are shown here. The page gathers when an assessment was held, how each student scored, and which questions showed weakness. A teacher reading it can tell which topic was hard for the whole class and where individual support is needed. One learner's results across assessments also reveal progress or a slide." },
  "/dashboard/ai-safety-reviewer/ai-pathshala/lesson-planner": { bn: "এই পাতায় দিনভিত্তিক লেসন প্ল্যান তৈরি ও দেখা যায়, যা শিক্ষক ক্লাসে সরাসরি অনুসরণ করতে পারেন। প্রতিটি প্ল্যানে কোন দিনে কোন বিষয় পড়ানো হবে, কত সময় লাগবে এবং কোন অনুশীলন দেওয়া হবে তা সাজানো থাকে। শিক্ষক প্রয়োজন অনুযায়ী ক্রম বদলাতে বা কোনো দিনের অংশ বাদ দিতে পারেন, যাতে শ্রেণির প্রকৃত অগ্রগতির সঙ্গে প্ল্যান মিলে যায়। আগে থেকে পরিকল্পনা থাকলে ক্লাসের সময় নষ্ট না হয়ে নির্ধারিত লক্ষ্যে এগোনো সহজ হয়।", en: "Day-by-day lesson plans are built and viewed here, ready for a teacher to follow in class. Each plan sets which topic falls on which day, how much time it takes, and what practice follows. The teacher can reorder items or drop a day's portion to match how the class is really progressing. Settling the sequence beforehand keeps class time for teaching." },
  "/dashboard/ai-safety-reviewer/ai-pathshala/lessons": { bn: "এই পাতায় ক্লাস ও বিষয় অনুযায়ী সাজানো কাঠামোবদ্ধ এআই লেসনগুলো দেখা যায়। প্রতিটি লেসনে কী শেখানো হবে, কোন ক্লাসের জন্য এটি তৈরি এবং পাঠের ক্রমে এটি কোথায় আছে তা উল্লেখ থাকে। ব্যবহারকারী নিজের ক্লাসের লেসন বেছে নিয়ে পড়া শুরু করতে পারেন এবং আগের বা পরের লেসনে সহজেই যেতে পারেন। এই কাঠামো অনুসরণ করলে পড়াশোনা এলোমেলো না হয়ে ধাপে ধাপে এগোয়, আর কোনো বিষয় বাদ পড়ার ঝুঁকিও কমে। লেসনের ক্রম মেনে চললে কোনো গুরুত্বপূর্ণ বিষয় বাদ পড়ে না।", en: "Structured AI lessons are listed here, organised by class and subject. Each lesson shows what it covers, which class it was written for, and where it sits in the sequence. A user picks the lessons for their class, starts reading, and moves to the previous or next one. Following that order keeps study moving in step instead of jumping between topics. Sticking to the order means no important topic gets skipped." },
  "/dashboard/ai-safety-reviewer/ai-pathshala/progress": { bn: "এই পাতায় লগইন করা ব্যবহারকারীর টপিকভিত্তিক মাস্টারি অগ্রগতি দেখানো হয়। কোন টপিকে তিনি কতটা এগিয়েছেন এবং কোনটি এখনো সম্পূর্ণ আয়ত্তে আসেনি তা স্পষ্টভাবে বোঝা যায়। এই চিত্র দেখে বোঝা যায় কোথায় বেশি সময় দিতে হবে এবং কোন বিষয়গুলো ইতিমধ্যেই ভালোভাবে আয়ত্ত হয়েছে। নিজের অগ্রগতি নিয়মিত দেখলে পড়ার পরিকল্পনা বাস্তব অবস্থার সঙ্গে মিলিয়ে নেওয়া সহজ হয়। কোন টপিকে সময় দিলে সবচেয়ে বেশি লাভ হবে তাও এখান থেকে বোঝা যায়।", en: "Topic-wise mastery progress for the signed-in user appears on this page. It shows how far each topic has come and which ones are not yet mastered. Reading it shows where more time is worth spending and what is already in good shape. Checking regularly keeps a study routine aligned with how things actually stand. It also indicates which topic would repay the most time invested." },
  "/dashboard/ai-safety-reviewer/ai-pathshala/quizzes": { bn: "এই পাতায় এআই দিয়ে তৈরি করা কুইজগুলো দেখা যায় এবং সেগুলোতে অংশ নেওয়া যায়। প্রতিটি কুইজ নির্দিষ্ট লেসন বা টপিকের ওপর তৈরি, তাই প্রশ্নগুলো পড়ানো বিষয়ের সঙ্গেই সম্পর্কিত থাকে। শিক্ষার্থী উত্তর জমা দিলেই যাচাই হয়ে ফলাফল দেখানো হয়, ফলে কোথায় ভুল হয়েছে তা সঙ্গে সঙ্গে বোঝা যায়। ফলাফল দেখে দুর্বল টপিক চিহ্নিত করা যায় এবং সেগুলোতে পরে আরও মনোযোগ দেওয়া যায়। ফলাফল দেখে শিক্ষার্থী নিজেই বুঝতে পারেন কোন অংশে অনুশীলন দরকার।", en: "AI-generated quizzes are listed here and can be attempted directly. Each is built around a particular lesson or topic, so questions stay tied to what was taught. Submitting answers triggers checking and shows the result at once, making mistakes visible immediately. Those results then point to the topics that need more work later. Learners can see for themselves which part needs more practice." },
  "/dashboard/ai-safety-reviewer/ai-pathshala/study-plan": { bn: "এই পাতায় সবচেয়ে দুর্বল টপিকগুলোর ওপর ভিত্তি করে তৈরি ব্যক্তিগত স্টাডি প্ল্যান দেখা যায়। কোথায় সবচেয়ে বেশি ঘাটতি আছে তা চিহ্নিত করে সেই বিষয়গুলো আগে রাখা হয়, যাতে সীমিত সময়ে সবচেয়ে বেশি উন্নতি হয়। ব্যবহারকারী প্ল্যান অনুসরণ করে এগোলে অগ্রগতি হালনাগাদ হয় এবং দুর্বলতা কমলে প্ল্যানের ক্রমও বদলে যায়। এতে পড়াশোনা অনুমাননির্ভর না হয়ে প্রকৃত ফলাফলের ভিত্তিতে পরিচালিত হয়। প্ল্যান দেখে প্রতিদিন কী পড়তে হবে তা আগেই ঠিক করা যায়।", en: "A personal study plan built from the weakest topics is presented here. The largest gaps are identified and placed first, so limited time goes where it improves results most. As the user follows the plan, progress updates and the order shifts once weak spots improve. Study then follows measured performance, not guesswork about what to revise. The plan settles what to read each day in advance." },
  "/dashboard/ai-safety-reviewer/audit-history": { bn: "এই পাতায় এআই নিরাপত্তা সংক্রান্ত সব পদক্ষেপ কালানুক্রমে সাজানো থাকে। কোন পর্যালোচক কখন কোন ঘটনা বা কেসে কী সিদ্ধান্ত নিয়েছেন, তা একটানা ধারায় দেখা যায়। এটি অভ্যন্তরীণ যাচাই ও জবাবদিহিতার জন্য ব্যবহার করা হয়, কারণ প্রতিটি পরিবর্তনের পেছনে একজন নির্দিষ্ট ব্যক্তি ও সময় খুঁজে পাওয়া যায়। কোনো সিদ্ধান্ত পরে প্রশ্ন ওঠে উঠলে এই ইতিহাস দেখে তার সূত্র ও প্রেক্ষাপট দ্রুত মিলিয়ে নেওয়া যায়। এই ধারা একটানা থাকায় আলাদা আলাদা নোট মিলিয়ে দেখতে হয় না।", en: "All AI safety actions are laid out here in chronological order. The page shows which reviewer decided what, on which case, and when. Internal checks and accountability rely on it, since every change traces to a named person and a point in time. If a decision is questioned later, the origin and context are found here. The trail reads as one continuous sequence rather than scattered notes." },
  "/dashboard/ai-safety-reviewer/escalations": { bn: "যেসব ঘটনা ঊর্ধ্বতন পর্যালোচকের কাছে পাঠানো হয়েছে তার প্রতিটি এখানে কারণসহ দেখা যায়। প্রতিটি সারিতে এসক্যালেট করা ঘটনাটি, পাঠানোর কারণ, কে পাঠিয়েছেন এবং বর্তমানে তা কোন অবস্থায় আছে তা উল্লেখ থাকে। ঊর্ধ্বতন পর্যালোচক এই তালিকা থেকেই বিষয়টি গ্রহণ করে সিদ্ধান্ত দেন অথবা আরও তথ্য চেয়ে ফেরত পাঠান। এতে কোন সিদ্ধান্ত নিম্ন স্তরে নেওয়া যায়নি এবং কেন তা স্পষ্ট থাকে। এসক্যালেশনের কারণ লিখিত থাকায় পরবর্তী সিদ্ধান্ত দ্রুত হয়।", en: "Every event passed up to a senior reviewer appears here with the reason it was sent. Each row names the event, the reason, the reviewer who raised it, and where it now stands. The senior reviewer takes the case from this list, decides it, or returns it for more information. Recording the reasons shows which decisions could not be settled at first level. Written reasons also make the next decision faster." },
  "/dashboard/ai-safety-reviewer/flagged-content": { bn: "এখানে পর্যালোচনার জন্য ফ্ল্যাগ করা এআই বার্তা ও উত্তরগুলো এক জায়গায় দেখা যায়। প্রতিটি এন্ট্রিতে ফ্ল্যাগ করা বার্তার মূল লেখা, কোন প্রশ্নের উত্তরে তা এসেছে এবং কেন এটি ফ্ল্যাগ হয়েছে তা থাকে। পর্যালোচক কনটেন্ট পড়ে সিদ্ধান্ত নেন এটি গ্রহণযোগ্য, সংশোধনযোগ্য নাকি ঊর্ধ্বতনে পাঠানো প্রয়োজন। ফ্ল্যাগ হওয়া কনটেন্টের ধরন বুঝে পরবর্তী সময়ে নীতিমালা বা প্রশিক্ষণে কী উন্নতি দরকার তাও নির্ধারণ করা যায়।", en: "Flagged AI messages and responses awaiting review are collected here. Each entry carries the original text, the prompt it answered, and the reason it was flagged. The reviewer reads it and decides whether it is acceptable, needs correction, or goes to a senior reviewer. The grouped view also shows which kinds of content keep getting flagged." },
  "/dashboard/ai-safety-reviewer/investigations": { bn: "এই পাতায় চলমান তদন্তগুলো এবং প্রতিটির দায়িত্বপ্রাপ্ত ব্যক্তি ও এ পর্যন্ত প্রাপ্ত ফলাফল দেখা যায়। কোনো ঘটনা গুরুতর হলে সেটি তদন্তে রূপ নেয়, আর এখানে তার অগ্রগতি, যুক্ত হওয়া প্রমাণ ও নেওয়া সিদ্ধান্ত একসঙ্গে থাকে। পর্যালোচক নিজের দায়িত্বে থাকা তদন্ত খুলে নোট যোগ করতে এবং ফলাফল লিপিবদ্ধ করতে পারেন। ফলে একাধিক ব্যক্তি একসঙ্গে কাজ করলেও কোন তদন্ত কোথায় আছে তা স্পষ্ট থাকে। তদন্ত শেষ হলে তার ফলাফল কেসের নথিতেই থেকে যায়।", en: "Ongoing investigations are listed here with who owns each one and the outcome reached so far. A serious event becomes an investigation, and its progress, evidence and findings sit together on this page. A reviewer can open their own cases, add notes, and write up the result. Ownership and current status stay clear even when several people work the same queue. Closing an investigation keeps its findings with the case record." },
  "/dashboard/ai-safety-reviewer/local-data": { bn: "এআই স্কুল-স্থানীয় কোন কোন ডেটা পড়তে পারে তার তালিকা এখানে দেখা যায়। প্রতিটি উৎসের ধরন ও ব্যবহারের উদ্দেশ্য মিলিয়ে দেখা যায়, যাতে প্রয়োজনের বাইরে কিছু পড়া না হয়। কোন ডেটা অনুমোদিত আর কোনটি বাদ দেওয়া হয়েছে তা স্পষ্ট থাকে। তালিকা যাচাই করে বোঝা যায় সীমা ঠিক আছে কি না এবং অপ্রয়োজনীয় প্রবেশাধিকার বন্ধ করা দরকার কি না। কোন সীমা কে অনুমোদন করেছে এবং কখন তা বদলানো হয়েছে তা দেখে পরিবর্তনের ইতিহাসও অনুসরণ করা যায়।", en: "Lists the school-local data the AI is permitted to read. Each source is shown with its type and the purpose it serves, so access stays tied to a stated need rather than open by default. It is clear which data is approved and which has been excluded. Checking the list shows whether the boundaries still hold and whether any access should be withdrawn." },
  "/dashboard/ai-safety-reviewer/notifications": { bn: "এই পাতায় এআই নিরাপত্তা সংক্রান্ত সতর্কবার্তা ও কেসভিত্তিক নোটিফিকেশন জমা হয়। নতুন ঘটনা রেকর্ড হলে, কোনো কেস এসক্যালেট হলে বা পর্যালোচনার জন্য কিছু অপেক্ষা করলে এখানে জানানো হয়। পর্যালোচক তালিকা দেখে প্রয়োজনীয় বিষয় দ্রুত খুঁজে নেন এবং সংশ্লিষ্ট কেসে গিয়ে কাজ শুরু করতে পারেন। পড়া হয়ে গেলে নোটিফিকেশন আলাদা হয়ে যায়, ফলে কোনটি এখনো দেখা হয়নি তা সহজেই বোঝা যায়। নোটিফিকেশন দেখে দ্রুত পদক্ষেপ নেওয়া যায়, ফলে জরুরি বিষয় ফাঁকি পড়ে না।", en: "Safety alerts and case notifications for this role collect on this page. It reports when a new event is recorded, when a case is escalated, and when items are waiting for review. The reviewer scans the list and moves into the related case to act. Read notifications are separated from pending ones, so what is unseen stays obvious. Acting on the list promptly keeps urgent items from slipping." },
  "/dashboard/ai-safety-reviewer/policies": { bn: "এই পাতায় সেই এআই নিরাপত্তা নীতিমালাগুলো থাকে যা অনুসরণ করে পর্যালোচনার সিদ্ধান্ত নেওয়া হয়। প্রতিটি নীতিমালার উদ্দেশ্য, কোন কোন ক্ষেত্রে তা প্রযোজ্য এবং সিদ্ধান্তের সময় কীভাবে উল্লেখ করতে হবে তা এখানে দেখা যায়। পর্যালোচক সন্দেহ হলে সিদ্ধান্তের আগে সংশ্লিষ্ট নীতিমালা পড়ে নিতে পারেন, যাতে একই ধরনের ঘটনায় সবাই একই মানদণ্ড প্রয়োগ করেন। এতে সিদ্ধান্তগুলো ব্যক্তিগত মতের বদলে লিখিত নীতির ভিত্তিতে দাঁড়ায়। নীতিমালা একভাবে উল্লেখ হলে পরে সিদ্ধান্ত পর্যালোচনা করাও সহজ হয়।", en: "The AI safety policies that review decisions must follow are kept here. For each policy the page shows its purpose, the situations it covers, and how it is cited in a decision. A reviewer who is unsure reads the relevant policy before deciding. That way similar events are judged against one written standard by everyone. Consistent citation also makes decisions easier to review later." },
  "/dashboard/ai-safety-reviewer/profile": { bn: "এই পাতায় লগইন করা ব্যক্তির নিজের অ্যাকাউন্ট তথ্য দেখা যায় এবং প্রয়োজন অনুযায়ী সম্পাদনা করা যায়। নাম, যোগাযোগের বিবরণ ও ছবির মতো তথ্য এখানে হালনাগাদ করা হয়, যাতে সংস্থার রেকর্ডে সবসময় সঠিক বিবরণ থাকে। নিজের অ্যাকাউন্ট বলেই এই পরিবর্তন সংশ্লিষ্ট ব্যক্তির তথ্যেই সীমাবদ্ধ থাকে, অন্য কারও ভূমিকা বা অনুমতিতে হাত পড়ে না। ভুল তথ্য চোখে পড়লে এখান থেকেই সংশোধন করে নেওয়া যায়। নিজের তথ্য নিজে হালনাগাদ রাখলে প্রশাসনিক সহায়তার দরকার কমে।", en: "This page shows the signed-in person's own account details and allows edits. Name, contact details and picture are updated here, so organisation records carry current information. Because it is their own account, changes stay within that person's details and touch no one else's role. Anything out of date is corrected here instead of via an administrator. Keeping details current reduces requests to administrators." },
  "/dashboard/ai-safety-reviewer/reports": { bn: "এই পাতায় এআই নিরাপত্তা বিষয়ক সামগ্রিক রিপোর্ট দেখা যায়। রেকর্ড করা ঘটনার সংখ্যা, এসক্যালেশনের পরিমাণ এবং কোন নীতিমালা কতবার সিদ্ধান্তে ব্যবহৃত হয়েছে তা একসঙ্গে পাওয়া যায়। ব্যবস্থাপনা ও তদারককারীরা এই রিপোর্ট দেখে কাজের চাপ ও প্রবণতা বোঝেন, আর নীতিমালা হালনাগাদ বা প্রশিক্ষণ দরকার কি না তা নির্ধারণ করেন। নির্দিষ্ট সময় ধরে প্রতিবেদন দেখে আগের অবস্থার সঙ্গে তুলনাও করা যায়। রিপোর্ট থেকে প্রাপ্ত চিত্র সিদ্ধান্ত গ্রহণে ব্যবহার করা যায়।", en: "This page presents the overall AI safety reports. It brings together how many events were recorded, how much escalation occurred, and how often each policy was cited. Managers and oversight staff read it to gauge workload and direction without opening individual cases. Comparing the same report over later periods shows how the position has moved. The figures also serve as input when planning the next period." },
  "/dashboard/ai-safety-reviewer/reports/audit-history": { bn: "এই রিপোর্টে এআই নিরাপত্তা পদক্ষেপ ও পর্যালোচকদের কার্যক্রম কালানুক্রমে দেখা যায়। কোন সময়ে কী ঘটেছে, কে সিদ্ধান্ত দিয়েছেন এবং কোন কেসে কোন পরিবর্তন এসেছে তা একটানা ধারায় সাজানো থাকে। তদারকি বা নিরীক্ষার সময় এই রিপোর্ট দেখিয়ে প্রতিটি সিদ্ধান্তের সূত্র ও সময় প্রমাণ করা যায়। কোনো প্রশ্ন ওঠলে একই ইতিহাস থেকে উত্তর মেলা সহজ হয়, কারণ সবকিছু সময় অনুযায়ী নথিভুক্ত থাকে। এতে নিয়মিত তদারকি সহজ হয় এবং জবাবদিহি নিশ্চিত থাকে।", en: "This report presents AI safety actions and reviewer activity in chronological order. What happened and when, who decided, and which case changed form one continuous record. During supervision or an audit it evidences the origin and timing of any decision. Anything questioned later is usually answered by this same trail. Regular oversight and accountability both rest on this record." },
  "/dashboard/ai-safety-reviewer/reports/escalation-trend": { bn: "এই রিপোর্টে সময়ের সঙ্গে এসক্যালেশনের হার দেখানো হয়, অর্থাৎ কোন সময়ে কতগুলো ঘটনা ঊর্ধ্বতনে পাঠাতে হয়েছে। প্রবণতা উপরে ওঠা মানে প্রথম স্তরে সিদ্ধান্ত নেওয়া কঠিন হচ্ছে বা ঘটনার চাপ বাড়ছে, আর নিচে নামা মানে পর্যালোচনা আরও স্থির হচ্ছে। এই চিত্র দেখে কর্মীর চাপ, প্রশিক্ষণের প্রয়োজন বা নীতিমালার স্পষ্টতা নিয়ে সিদ্ধান্ত নেওয়া যায়। নির্দিষ্ট সময় ধরে প্রবণতা দেখা হলে হঠাৎ বাড়া বা কমা সহজে ধরা পড়ে। কয়েক সময়ের ধারা একসঙ্গে দেখলে এক সপ্তাহের চেয়ে বেশি বোঝা যায়।", en: "This report charts escalation rates over time, meaning how many events had to go upward in each period. A rising line suggests first-level decisions are getting harder or case volume is growing. A falling line suggests review is settling. The figures support decisions on staffing pressure, training, or how clear the policies are. Trends across several periods say more than a single week." },
  "/dashboard/ai-safety-reviewer/reports/open-safety-events": { bn: "এই রিপোর্টে এমন নিরাপত্তা ঘটনাগুলো দেখানো হয় যেগুলো এখনো খোলা আছে, পুরনোটি সবার আগে। সবচেয়ে পুরনো ঘটনাগুলো উপরে থাকায় দীর্ঘদিন অনিষ্পন্ন পড়ে থাকা বিষয়গুলো সহজেই চোখে পড়ে। পর্যালোচক এই তালিকা ধরে একটি একটি করে ঘটনা খুলে সিদ্ধান্ত নিতে পারেন, ফলে কোনো পুরনো ঘটনা ভুলে যাওয়ার ঝুঁকি কমে। নিয়মিত এই রিপোর্ট দেখা হলে বকেয়া কাজের পরিমাণ নিয়ন্ত্রণে থাকে। কোন ঘটনা কত দিন ধরে খোলা আছে তা দেখে অগ্রাধিকার ঠিক করা যায়।", en: "This report shows safety events that are still open, oldest first. Because the earliest entries sit at the top, anything pending for a long time is easy to spot. A reviewer works down the list, opening each event and recording a decision. Checking it regularly stops the backlog from quietly growing. With older entries on top, prioritisation is straightforward." },
  "/dashboard/ai-safety-reviewer/reports/policy-codes": { bn: "এই রিপোর্টে প্রতিটি সিদ্ধান্তে যে নীতিমালা কোড উল্লেখ করা হয়েছে তা একসঙ্গে দেখা যায়। কোন কোড কতবার ব্যবহৃত হয়েছে এবং কোন ধরনের ঘটনায় তা প্রয়োগ হয়েছে তা বোঝা যায়। এই তথ্য দেখে বোঝা যায় কোন নীতিমালা বেশি কাজে লাগছে আর কোনটি কম ব্যবহৃত বা অস্পষ্ট। প্রয়োজনে নীতিমালার ভাষা সহজ করা বা নতুন নির্দেশনা যোগ করার সিদ্ধান্তও এর ভিত্তিতে নেওয়া যায়। সিদ্ধান্তের সঙ্গে কোড যুক্ত থাকায় পরবর্তী যাচাই অনেক সহজ হয় এবং আলাদা ব্যাখ্যা দিতে হয় না।", en: "This report gathers the policy codes cited in each decision. It becomes clear how often a code was used and what kind of event it was applied to. That shows which policies carry most of the load and which are rarely used or unclear. The same information supports simplifying wording or adding guidance. Tagging decisions with codes also makes later verification quicker." },
  "/dashboard/ai-safety-reviewer/resolved": { bn: "বন্ধ হয়ে যাওয়া এআই কেসগুলো এখানে সাজানো থাকে, প্রতিটির সঙ্গে কোন পদক্ষেপে সমস্যাটি সমাধান হয়েছে তার বিবরণ থাকে। পর্যালোচক পুরনো কেস খুলে আগের সিদ্ধান্ত ও যুক্তি দেখে নিতে পারেন, যা একই ধরনের নতুন কেস দ্রুত নিষ্পত্তিতে সহায়ক হয়। এই তালিকা প্রমাণ হিসেবেও কাজ করে যে প্রতিটি অভিযোগের একটি নথিভুক্ত সমাধান আছে। একই সমস্যা বারবার ফিরে এলে তার ধরনও এখান থেকেই বোঝা যায়। পুরনো কেসের নথি মুছে যায় না, তাই রেকর্ড অটুট থাকে।", en: "Closed AI cases are collected here, each with the action that resolved it. A reviewer can reopen an old case to see the decision and the reasoning behind it. That speeds up handling when a similar case appears again. The list also evidences that every raised concern reached a documented closure. Where the same issue returns, the pattern shows up here. The records are kept, so the reasoning is not lost over time." },
  "/dashboard/ai-safety-reviewer/review-queue": { bn: "এই কিউতে সেই সব এআই কনটেন্ট জমা থাকে যেগুলোর নিরাপত্তা সিদ্ধান্ত এখনো নেওয়া হয়নি। পর্যালোচক প্রতিটি আইটেম খুলে তার বিষয়বস্তু ও প্রেক্ষাপট পড়েন এবং প্রয়োজনে সংশ্লিষ্ট সেশন যাচাই করেন। এরপর তিনি অনুমোদন, প্রত্যাখ্যান বা এসক্যালেশনের সিদ্ধান্ত রেকর্ড করেন এবং সংক্ষিপ্ত কারণ লিখে দেন। সিদ্ধান্ত রেকর্ড হওয়ামাত্র আইটেমটি কিউ থেকে সরে যায়, ফলে বাকি কাজের চাপ স্পষ্ট থাকে। নতুন কনটেন্ট যোগ হলে বা কর্মদিবসের শুরুতে এই তালিকা দেখে অগ্রাধিকার ঠিক করা যায়।", en: "This queue holds AI content that still needs a safety decision. A reviewer opens each item and reads the content with its context. Where needed they check the related session before deciding. They record a decision to approve, reject or escalate with a short reason. Once recorded the item leaves the queue, so pending workload stays visible at a glance." },
  "/dashboard/ai-safety-reviewer/safety-events": { bn: "এই পাতায় এআই ব্যবহারে ঘটে যাওয়া প্রতিটি নিরাপত্তা ঘটনা লিপিবদ্ধ থাকে, নতুনটি সবার আগে দেখানো হয়। প্রতিটি সারিতে কোন ধরনের ঘটনা ঘটেছে, কোন এআই ইন্টার‌্যাকশন থেকে এসেছে এবং কে জড়িত ছিল তা দেখা যায়। পর্যালোচক যেকোনো ঘটনা খুলে বিস্তারিত ও সংশ্লিষ্ট প্রমাণ দেখে সেটি সরাসরি নিষ্পত্তি করতে বা এসক্যালেট করতে পারেন। এভাবে পুরো এআই ব্যবহারের ঝুঁকি এক জায়গা থেকে নজরে রাখা যায়। একই ঘটনার পুনরাবৃত্তি হলেও তার একটিই নথি থাকে, তাই তথ্যে দ্বিধা তৈরি হয় না।", en: "Every safety event recorded in the AI system is logged here, newest first. Each row shows the kind of event, the AI interaction it came from, and who was involved. A reviewer opens an event to read the details and evidence, then resolves it or escalates it. Keeping one chronological log means no recorded event is quietly dropped. The order of the log also makes a case's sequence easy to reconstruct." },
  "/dashboard/ai-safety-reviewer/tutor-sessions": { bn: "এই তালিকায় এআই টিউটরের কথোপকথনগুলো শিক্ষার্থী ও সেশন ধরে সাজানো থাকে। পর্যালোচক যেকোনো সেশন খুলে শুরু থেকে শেষ পর্যন্ত পুরো আলাপ পড়তে পারেন এবং শিক্ষার্থীর প্রশ্ন ও টিউটরের উত্তর পাশাপাশি মিলিয়ে দেখতে পারেন। কোনো উত্তর সন্দেহজনক মনে হলে সেখান থেকেই সেটি ফ্ল্যাগ বা এসক্যালেট করা যায়। এতে বোঝা যায় টিউটর অনুমোদিত বিষয়ের বাইরে গিয়ে কিছু বলছে কি না। শিক্ষার্থী কতটা সহায়তা নিচ্ছেন তাও সেশন দেখে বোঝা যায়।", en: "Tutor conversations are listed here by student and session. A reviewer can open any session and read the whole exchange from first message to last. That shows what the learner asked beside what the tutor answered. Any doubtful reply can be flagged or escalated from the same view. Reading whole sessions shows whether the tutor stayed within approved subject matter. It also shows how much help each learner draws on." },
  "/dashboard/content-reviewer/ai-pathshala/ai-tutor": { bn: "চ্যাটভিত্তিক এই টিউটর শুধু অনুমোদিত লেসন কনটেন্ট থেকে উত্তর দেয়, তাই বাইরের অনির্ভরযোগ্য উৎসের উপর নির্ভর করতে হয় না। পর্যালোচক হিসেবে এই আচরণ যাচাই করা যায়, কারণ উত্তর অনুমোদিত কনটেন্টের বাইরে গেলে তা ধরা পড়ে। প্রশ্ন লিখে দেখা যায় টিউটর কীভাবে উত্তর দেয় এবং তার সীমা কোথায়। এতে অনুমোদিত পাঠ্যক্রমের বাইরে তথ্য ছড়ানোর ঝুঁকি কমে। উত্তর ভুল তথ্য দিলে তা লেসনের কোন অংশ থেকে এসেছে খুঁজে বের করা যায়, ফলে সংশোধনও নির্দিষ্ট জায়গায় করা যায়।", en: "A chat tutor that answers only from approved lesson content instead of pulling in uncontrolled outside material. For a reviewer this behaviour can be tested directly: ask a question and see whether the reply stays within what has been approved. The exchange also shows where the tutor's limits currently lie. That keeps unreviewed information from spreading through answers." },
  "/dashboard/content-reviewer/ai-pathshala/assessments": { bn: "অ্যাসেসমেন্টের তালিকা এবং প্রত্যেক শিক্ষার্থীর প্রাপ্ত নম্বর এখানে দেখা যায়। প্রতিটি অ্যাসেসমেন্টে কোন ক্লাস ও টপিক জড়িত তা বোঝা যায়, ফলে ফলাফলের পটভূমি স্পষ্ট থাকে। পর্যালোচক হিসেবে নম্বরের ধরন দেখে বোঝা যায় কোনো অ্যাসেসমেন্ট অতিরিক্ত কঠিন বা সহজ হয়ে গেছে কি না। এতে কনটেন্টের গুণমান নিয়ে সিদ্ধান্ত নেওয়ার বাস্তব ভিত্তি পাওয়া যায়। সময়ের সাথে নম্বরের ধারা বদলালে তা কনটেন্টের পরিবর্তনের সাথে মিলিয়ে দেখা যায়।", en: "Lists the assessments in use alongside the marks each student obtained. Every assessment shows the class and topic behind it, so a score can be read in context. A reviewer can judge from the spread of marks whether an assessment has turned out too hard or too easy. That gives a practical basis for decisions about the quality of the underlying content." },
  "/dashboard/content-reviewer/ai-pathshala/lesson-planner": { bn: "দিন-ভিত্তিক এই প্ল্যানার দেখায় কোন দিনে কোন লেসন বা টপিক পড়ানো হবে, যা শিক্ষক ক্লাসে অনুসরণ করতে পারেন। পর্যালোচনার সময় এই সময়সূচি দেখে বোঝা যায় কোনো কনটেন্ট সঠিক ক্রমে ও সঠিক সময়ে বসছে কি না। পরিকল্পনার সাথে কনটেন্ট মিলিয়ে দেখলে ফাঁক বা পুনরাবৃত্তি সহজে ধরা পড়ে। এতে অনুমোদিত উপকরণ পাঠদানের ধারার সাথে সামঞ্জস্যপূর্ণ থাকে। কোন সময়ে কোন ক্লাসের জন্য উপকরণ বেশি দরকার তা পরিকল্পনা দেখে বোঝা যায়, ফলে পর্যালোচনার অগ্রাধিকারও সাজানো যায়।", en: "The day-by-day planner shows which lesson or topic is taught on which date, in the order teachers follow in class. During review the same schedule shows whether a piece fits into the right place at the right stage. Checking content against the plan brings gaps and repetition into view quickly. Approved material therefore stays in step with how the syllabus is actually taught." },
  "/dashboard/content-reviewer/ai-pathshala/lessons": { bn: "ক্লাস ও বিষয় অনুযায়ী সাজানো কাঠামোবদ্ধ এআই লেসন এখানে দেখা যায়। পর্যালোচকের কাজে এই তালিকা প্রয়োজনীয়, কারণ জমা পড়া কনটেন্ট কোন ক্লাস ও বিষয়ের সাথে সম্পর্কিত তা মিলিয়ে দেখা যায়। লেসন খুলে তার বিষয়বস্তু ও ক্রম যাচাই করা যায়। অনুমোদনের আগে পাঠ্যক্রমের সাথে সামঞ্জস্য নিশ্চিত করার ভিত্তি এখান থেকেই তৈরি হয়। কোন লেসনে বিষয়বস্তু এখনো কম বা অসম্পূর্ণ তা দেখে পরে কোন দিকে আরও জমা দরকার হবে তাও আগেই আন্দাজ করা যায়।", en: "Structured AI lessons organised by class and subject are listed here. The list matters in review work because a submitted piece has to be matched to the class and subject it belongs to. Opening a lesson makes its content and sequence available for checking. Confirming that material fits the syllabus before approval starts from this view." },
  "/dashboard/content-reviewer/ai-pathshala/progress": { bn: "টপিক ধরে মাস্টারি অগ্রগতি এখানে দেখানো হয়, অর্থাৎ কোন বিষয়ে দখল কতটা তৈরি হয়েছে তা বোঝা যায়। লগইন করা ব্যবহারকারীর নিজের অগ্রগতিই এই পাতায় দেখা যায়, তাই প্রতিবার আলাদা করে প্রসঙ্গ মেলাতে হয় না। পর্যালোচনার সময় দেখা যায় কোন টপিকগুলোতে শিক্ষার্থীরা সাধারণত আটকে যায়। সেই তথ্য দেখে সংশ্লিষ্ট কনটেন্ট সহজ বা স্পষ্ট করার সিদ্ধান্ত নেওয়া যায়। কোন টপিকে অগ্রগতি ধীরে বাড়ছে তা দেখে কনটেন্ট পুনর্বিবেচনার সংকেত পাওয়া যায়।", en: "Topic-wise mastery progress is shown here, making clear how well each topic has actually been grasped. The page covers the progress of the user who is logged in, so the figures always belong to the right learner. In review work it reveals the topics where learners commonly get stuck. Content that keeps causing difficulty can then be clarified or simplified on that evidence." },
  "/dashboard/content-reviewer/ai-pathshala/quizzes": { bn: "এআই-জেনারেটেড কুইজের তালিকা এখানে দেখা যায়, প্রতিটি কুইজ নির্দিষ্ট লেসন বা টপিকের সাথে যুক্ত। শিক্ষার্থী জমা দেওয়ার সাথে সাথেই উত্তর যাচাই হয়ে ফলাফল তৈরি হয়, তাই আলাদা মূল্যায়নের অপেক্ষা করতে হয় না। পর্যালোচক হিসেবে দেখা যায় কোন কুইজ কতটা কঠিন হচ্ছে এবং প্রশ্নগুলো লেসনের সাথে মিলছে কি না। এই ফলাফলই পরে অগ্রগতি হিসাবের ভিত্তি হয়। কোন কুইজে প্রশ্ন বেশি কঠিন বা অস্পষ্ট হচ্ছে তা দেখে সংশ্লিষ্ট লেসন বা প্রশ্নটি পুনর্বিবেচনা করা যায়।", en: "AI-generated quizzes are listed here, each tied to the lesson or topic it came from. Answers are checked the moment a student submits, so a score appears without separate marking. A reviewer can see which quizzes are proving hard and whether the questions really match the lesson they claim to test. Those outcomes later become the base for progress figures." },
  "/dashboard/content-reviewer/ai-pathshala/study-plan": { bn: "সবচেয়ে দুর্বল টপিক চিহ্নিত করে তৈরি করা ব্যক্তিগত স্টাডি প্ল্যান এখানে দেখা যায়। কোন টপিক আগে পড়া দরকার এবং কোন ক্রমে এগোলে দুর্বলতা কমবে তা পরিকল্পনায় সাজানো থাকে। পর্যালোচক হিসেবে এই প্ল্যান দেখে বোঝা যায় কোন টপিক বারবার দুর্বল হিসেবে উঠে আসছে। সেই সংকেত সংশ্লিষ্ট কনটেন্ট পুনর্বিবেচনার কারণ হতে পারে। একই টপিক একাধিক সন্তানের পরিকল্পনায় ফিরে এলে তা কেবল ব্যক্তিগত দুর্বলতা নয়, উপকরণের সীমাও হতে পারে। সেই ইঙ্গিত পর্যালোচনায় কাজে লাগে।", en: "A personal study plan built from the weakest topics appears here. It sets out which topic to take first and in what order to move so that the gaps close. For a reviewer the plan is also a signal: the topics it keeps returning to are the ones learners consistently struggle with. That pattern is a fair reason to look again at the content behind those topics." },
  "/dashboard/content-reviewer/approved": { bn: "যে কনটেন্ট ইতিমধ্যে অনুমোদিত এবং শিক্ষার্থীদের জন্য চালু হয়েছে তার তালিকা এখানে দেখা যায়। প্রতিটি আইটেমের সাথে অনুমোদনের সময় ও পর্যালোচকের পরিচয় পাওয়া যায়, ফলে সিদ্ধান্তের সূত্র স্পষ্ট থাকে। অনুমোদিত তালিকা দেখে বোঝা যায় কী ইতিমধ্যে প্রকাশিত এবং কোন বিষয়ে নতুন কিছু যোগ হয়েছে। প্রয়োজনে কোনো আইটেমের বিস্তারিত দেখে সিদ্ধান্ত যাচাই করা যায়। প্রকাশিত তালিকা থেকে কোনো আইটেম সরানো বা স্থগিত করা দরকার হলে সেই কাজও এখান থেকেই শুরু হয়।", en: "Lists the content already approved and released to students. Each entry carries the approval date and the reviewer who signed it off, so the origin of a decision stays visible. Reading the approved list shows what is live and what has recently been added to the published material. Any item can be opened for detail if a decision needs to be checked later." },
  "/dashboard/content-reviewer/content-datasets": { bn: "এআই টিউটর প্রশিক্ষণের জন্য দেওয়া লেসন ডেটাসেট এখানে তালিকাভুক্ত থাকে। প্রতিটি ডেটাসেট ব্যবহারের আগে পর্যালোচনা করা হয়, যাতে ভুল বা অনুপযুক্ত কনটেন্ট প্রশিক্ষণে ঢুকে না পড়ে। ডেটাসেট খুলে তার উৎস ও বিষয়বস্তু দেখা যায় এবং গুণমান মিলিয়ে সিদ্ধান্ত নেওয়া যায়। অনুমোদনের পরই তা ব্যবহারযোগ্য হয়, ফলে প্রশিক্ষণের ভিত্তি নিয়ন্ত্রণে থাকে। কোন ডেটাসেট কোন ক্লাস বা বিষয়ের জন্য তৈরি তা তালিকায় দেখা যায়, তাই প্রসঙ্গ না জেনে সিদ্ধান্ত নিতে হয় না।", en: "Lesson datasets supplied for AI tutor training are listed here. Each one is reviewed before use, so that inaccurate or unsuitable material does not reach the training set unnoticed. Opening a dataset shows where it came from and what it contains, which is what the quality judgement rests on. Only after approval does it become usable, keeping the training base under control." },
  "/dashboard/content-reviewer/guidelines": { bn: "এই ভূমিকার পর্যালোচনার মান এবং গুণমান-চেকলিস্ট এখানে দেওয়া থাকে। কোন দিকগুলো যাচাই করা বাধ্যতামূলক, কোন ত্রুটিতে বাতিল করা হয় এবং কারণ কীভাবে লিখতে হয় তা নির্দেশিকা থেকে জানা যায়। সবাই একই মান অনুসরণ করলে সিদ্ধান্তে সামঞ্জস্য থাকে এবং লেখকও আগেই বুঝতে পারেন কী প্রত্যাশিত। নতুন পর্যালোচকের জন্য এটি প্রধান নির্ভরযোগ্য সূত্র। নির্দেশিকা হালনাগাদ হলে সবাই একই নিয়মে কাজ করে, তাই পুরোনো ও নতুন সিদ্ধান্তের মধ্যে অসঙ্গতি কমে।", en: "The review standards and quality checklist for this role are set out here. The guidelines state which points must be verified, which faults justify rejection and how a reason should be written. A shared standard keeps decisions consistent between reviewers, and lets authors know what is expected before they submit. For someone new to the role it is the first reference to read." },
  "/dashboard/content-reviewer/notifications": { bn: "নতুন জমা পড়া এবং সংশোধনের কার্যক্রম এখানে জানানো হয়। কেউ নতুন কনটেন্ট জমা দিলে বা সংশোধিত সংস্করণ পাঠালে সেই খবর এখানেই আসে, ফলে কিউতে বারবার না ঢুকেও কাজের গতি বোঝা যায়। অপঠিত বিজ্ঞপ্তি আলাদা করে চিহ্নিত থাকে। কোন লেখা জরুরি ভিত্তিতে দেখা দরকার তা এই তালিকা দেখে সহজে নির্ধারণ করা যায়। কোন লেখক একসাথে কয়েকটি সংশোধিত সংস্করণ পাঠিয়েছেন তাও এখান থেকে বোঝা যায়, ফলে পর্যালোচনার ক্রম সাজানো ও অগ্রাধিকার নির্ধারণ সহজ হয়।", en: "Reports new submissions and revision activity as it happens. When someone sends fresh content or a corrected version, the notice arrives here, so the pace of work can be judged without reopening the queue. Unread notices are marked apart from those already seen. The list makes it straightforward to decide which piece should be reviewed first." },
  "/dashboard/content-reviewer/profile": { bn: "লগইন করা ব্যক্তির নিজের অ্যাকাউন্ট তথ্য এখানে দেখা যায়, যেমন নাম ও যোগাযোগের বিবরণ। যে তথ্যগুলো নিজে পরিবর্তন করা যায় সেগুলো সম্পাদনা করে সংরক্ষণ করা যায়, আর প্রশাসন-নিয়ন্ত্রিত তথ্য কেবল দেখা যায়। সঠিক তথ্য থাকলে নোটিফিকেশন ও কাজের দায়িত্ব সঠিক ব্যক্তির কাছে পৌঁছায়। নিজের ভূমিকা ও অ্যাকাউন্টের অবস্থাও এখানেই যাচাই করা যায়। নিজের ভূমিকা ও অনুমোদনের সীমা এই পাতায় স্পষ্ট থাকে, ফলে কোন কাজ করার অধিকার আছে তা নিয়ে সংশয় থাকে না।", en: "Shows the signed-in person's own account details, including name and contact information. Fields under the user's control can be edited and saved, while administrator-managed fields remain read-only. Accurate details are what allow notifications and assigned work to reach the right person. The page also confirms the role the account currently holds." },
  "/dashboard/content-reviewer/rejected": { bn: "পর্যালোচকের কারণসহ বাতিল হওয়া আইটেম এখানে জমা থাকে। প্রতিটি বাতিলের সাথে কারণ উল্লেখ থাকায় লেখক বুঝতে পারেন ঠিক কী সংশোধন করা দরকার। আইটেমগুলো সংশোধনের জন্য প্রস্তুত অবস্থায় থাকে, তাই কাজ শুরু করতে আলাদা খোঁজাখুঁজি করতে হয় না। বারবার একই কারণে বাতিল হচ্ছে কি না তা দেখে সাধারণ মান উন্নয়নের দিকও বোঝা যায়। একই লেখকের একাধিক আইটেম বাতিল হলে তা একসাথে দেখা যায়, ফলে ব্যক্তিগত নয়, পদ্ধতিগত সমস্যা ধরাই সহজ হয়।", en: "Items turned down by a reviewer are kept here together with the reason given. Because the reason is attached to each rejection, the author can see exactly what needs correcting rather than guessing. The items stay ready for revision, so the rework can begin without searching elsewhere. Repeated rejection for the same cause also points to a general quality problem worth fixing." },
  "/dashboard/content-reviewer/review-history": { bn: "প্রতিটি পর্যালোচনা সিদ্ধান্তের পূর্ণ ইতিহাস এখানে সংরক্ষিত থাকে, সময় ও পর্যালোচকের পরিচয়সহ। কোন আইটেম কখন অনুমোদিত, বাতিল বা সংশোধনের জন্য ফেরত পাঠানো হয়েছে তা ক্রমানুসারে দেখা যায়। ইতিহাস দেখে বোঝা যায় কোনো সিদ্ধান্ত কে নিয়েছে এবং তার আগে কী ঘটেছিল। প্রয়োজনে পুরোনো সিদ্ধান্ত যাচাই বা ব্যাখ্যা করার ভিত্তি এখান থেকেই পাওয়া যায়। একই আইটেম কতবার ফিরে এসেছে তা ইতিহাসে দেখা যায়, ফলে বারবার সংশোধনের ধরনটিও বোঝা যায়।", en: "The full history of every review decision is kept here, with the time and the reviewer recorded. It shows, in order, when an item was approved, rejected or sent back for revision. Reading it establishes who made a decision and what had happened before it. When an earlier conclusion has to be justified or questioned, this is the record to work from." },
  "/dashboard/content-reviewer/review-queue": { bn: "গুণমান পর্যালোচনার জন্য জমা দেওয়া নতুন কনটেন্ট এই কিউতে অপেক্ষা করে। প্রতিটি আইটেমে কে জমা দিয়েছে, কখন দিয়েছে এবং কোন ধরনের কনটেন্ট তা দেখা যায়। পর্যালোচক আইটেম খুলে যাচাই করে অনুমোদন, বাতিল বা সংশোধনের অনুরোধ জানাতে পারেন। কিউ খালি হওয়া মানে প্রতিটি জমা সিদ্ধান্ত পেয়েছে, তাই কিছু অপর্যালোচিত পড়ে থাকে না। প্রতিটি আইটেমের বিস্তারিত দেখে আগের সংশোধন হয়েছে কি না তা যাচাই করা যায়, ফলে একই ভুল বারবার অনুমোদিত হওয়ার ঝুঁকি থাকে না।", en: "Newly submitted content waits in this queue for a quality review. Each item shows who sent it, when, and what kind of content it is. The reviewer opens the item, checks it, and then approves it, rejects it or asks for revision. An empty queue means every submission has reached a decision, so nothing is left unreviewed by accident." },
  "/dashboard/content-reviewer/revision-requests": { bn: "লেখককে সংশোধন করে পুনরায় জমা দিতে বলা চলমান অনুরোধগুলো এখানে দেখা যায়। প্রতিটি অনুরোধে কোন আইটেম, কী পরিবর্তন চাওয়া হয়েছে এবং কে অনুরোধ করেছে তা উল্লেখ থাকে। অনুরোধ নিষ্পত্তি হলে তা তালিকা থেকে সরে যায়, ফলে বাকি কাজ স্পষ্ট থাকে। লেখক ও পর্যালোচকের মধ্যে কাজের যোগসূত্র এখানেই রক্ষিত হয়। অনুরোধের সাথে সংশ্লিষ্ট জমা ও তার আগের পর্যালোচনা মিলিয়ে দেখা যায়, তাই লেখক ঠিক কী বদলাবেন তা নিয়ে অস্পষ্টতা থাকে না।", en: "Open requests asking an author to revise a piece and submit it again are tracked here. Each one records which item it concerns, what change was asked for and who asked. Once a request is settled it leaves the list, so what remains is a true picture of outstanding work. This is the thread that keeps author and reviewer moving on the same correction." },
  "/dashboard/government-officer/ai-pathshala/ai-tutor": { bn: "এখানে একটি চ্যাটভিত্তিক এআই টিউটর আছে, যা কেবল অনুমোদিত লেসন কনটেন্টের ভেতর থেকেই উত্তর তৈরি করে। প্রশ্ন লিখলে টিউটর সংশ্লিষ্ট লেসনের ব্যাখ্যা হাজির করে, ফলে পাঠ্যসূচির বাইরের তথ্য ঢুকে পড়ার সুযোগ কমে। চ্যাট পর্দাতেই প্রশ্ন ও উত্তরের ধারা থেকে যায়, তাই পরে মিলিয়ে দেখা সহজ। কর্মকর্তারাও এটি ব্যবহার করে দেখতে পারেন শিক্ষার্থীরা কী ধরনের সহায়তা পাচ্ছে। উত্তর দেওয়ার সময় টিউটর কেবল পাঠ্য কনটেন্টেই সীমাবদ্ধ থাকে।", en: "This page offers a chat based AI tutor that builds its answers only from approved lesson content. When a question is typed, the tutor brings forward the explanation held in the related lesson, which leaves little room for material outside the syllabus. The question and answer trail remains on the screen, so it can be reviewed later. Officers can also use it to see what kind of help learners are receiving." },
  "/dashboard/government-officer/ai-pathshala/assessments": { bn: "এই পর্দায় অ্যাসেসমেন্টের তালিকা এবং প্রত্যেক শিক্ষার্থীর প্রাপ্ত নম্বর পাশাপাশি দেখা যায়। নির্দিষ্ট অ্যাসেসমেন্ট বেছে নিলে কে কত নম্বর পেয়েছে তা সরাসরি মিলিয়ে দেখা যায়। নম্বরের সঙ্গে শিক্ষার্থীর নাম ও ক্লাসের তথ্য থাকায় ফলাফল ব্যাখ্যা করা সহজ হয়। কর্মকর্তারা এই নম্বর দেখে কোন প্রতিষ্ঠানে অতিরিক্ত নজর দরকার তা বুঝতে পারেন। একই অ্যাসেসমেন্টের ফলাফল প্রতিষ্ঠান ধরে ভাগ করেও দেখা যায়।", en: "This screen shows the list of assessments next to the marks each learner received. Choosing a particular assessment lets a user check directly who scored what. With the learner name and class shown alongside the marks, the results are easier to interpret. Officers read these marks to judge which institution needs closer attention." },
  "/dashboard/government-officer/ai-pathshala/lesson-planner": { bn: "এই পর্দায় দিন-ভিত্তিক লেসন প্ল্যান দেখা ও ব্যবহার করা যায়, যা শিক্ষক ক্লাসে অনুসরণ করতে পারেন। প্ল্যানে কোন দিনে কোন টপিক পড়ানো হবে তা ধাপে ধাপে সাজানো থাকে, তাই ক্লাসের প্রস্তুতি আগেই সম্পন্ন করা যায়। কোন অংশ কভার হয়েছে তা মিলিয়ে নিয়ে পরের ধাপে যাওয়া যায়। একই প্ল্যান একাধিক প্রতিষ্ঠানে ব্যবহার করলে পাঠদানের ধরনেও মিল থাকে। শিক্ষক প্রয়োজনে প্ল্যানের ধাপ এগিয়ে বা পিছিয়ে নিতে পারেন।", en: "This screen presents day wise lesson plans that a teacher can follow in class. Each plan sets out which topic is taught on which day, step by step, so preparation for a class can be finished in advance. It can be checked against what has actually been covered before moving to the next step. Using the same plan in several institutions also keeps teaching consistent." },
  "/dashboard/government-officer/ai-pathshala/lessons": { bn: "এই পর্দায় এআই পাঠশালার লেসনগুলো ক্লাস ও বিষয় অনুযায়ী সাজিয়ে দেখানো হয়। ব্যবহারকারী তালিকা থেকে প্রয়োজনীয় শ্রেণির লেসন বেছে নিয়ে ভেতরের কনটেন্ট পড়তে পারেন। প্রতিটি লেসনের বিষয়, ক্লাস ও সারসংক্ষেপ একসাথে থাকায় কাঙ্ক্ষিত লেসন খুঁজে পেতে বেশি সময় লাগে না। কর্মকর্তারা এই লেসন দেখে বুঝতে পারেন প্রতিষ্ঠানগুলোতে আসলে কী পড়ানো হচ্ছে। লেসনের তালিকা ক্লাস অনুযায়ী ছেঁকে দেখা যায়।", en: "This screen presents AI Pathshala lessons arranged by class and subject. A user can choose the lesson for the grade they need from the list and read the content inside. Subject, class and a short summary sit together for each lesson, so finding the right one takes little time. Officers use these lessons to understand what is actually being taught in institutions." },
  "/dashboard/government-officer/ai-pathshala/progress": { bn: "এই পর্দায় লগইন করা ব্যবহারকারীর অগ্রগতি টপিক ধরে দেখানো হয়। কোন বিষয়ে দক্ষতা কতটা দাঁড়িয়েছে এবং কোন অংশ এখনো অসম্পূর্ণ, তা এক নজরে বোঝা যায়। টপিক বেছে নিলে বিস্তারিত চিত্র দেখা যায়, ফলে কোথায় বেশি অনুশীলন দরকার তা স্পষ্ট হয়। শিক্ষার্থী নিজে এবং তাঁর শিক্ষক—দুজনেই এই পর্দা থেকে অগ্রযাত্রা পর্যালোচনা করতে পারেন। কোন টপিক দীর্ঘদিন অসম্পূর্ণ থেকে গেলে তা সহজেই নজরে আসে এবং আলাদা করে দেখা যায়।", en: "This screen shows the signed in user progress, topic by topic. It makes clear how much mastery has been reached in each subject and which parts are still incomplete. Selecting a topic opens the detail, which shows where more practice is needed. Both the learner and their teacher can use this page to review how far the work has moved." },
  "/dashboard/government-officer/ai-pathshala/quizzes": { bn: "এখানে এআই দিয়ে তৈরি কুইজগুলোর তালিকা ও বিস্তারিত দেখা যায়। শিক্ষার্থী উত্তর জমা দিলেই যাচাই প্রক্রিয়া নিজে থেকে সম্পন্ন হয় এবং ফলাফল তৈরি হয়ে যায়, তাই শিক্ষককে আলাদা সময় দিতে হয় না। ব্যবহারকারী ক্লাস বা বিষয় ধরে কুইজ বেছে নিয়ে প্রশ্নগুলো দেখতে পারেন। নিয়মিত ছোট মূল্যায়নের মাধ্যমে শিক্ষার্থীর অবস্থা বোঝার দ্রুত একটি উপায় এটি। ফলাফল তৈরি হওয়ার পর তালিকা থেকেই তা দেখা যায়।", en: "This page lists the quizzes built with AI and shows each one in detail. The moment a learner submits answers the checking runs by itself and a result appears, which saves the teacher time. A user can pick a quiz by class or subject and look through its questions. It offers a quick way to gauge how learners are doing through frequent short assessments." },
  "/dashboard/government-officer/ai-pathshala/study-plan": { bn: "এখানে সবচেয়ে দুর্বল টপিকগুলো চিহ্নিত করে ব্যক্তিগত স্টাডি প্ল্যান তৈরি করা হয়। প্ল্যানে কোন টপিক আগে আর কোনটি পরে পড়া হবে, সেই ক্রম সাজিয়ে দেওয়া থাকে, ফলে প্রস্তুতি এলোমেলো হয়ে যায় না। ব্যবহারকারী প্ল্যান মেনে ধাপে ধাপে এগোতে পারেন এবং অগ্রগতির সঙ্গে মিলিয়ে দেখতে পারেন। নিজে থেকে পড়ার রুটিন ঠিক করতে যাঁরা হিমশিম খান, তাঁদের জন্য এটি বিশেষভাবে সহায়ক। প্ল্যানে দেওয়া ক্রম অনুসরণ করলে দুর্বল টপিক আগেই শেষ হয়।", en: "This page creates a personal study plan built around the weakest topics. The plan sets out the order in which topics should be studied, so preparation does not become disorganised. A user can follow it step by step and check the movement against their progress. It is especially helpful for learners who find it hard to set a study routine of their own." },
  "/dashboard/government-officer/analytics": { bn: "এই পর্দায় জেলা-স্তরের বিশ্লেষণ দেখা যায়, যা তত্ত্বাবধানের সিদ্ধান্ত নিতে সহায়ক। প্রতিষ্ঠান, ভর্তি, উপস্থিতি ও ফলাফলের ধারা একসাথে বিশ্লেষণ করে কোথায় সমস্যা জমছে তা বোঝা যায়। ব্যবহারকারী জেলা বেছে নিয়ে সংশ্লিষ্ট বিশ্লেষণ দেখতে পারেন এবং তুলনার মাধ্যমে অগ্রাধিকার ঠিক করতে পারেন। পরিদর্শন পরিকল্পনা ও সম্পদ বণ্টনের সিদ্ধান্তে এই বিশ্লেষণ সরাসরি ব্যবহার হয়। এই বিশ্লেষণ জেলা-স্তরের অগ্রাধিকার তালিকা তৈরি করতেও সহায়ক।", en: "This page holds district level analysis intended to support oversight decisions. By analysing the pattern of institutions, enrolment, attendance and results together, it becomes clear where problems are building up. A user can select a district to view its analysis and set priorities through comparison. The findings feed directly into inspection planning and into decisions on how resources are shared." },
  "/dashboard/government-officer/attendance": { bn: "এই পর্দায় পর্যবেক্ষণাধীন প্রতিষ্ঠানগুলো জুড়ে উপস্থিতির হার দেখা যায়। প্রতিষ্ঠান ও জেলা ধরে হার পাশাপাশি থাকায় কোথায় উপস্থিতি স্থিতিশীল আর কোথায় দুর্বল, তা দ্রুত ধরা পড়ে। ব্যবহারকারী নির্দিষ্ট প্রতিষ্ঠান বেছে নিয়ে তার উপস্থিতির চিত্র দেখতে পারেন। নিয়মিত অনুপস্থিতির পেছনের কারণ খুঁজতে ও প্রয়োজনীয় সহায়তা দিতে এই তথ্য সহায়ক। উপস্থিতির হার সময় ধরে দেখলে ধীরে ধীরে বদলও ধরা পড়ে।", en: "This page presents attendance rates across the institutions under observation. With rates shown by institution and by district, it is quick to see where attendance is steady and where it is weak. A user can select a particular institution to view its attendance picture. The data helps investigate the reasons behind regular absence and provide the support that is needed." },
  "/dashboard/government-officer/data-exports": { bn: "এই পর্দা থেকে দাতা ও অভ্যন্তরীণ প্রতিবেদনের প্রয়োজন অনুযায়ী কর্মসূচির ডেটা ডাউনলোড করা যায়। কোন ডেটাসেট প্রয়োজন তা বেছে নিয়ে ফাইল আকারে নামিয়ে রাখা যায়, ফলে আলাদা করে অনুরোধ পাঠানোর দরকার হয় না। নামানোর আগে ব্যবহারকারী দেখে নিতে পারেন তিনি ঠিক কোন তথ্য নিচ্ছেন। প্রতিবেদন তৈরি এবং বাইরে তথ্য উপস্থাপনের কাজে এই ফাইলগুলো ব্যবহার হয়। ডেটাসেটের বিবরণ দেখে নিয়ে ভুল ফাইল নামানোর ঝুঁকি কমানো যায়।", en: "From this page, programme data can be downloaded for donor reporting and for internal use. The needed dataset is chosen and taken away as a file, so there is no need to send a separate request. Before downloading, a user can check exactly what information is being taken. These files then feed report writing and sharing with outside parties." },
  "/dashboard/government-officer/districts": { bn: "এই পর্দায় জেলাভিত্তিক একটি সার্বিক চিত্র দেখা যায়, যেখানে প্রতিষ্ঠানের সংখ্যা, ভর্তি ও ফলাফল একসাথে থাকে। প্রতিটি জেলার অবস্থান পাশাপাশি বসিয়ে দেখলে কোন জেলা এগিয়ে আর কোনটি পিছিয়ে, তা তুলনা করা সহজ হয়। ব্যবহারকারী একটি জেলা বেছে নিয়ে তার ভেতরের বিস্তারিত তথ্য দেখতে পারেন। জেলা-স্তরের পরিকল্পনা ও সমন্বয়ের জন্য এই দৃশ্যটি প্রধান ভিত্তি হিসেবে ব্যবহৃত হয়। জেলার এই তুলনা থেকে পরিদর্শনের অগ্রাধিকার তালিকা তৈরি করা হয়।", en: "This screen gives a district level picture in which the number of institutions, enrolment and results sit together. Placing districts side by side makes it easy to compare which ones are ahead and which are behind. A user can select a district and look into the detail held beneath it. This view serves as the main basis for planning and coordination at district level." },
  "/dashboard/government-officer/enrollment": { bn: "এই পর্দায় প্রতিষ্ঠান ও জেলা ধরে ভর্তির সংখ্যা ও প্রবণতা দেখা যায়। কোন প্রতিষ্ঠানে ভর্তি বাড়ছে, কোথায় কমছে এবং কোন সময়ে পরিবর্তনটা ঘটেছে, তা এক নজরে বোঝা যায়। ব্যবহারকারী প্রতিষ্ঠান বা জেলা বেছে নিয়ে নির্দিষ্ট সংখ্যা যাচাই করতে পারেন। ভর্তি কমার কারণ খোঁজা এবং সংশ্লিষ্ট প্রতিষ্ঠানকে সহায়তা দেওয়ার সিদ্ধান্তে এই তথ্য ব্যবহার হয়। এই সংখ্যা প্রতিষ্ঠানভিত্তিক ও জেলাভিত্তিক তুলনার ভিত্তি হিসেবে থাকে।", en: "This page shows enrolment numbers and trends by institution and by district. It makes visible where enrolment is rising, where it is falling and roughly when the change happened. A user can select an institution or a district to verify the figures. The information is used to look into drops in enrolment and to decide where an institution should receive support." },
  "/dashboard/government-officer/equity-indicators": { bn: "এই পর্দায় সমতা সূচকগুলো দেখা যায়, যেখানে লিঙ্গ, অবস্থান ও প্রবেশগত বৈষম্য আলাদা করে ধরা হয়। কোন গ্রুপের অংশগ্রহণ কম এবং কোথায় ব্যবধান সবচেয়ে বেশি, তা সংখ্যার মাধ্যমে বোঝা যায়। ব্যবহারকারী সূচক বেছে নিয়ে সংশ্লিষ্ট ভাঙ্গন দেখতে পারেন। নীতিনির্ধারণ এবং লক্ষ্যভিত্তিক সহায়তার জন্য এই ব্যবধানগুলো চিহ্নিত করা জরুরি। প্রতিটি সূচক আলাদা করে দেখলে কোন গ্রুপ কোথায় পিছিয়ে আছে, তা পরিষ্কার হয়।", en: "This screen presents equity indicators, separating gaps by gender, by location and by access. It shows through the numbers which group takes part less and where the gap is widest. A user can select an indicator and look at the breakdown behind it. Identifying these gaps matters for policy decisions and for support that is properly targeted." },
  "/dashboard/government-officer/institutions": { bn: "এই পর্দায় পর্যবেক্ষণাধীন সব প্রতিষ্ঠানের তালিকা জেলা ও বর্তমান অবস্থাসহ দেখা যায়। তালিকা থেকে নির্দিষ্ট প্রতিষ্ঠান বেছে নিয়ে তার তথ্য যাচাই করা যায়, ফলে কোন প্রতিষ্ঠান সক্রিয় আর কোনটি নিষ্ক্রিয় তা দ্রুত বোঝা যায়। সরকারি কর্মকর্তারা এই তালিকা দেখে তদারকির অগ্রাধিকার ঠিক করেন। পরিদর্শনের পর কোন প্রতিষ্ঠানের দিকে নজর দেওয়া দরকার, তা এখান থেকেই ধরা পড়ে। প্রতিষ্ঠানের তালিকা জেলা অনুযায়ী ছেঁকে দেখা যায়, ফলে বড় জেলার তথ্যও সহজে মেলে।", en: "This page lists every institution under observation along with its district and current status. Selecting an institution from the list opens its details for checking, so it is quick to see which ones are active and which are not. Government officers use the list to set the priority order for oversight. After an inspection, it is also the place to see which institution needs attention next." },
  "/dashboard/government-officer/learning-outcomes": { bn: "এই রিপোর্টে কর্মসূচি ও কোহোর্ট ধরে ফলাফলের চিত্র দেখা যায়। কোন কোহোর্ট প্রত্যাশিত মান অর্জন করেছে এবং কোনটি পিছিয়ে আছে, তা তুলনা করে বোঝা যায়। ব্যবহারকারী কর্মসূচি বা কোহোর্ট বেছে নিয়ে বিস্তারিত ফলাফল দেখতে পারেন। তদারকির সময় কোন প্রতিষ্ঠানে অতিরিক্ত সহায়তা দরকার, তা এই তুলনা থেকেই নির্ধারণ করা হয়। কোন প্রতিষ্ঠানের ফলাফল প্রত্যাশার নিচে, তা চিহ্নিত করে সেখানে পরবর্তী সহায়তা দেওয়া হয়।", en: "This report shows learning outcomes by programme and by cohort. Comparing the figures makes it clear which cohorts have met the expected level and which are lagging. A user can select a programme or a cohort to study the detail. During oversight, this comparison is what decides which institution should receive extra support. It also shows where additional support is needed." },
  "/dashboard/government-officer/notifications": { bn: "এই পর্দায় এই ভূমিকার জন্য পাঠানো ঘোষণা ও সতর্কবার্তাগুলো দেখা যায়। প্রতিটি বার্তার সঙ্গে সময় ও ধরন থাকায় কোনটি নতুন আর কোনটি আগে পড়া হয়েছে, তা আলাদা করা সহজ হয়। ব্যবহারকারী বার্তা খুলে বিস্তারিত পড়তে পারেন এবং কাজ শেষ হলে তালিকা থেকে সরে যেতে পারেন। জরুরি নির্দেশনা বা সময়সীমা সংক্রান্ত তথ্য যাতে সময়মতো নজরে আসে, তা এখানেই নিশ্চিত হয়। নতুন বার্তা এলে তা এই তালিকায় যুক্ত হয় এবং পড়া পর্যন্ত অপরিবর্তিত থাকে।", en: "This page shows the announcements and alerts sent for this role. With the time and type shown against each message, it is easy to tell what is new and what has already been read. A user can open a message to read it in full and clear it from the list once handled. This is where urgent instructions and deadline information are made sure to reach the right person in time." },
  "/dashboard/government-officer/profile": { bn: "এই পর্দায় লগইন করা ব্যক্তির নিজের অ্যাকাউন্ট তথ্য দেখা যায়, যা তিনি প্রয়োজন অনুযায়ী সম্পাদনা করতে পারেন। নাম, যোগাযোগ ও সংশ্লিষ্ট ভূমিকার তথ্য এক জায়গায় থাকায় ভুল হলে সহজেই ঠিক করা যায়। তথ্য বদলে সংরক্ষণ করলে তা পরবর্তী লগইন থেকেই প্রযোজ্য হয়। যোগাযোগের তথ্য সঠিক থাকলে ঘোষণা ও সতর্কবার্তা নির্দিষ্ট ব্যক্তির কাছে পৌঁছায়। অ্যাকাউন্টের সঙ্গে সংশ্লিষ্ট ভূমিকা ও প্রতিষ্ঠানের তথ্যও এখানে যুক্ত থাকে।", en: "This page shows the signed in person own account information, which they can edit as needed. Name, contact details and the associated role sit in one place, so anything incorrect is easy to correct. Once the changes are saved, they apply from the next sign in onward. Keeping contact details accurate also means announcements and alerts reach the right person." },
  "/dashboard/government-officer/programs": { bn: "এই পর্দায় সরকারি শিক্ষা কর্মসূচিগুলোর তালিকা ও তাদের নির্ধারিত লক্ষ্যমাত্রা দেখা যায়। প্রতিটি কর্মসূচির আওতা ও অগ্রগতি একসাথে থাকায় লক্ষ্যের কতটা কাছে পৌঁছানো গেছে তা বোঝা যায়। ব্যবহারকারী কর্মসূচি বেছে নিয়ে তার বিস্তারিত তথ্য দেখতে পারেন। কোন কর্মসূচিতে গতি বাড়ানো বা সমন্বয় দরকার, তা ঠিক করতে এই তুলনা কাজে লাগে। লক্ষ্যমাত্রার বিপরীতে কতটা কাজ শেষ হয়েছে, তা প্রতিটি কর্মসূচিতে আলাদা করে দেখা যায়।", en: "This page lists the government education programmes together with the targets set for each. Coverage and progress appear side by side, so it is clear how close a programme has come to its goal. A user can select a programme and open its details for review. The comparison supports decisions on where a programme needs more pace or better coordination." },
  "/dashboard/government-officer/reports": { bn: "এই পর্দায় এই ভূমিকার পরিধির ভেতরে থাকা সমন্বিত রিপোর্টগুলো দেখা যায়। প্রতিটি রিপোর্ট আলাদা করে না খুঁজে একই জায়গা থেকে প্রয়োজনীয় সারসংক্ষেপ বেছে নেওয়া যায়। ব্যবহারকারী রিপোর্ট খুলে বিস্তারিত দেখতে পারেন এবং প্রয়োজন অনুযায়ী নির্দিষ্ট সময় বা এলাকার চিত্র মিলিয়ে নিতে পারেন। নিয়মিত পর্যালোচনা সভা এবং ঊর্ধ্বতন কর্তৃপক্ষকে অবহিত করার কাজে এগুলো ব্যবহৃত হয়। একই জায়গা থেকে রিপোর্ট বেছে নিয়ে পর্যালোচনার কাজ শুরু করা যায়।", en: "This page gathers the consolidated reports that fall within the scope of this role. Instead of hunting for each one separately, a user can pick the summary needed from a single place. Reports can be opened for detail and checked against a particular period or area as required. They are used in regular review meetings and when keeping higher authorities informed." },
  "/dashboard/government-officer/reports/district-oversight": { bn: "এই রিপোর্টে জেলা তত্ত্বাবধানের একটি সার্বিক দৃশ্য দেখা যায়, যা কর্মকর্তার পরিদর্শনের প্রস্তুতিতে সহায়ক। কোন জেলায় প্রতিষ্ঠানের অবস্থা কেমন, কোথায় ঘাটতি জমেছে এবং কোথায় দ্রুত পদক্ষেপ দরকার, তা এক জায়গা থেকে বোঝা যায়। ব্যবহারকারী জেলা বেছে নিয়ে বিস্তারিত দেখতে পারেন এবং পরিদর্শনের অগ্রাধিকার ঠিক করতে পারেন। সফর পরিকল্পনা ও পরবর্তী নির্দেশনা দেওয়ার সময় এই চিত্র হাতে রাখা কাজে লাগে।", en: "This report gives a broad view of district oversight meant to prepare an officer for inspection. It shows from one place how institutions stand in a district, where shortfalls have gathered and where action is needed soon. A user can select a district to see the detail and settle the priority order for visits. Keeping this picture at hand helps when planning a tour and issuing follow up instructions." },
  "/dashboard/government-officer/reports/enrollment-trend": { bn: "এই রিপোর্টে নির্বাচিত সময়ে ভর্তির পরিবর্তন দেখা যায়। সময় ধরে সংখ্যা সাজিয়ে দেখলে ভর্তি বাড়ছে না কমছে, আর কোন সময়ে বাঁক নিয়েছে তা স্পষ্ট হয়। ব্যবহারকারী সময়সীমা বেছে নিয়ে নির্দিষ্ট প্রতিষ্ঠান বা জেলার ধারা দেখতে পারেন। এই প্রবণতা দেখে পরবর্তী সেশনের প্রস্তুতি এবং সম্পদ বণ্টনের সিদ্ধান্ত নেওয়া হয়। এই ধারা প্রতিষ্ঠান ও জেলা ধরে আলাদা করেও দেখা যায়, ফলে কোন জায়গায় পরিবর্তন বেশি তা বোঝা যায়।", en: "This report shows how enrolment has changed over the period selected. Placing the numbers across time makes it clear whether enrolment is rising or falling and roughly when the direction turned. A user can choose a period and look at the trend for a particular institution or district. The trend informs preparation for the next session and decisions on sharing resources." },
  "/dashboard/government-officer/reports/equity-indicators": { bn: "এই রিপোর্টে ইকুইটি সূচকগুলো বিস্তারিতভাবে দেখা যায়, যেখানে লিঙ্গ, অবস্থান ও প্রবেশগত বৈষম্য আলাদা করে হিসাব করা হয়। কোন গ্রুপ পিছিয়ে আছে এবং ব্যবধান কতটা বড়, তা সংখ্যা ও তুলনার মাধ্যমে বোঝা যায়। ব্যবহারকারী সূচক ও এলাকা বেছে নিয়ে সংশ্লিষ্ট ভাঙ্গন দেখতে পারেন। এই ব্যবধানগুলো নীতি নির্ধারণ এবং লক্ষ্যভিত্তিক সহায়তার ভিত্তি হিসেবে ব্যবহৃত হয়। সূচকের এই বিস্তারিত চিত্র প্রতিবেদনে ব্যবহারের উপযোগী করে সাজানো থাকে।", en: "This report sets out the equity indicators in detail, calculating gaps separately by gender, by location and by access. The numbers and comparisons show which group is behind and how wide the gap has grown. A user can pick an indicator and an area to see the breakdown behind it. These gaps serve as the basis for policy decisions and for support that is properly targeted to a group." },
  "/dashboard/government-officer/reports/safety-overview": { bn: "এই রিপোর্টে পর্যবেক্ষণাধীন প্রতিষ্ঠান জুড়ে এআই নিরাপত্তার সমন্বিত চিত্র তুলে ধরা হয়। কোন প্রতিষ্ঠানে কী ধরনের ঝুঁকি বা ঘটনা নথিভুক্ত হয়েছে এবং তার বর্তমান অবস্থা কী, তা একসাথে দেখা যায়। ব্যবহারকারী প্রতিষ্ঠান বেছে নিয়ে বিস্তারিত দেখতে পারেন এবং দ্রুত পদক্ষেপ দরকার এমন জায়গা চিহ্নিত করতে পারেন। তদারকি সভায় এই সারসংক্ষেপ দেখে পরবর্তী নির্দেশনা দেওয়া হয়। প্রতিষ্ঠান ধরে ধরে নিরাপত্তার চিত্র পাশাপাশি দেখলে তুলনা করা সহজ হয়।", en: "This report lays out a combined picture of AI safety across the institutions under observation. It shows together what kind of risk or incident has been recorded at each institution and what state it is in now. A user can select an institution for the detail and mark the places where action is needed quickly. The summary is used in oversight meetings to issue follow up instructions." },
  "/dashboard/government-officer/safety-overview": { bn: "এই পর্দায় পর্যবেক্ষণাধীন প্রতিষ্ঠান জুড়ে এআই নিরাপত্তার সমন্বিত চিত্র দেখা যায়। কোন প্রতিষ্ঠানে কী ধরনের ঝুঁকি বা ঘটনা নজরে এসেছে এবং সেগুলোর অবস্থা কী, তা এক জায়গায় মিলিয়ে দেখা সম্ভব হয়। ব্যবহারকারী প্রতিষ্ঠান বেছে নিয়ে বিস্তারিত দেখতে পারেন। তদারকি দল এই সারসংক্ষেপ দেখে দ্রুত পদক্ষেপ দরকার এমন প্রতিষ্ঠান চিহ্নিত করে। ঘটনার ধরন ও বর্তমান অবস্থা পাশাপাশি থাকায় কোনটি বেশি জরুরি তা বোঝা সহজ হয়।", en: "This screen gives a combined view of AI safety across the institutions under observation. It brings together which institutions have had what kind of risk or incident flagged and what state each one is in. A user can select an institution to look at the detail. The oversight team uses this summary to identify quickly the institutions that need action." },
  "/dashboard/ngo-admin/ai-pathshala/ai-tutor": { bn: "এখানে একটি চ্যাটভিত্তিক এআই টিউটর আছে, যা কেবল অনুমোদিত লেসন কনটেন্টের ভিত্তিতেই উত্তর দেয়। শিক্ষার্থী বা শিক্ষক প্রশ্ন লিখলে টিউটর প্রাসঙ্গিক লেসনের ভেতর থেকেই ব্যাখ্যা খুঁজে দেয়, তাই পাঠ্যবহির্ভূত তথ্য আসার ঝুঁকি থাকে না। চ্যাট পর্দাতেই প্রশ্ন ও উত্তরের ধারা দেখা যায়, ফলে একই প্রশ্ন বারবার করার দরকার হয় না। যেসব প্রতিষ্ঠান পাঠ্যসূচির বাইরে না গিয়ে সহায়তা চায়, তাদের জন্য এটি নিরাপদ সহায়ক।", en: "This page provides a chat based AI tutor that answers only from approved lesson content. When a student or teacher types a question, the tutor looks for the explanation inside the relevant lesson rather than pulling in outside information. The flow of questions and answers stays visible on the same screen, so a learner need not repeat the same query. It suits institutions that want guided help kept within the syllabus." },
  "/dashboard/ngo-admin/ai-pathshala/assessments": { bn: "এই পর্দায় অ্যাসেসমেন্টের তালিকা এবং প্রত্যেক শিক্ষার্থীর প্রাপ্ত নম্বর একসাথে দেখা যায়। ব্যবহারকারী নির্দিষ্ট অ্যাসেসমেন্ট বেছে নিয়ে কে কত নম্বর পেয়েছে তা মিলিয়ে দেখতে পারেন। নম্বরের পাশাপাশি শিক্ষার্থীর নাম ও সংশ্লিষ্ট ক্লাসের তথ্য থাকায় ফলাফল বোঝা সহজ হয়। শিক্ষক ও কর্মসূচি সমন্বয়করা এই নম্বর দেখে কে পিছিয়ে আছে তা চিহ্নিত করে পরবর্তী পদক্ষেপ নিতে পারেন। পাশাপাশি রাখা নম্বরের তুলনায় কোন বিষয়ে দুর্বলতা স্পষ্ট হয়ে ওঠে।", en: "This screen brings together the list of assessments and the marks each learner received. A user can open a particular assessment and check who scored what. With the learner name and the related class shown next to the marks, the results are easy to follow. Teachers and programme coordinators use these marks to spot who is falling behind and to decide the next step." },
  "/dashboard/ngo-admin/ai-pathshala/lesson-planner": { bn: "এই পর্দায় শিক্ষকের জন্য দিন-ভিত্তিক লেসন প্ল্যান দেখা ও তৈরি করা যায়। প্রতিটি প্ল্যানে কোন দিনে কোন বিষয় বা টপিক পড়ানো হবে তা ধাপে ধাপে সাজানো থাকে, ফলে ক্লাসের প্রস্তুতি আগেই নেওয়া সম্ভব হয়। শিক্ষক প্ল্যানটি খুলে ক্লাস চলাকালে ধাপ ধরে এগোতে পারেন এবং কোন অংশ কভার হয়েছে তা মিলিয়ে নিতে পারেন। একই কাঠামো একাধিক ক্লাসে ব্যবহার করা যায়, ফলে কর্মসূচির সব প্রতিষ্ঠানে পাঠদানের ধরন মোটামুটি একই থাকে।", en: "This screen lets a teacher build and review day wise plans. Each plan sets out which subject and topic will be taught on which day, step by step, so preparation can start well before the class. A teacher can open the plan during the lesson, move through the steps in order and check which parts have already been covered. The same structure can be reused across classes, which keeps teaching consistent across the programme." },
  "/dashboard/ngo-admin/ai-pathshala/lessons": { bn: "এই পর্দায় এআই পাঠশালার সব লেসন এক জায়গায় দেখা যায়, যা ক্লাস ও বিষয় অনুযায়ী সাজানো থাকে। ব্যবহারকারী তালিকা থেকে নির্দিষ্ট শ্রেণির লেসন বেছে নিয়ে ভেতরের কনটেন্ট পড়তে পারেন। প্রতিটি লেসনে বিষয়, ক্লাস ও সংক্ষিপ্ত বিবরণ একসাথে দেখানো হয়, ফলে ক্লাসের প্রস্তুতি নিতে কম সময় লাগে। যে সব শিক্ষক ও কর্মসূচি সমন্বয়ক ক্লাসে এআই কনটেন্ট ব্যবহার করেন, তাঁদের জন্য এটি মূল প্রবেশপথ।", en: "This screen lists every AI Pathshala lesson in one place, arranged by class and subject. Users can pick a specific grade from the list and open the lesson to read its content. Each entry shows its subject, class and a short summary together, so preparing for a session takes less time. It is the main entry point for teachers and programme coordinators who use AI content in class." },
  "/dashboard/ngo-admin/ai-pathshala/progress": { bn: "এই পর্দায় লগইন করা ব্যবহারকারীর নিজের অগ্রগতি টপিক ধরে দেখানো হয়। কোন বিষয়ে কতটা দক্ষতা তৈরি হয়েছে এবং কোন অংশ এখনো অসম্পূর্ণ, তা এক নজরে বোঝা যায়। ব্যবহারকারী টপিক বেছে নিয়ে বিস্তারিত দেখতে পারেন, ফলে কোথায় বেশি অনুশীলন দরকার তা স্পষ্ট হয়। এটি মূলত শিক্ষার্থী নিজে এবং তাঁর শিক্ষক—দুই পক্ষের জন্যই অগ্রগতি পর্যালোচনার জায়গা। অগ্রগতির এই চিত্র দেখে পরবর্তী ক্লাসে কোন অংশ আবার আলোচনা করা দরকার, সে সিদ্ধান্তও নেওয়া যায়।", en: "This screen shows the signed in user own progress topic by topic. It makes clear how much mastery has been built in each subject and which parts are still incomplete. A user can select a topic to see the detail, which highlights where more practice is needed. It is mainly a place for the learner and their teacher to review progress against the syllabus over time." },
  "/dashboard/ngo-admin/ai-pathshala/quizzes": { bn: "এখানে এআই দিয়ে তৈরি কুইজের তালিকা ও সেগুলোর বিস্তারিত দেখা যায়। শিক্ষার্থী কুইজ শেষ করে জমা দিলেই উত্তর স্বয়ংক্রিয়ভাবে যাচাই হয়ে ফলাফল তৈরি হয়, তাই শিক্ষককে আলাদা করে খাতা দেখতে হয় না। তালিকা থেকে নির্দিষ্ট ক্লাস বা বিষয়ের কুইজ বেছে নিয়ে প্রশ্নপত্র দেখা যায়। যেসব শিক্ষক নিয়মিত ছোট মূল্যায়ন চান, তাদের জন্য এটি দ্রুত ও কম পরিশ্রমের পথ। নতুন কুইজ তৈরি হলে তা একই তালিকায় যুক্ত হয়, ফলে পুরনো কুইজের সঙ্গে মিলিয়ে দেখা সহজ হয়।", en: "This page lists the quizzes generated with AI and shows the detail of each one. As soon as a learner finishes and submits a quiz, the answers are checked automatically and a result is produced, so a teacher does not have to mark scripts by hand. From the list, a quiz for a particular class or subject can be opened to review its questions. It gives teachers who want frequent short checks a fast route with little manual work." },
  "/dashboard/ngo-admin/ai-pathshala/study-plan": { bn: "এখানে সবচেয়ে দুর্বল টপিকগুলো চিহ্নিত করে একটি ব্যক্তিগত স্টাডি প্ল্যান তৈরি করা হয়। প্ল্যানে কোন টপিক আগে পড়তে হবে এবং কোনটি পরে, সেই ক্রম সাজিয়ে দেওয়া থাকে, ফলে প্রস্তুতি এলোমেলো হয় না। ব্যবহারকারী প্ল্যান দেখে ধাপে ধাপে এগোতে পারেন এবং অগ্রগতি পর্দার সঙ্গে মিলিয়ে অগ্রসরতা যাচাই করতে পারেন। যেসব শিক্ষার্থী নিজে থেকে পড়ার রুটিন ঠিক করতে পারে না, তাদের জন্য এটি বিশেষভাবে সহায়ক।", en: "This page builds a personal study plan around the topics where a learner is weakest. The plan sets the order in which topics should be studied, first things first, so preparation does not become scattered. A user can follow the plan step by step and check the movement against the progress screen. It particularly helps learners who struggle to set their own revision routine." },
  "/dashboard/ngo-admin/data-exports": { bn: "এই পাতায় দাতা ও অভ্যন্তরীণ প্রতিবেদনের জন্য কর্মসূচির ডেটা ডাউনলোড করা যায়। কোন কর্মসূচি বা প্রতিষ্ঠানের তথ্য কোন ফরমে বের করা হবে তা বেছে নিয়ে ফাইলটি নামানো হয়। প্রশাসক এই ফাইল দিয়ে নিজের হিসাব মেলাতে পারেন অথবা দাতার নির্ধারিত ছকে তথ্য জমা দিতে পারেন। এতে একই তথ্য বারবার হাতে তুলে লেখার দরকার হয় না এবং ভুলের আশঙ্কা কমে। একবার নামানো ফাইল পরে আবার ব্যবহার করা যায়, তাই প্রতিবার নতুন করে তৈরি করতে হয় না।", en: "Program data can be downloaded from this page for donor and internal reporting. The administrator chooses which program or institution to export and in what form, then takes the file away. That file supports their own reconciliation or fills the template a donor has set. Working from an export instead of retyping figures reduces both effort and the chance of error." },
  "/dashboard/ngo-admin/impact-analytics": { bn: "এই পাতায় সব কর্মসূচি ও জেলা জুড়ে প্রভাবের সামগ্রিক বিশ্লেষণ দেখা যায়। কোন এলাকায় কর্মসূচির প্রভাব বেশি আর কোথায় কম তা তুলনা করে বোঝা যায়, এবং শিক্ষার্থী, প্রতিষ্ঠান ও ফলাফলের চিত্র একসঙ্গে পাওয়া যায়। প্রশাসক এই বিশ্লেষণ দেখে সম্পদ বণ্টন ও ভবিষ্যৎ পরিকল্পনা নিয়ে সিদ্ধান্ত নিতে পারেন। একাধিক জেলার তথ্য একসঙ্গে দেখলে সামগ্রিক অগ্রগতির ধরন স্পষ্ট হয়। কোন জেলায় সম্পদ বাড়ানো দরকার তা নিয়ে সিদ্ধান্তও এর ভিত্তিতে নেওয়া হয়।", en: "This page holds the overall impact analysis across all programs and districts. It compares where a program is making a difference and where it is not, bringing learner, institution and outcome figures together. An administrator uses it to decide on resource allocation and future planning. Seeing several districts side by side makes the wider pattern of progress clear." },
  "/dashboard/ngo-admin/institutions": { bn: "এই পাতায় এনজিওর নিজস্ব পরিচালনায় থাকা এবং পার্টনার হিসেবে যুক্ত প্রতিষ্ঠানগুলোর তালিকা দেখা যায়। প্রতিটি প্রতিষ্ঠানের ধরন, কোন কর্মসূচির সঙ্গে যুক্ত এবং বর্তমান অবস্থা এখানে উল্লেখ থাকে। প্রশাসক তালিকা দেখে বুঝতে পারেন কোন প্রতিষ্ঠান সরাসরি পরিচালিত আর কোনটি পার্টনারের মাধ্যমে চলছে। এতে অংশীদারিত্বের পরিধি এবং প্রতিটি প্রতিষ্ঠানের সঙ্গে সম্পর্কের ধরন স্পষ্ট থাকে। প্রতিষ্ঠানের তথ্য হালনাগাদ থাকলে পরবর্তী রিপোর্ট তৈরি করাও নির্ভুল হয়।", en: "This page lists the institutions the NGO operates directly alongside those attached as partners. Each entry shows the type of institution, the program it belongs to, and its current status. From the list an administrator can tell which sites are run in house and which operate through a partner. That makes the scale of the partnership and the nature of each relationship clear." },
  "/dashboard/ngo-admin/interventions": { bn: "এই পাতায় পিছিয়ে পড়া শিক্ষার্থীদের জন্য নেওয়া সহায়তা পরিকল্পনাগুলো দেখা যায়। কোন শিক্ষার্থীর জন্য কী ধরনের সহায়তা নির্ধারণ করা হয়েছে, তা কে পরিচালনা করছেন এবং এখন পর্যন্ত কী ফল মিলেছে তা এখানে থাকে। প্রশাসক পরিকল্পনাগুলো দেখে বুঝতে পারেন কোন ধরনের সহায়তা কাজ করছে আর কোনটি বদলানো দরকার। এতে সীমিত সম্পদ সবচেয়ে প্রয়োজনের জায়গায় ব্যবহার করা সহজ হয়। কোন পরিকল্পনা কত দিন ধরে চলছে এবং কে তার ফলোআপ করছেন তাও এখানে দেখা যায়।", en: "Support plans drawn up for learners who have fallen behind are shown here. Each plan records what help was arranged, who is running it, and what result has followed so far. Reading across the plans shows which kinds of support are working and which need changing. That helps direct limited resources to where the need is greatest. The plans also show which learners they cover and where follow-up stands." },
  "/dashboard/ngo-admin/learners": { bn: "এই পাতায় কর্মসূচিতে অন্তর্ভুক্ত শিক্ষার্থীদের তালিকা দেখা যায়, সঙ্গে থাকে কোহোর্ট ও তাদের অগ্রগতির চিত্র। কোন শিক্ষার্থী কোন কোহোর্টে পড়ছে, কোন স্কুলে যুক্ত এবং কতটা এগিয়েছে তা একসঙ্গে পাওয়া যায়। প্রশাসক এই তথ্য দেখে বুঝতে পারেন কোন কোহোর্ট ভালো করছে আর কোথায় অতিরিক্ত সহায়তা দরকার। শিক্ষার্থীর সংখ্যা ও অগ্রগতি একসঙ্গে দেখলে কর্মসূচির প্রকৃত অবস্থা স্পষ্ট হয়। শিক্ষার্থীর তথ্য এক জায়গায় থাকায় সহায়তা পরিকল্পনা করাও সহজ হয়।", en: "Learners enrolled across the programs are listed here with their cohort and progress. Each entry shows which cohort a learner belongs to, the school they attend, and how far they have come. An administrator reading this can see which cohorts are doing well and where extra support is needed. Numbers and progress together give a realistic picture of how a program is performing." },
  "/dashboard/ngo-admin/learning-outcomes": { bn: "এই পাতায় কর্মসূচি ও কোহোর্টভিত্তিক শেখার ফলাফল দেখা যায়। কোন কর্মসূচিতে শিক্ষার্থীরা কতটা শিখছে এবং কোহোর্টভেদে এই ফলাফল কেমন আলাদা হয় তা তুলনা করা যায়। প্রশাসক এই চিত্র দেখে বুঝতে পারেন কোন কোহোর্ট বা কর্মসূচিতে উন্নতি দরকার এবং কোথায় কাজ ভালো হচ্ছে। সময়ের সঙ্গে ফলাফল মিলিয়ে দেখলে নেওয়া উদ্যোগের প্রভাবও বোঝা যায়। ফলাফল কম হলে সংশ্লিষ্ট কোহোর্টের দিকে আলাদা করে নজর দেওয়া যায়। এই তুলনা থেকেই বোঝা যায় কোথায় পাঠদান পদ্ধতি বদলানো দরকার।", en: "Learning outcomes by program and cohort are shown here. It becomes possible to compare how much learners are picking up in each program and how results differ between cohorts. An administrator reading this sees which cohort or program needs improvement and where work is going well. Tracking outcomes over time also shows whether the steps taken are having effect." },
  "/dashboard/ngo-admin/notifications": { bn: "এই পাতায় এই ভূমিকার জন্য প্রযোজ্য ঘোষণা ও সতর্কবার্তাগুলো জমা হয়। কর্মসূচি সংক্রান্ত ঘোষণা, সময়সীমার কথা বা নজর দেওয়ার মতো বিষয় এখানে জানানো হয়। প্রশাসক তালিকা দেখে প্রয়োজনীয় বিষয় দ্রুত খুঁজে নিয়ে সংশ্লিষ্ট কাজে এগোতে পারেন। পড়া হয়ে গেলে ঘোষণা আলাদা হয়ে যায়, ফলে কোনটি এখনো দেখা হয়নি তা সহজেই বোঝা যায়। ঘোষণা পড়ার পর সংশ্লিষ্ট কাজ শেষ হলে তালিকা হালকা হয়, ফলে নতুন বার্তা সহজে নজরে পড়ে। জরুরি সতর্কবার্তায় দ্রুত পদক্ষেপ নেওয়া যায়।", en: "Announcements and alerts meant for this role collect on this page. Program notices, deadline reminders and items worth attention are reported here. The administrator scans the list and moves on to whatever it points at. Once read, an item is set apart from the rest, so anything unseen stays easy to identify. Urgent alerts are acted on promptly, so nothing important is left aside." },
  "/dashboard/ngo-admin/profile": { bn: "এই পাতায় লগইন করা ব্যক্তির নিজের অ্যাকাউন্ট তথ্য দেখা যায় এবং সম্পাদনা করা যায়। নাম, যোগাযোগের বিবরণ ও ছবির মতো তথ্য এখানে হালনাগাদ করা হয়, যাতে সংস্থার রেকর্ডে সঠিক বিবরণ থাকে। নিজের অ্যাকাউন্ট হওয়ায় পরিবর্তন কেবল সংশ্লিষ্ট ব্যক্তির তথ্যেই সীমাবদ্ধ থাকে, অন্যের ভূমিকা বা অনুমতিতে হাত পড়ে না। ভুল বা পুরনো তথ্য চোখে পড়লে এখান থেকেই সংশোধন করা যায়। নিজের তথ্য হালনাগাদ থাকলে সংস্থার যোগাযোগ ও রেকর্ড নির্ভুল থাকে।", en: "This page shows the signed-in person's own account details and allows them to be edited. Name, contact details and picture are updated here so organisation records stay correct. Being their own account, changes touch only that person's details and no one else's role. Anything stale or wrong is corrected here rather than through an administrator. Current details keep organisation contact records accurate." },
  "/dashboard/ngo-admin/programs": { bn: "এই পাতায় এনজিওর পরিচালিত শিক্ষা কর্মসূচিগুলোর তালিকা দেখা যায়, প্রতিটির সঙ্গে আওতাভুক্ত স্কুল ও নির্ধারিত লক্ষ্যমাত্রা থাকে। কোন কর্মসূচি কোথায় চলছে, কতগুলো প্রতিষ্ঠান এতে যুক্ত এবং লক্ষ্যমাত্রার কতটা অর্জিত হয়েছে তা একসঙ্গে বোঝা যায়। প্রশাসক প্রতিটি কর্মসূচি খুলে তার বিবরণ দেখতে ও প্রয়োজন অনুযায়ী হালনাগাদ করতে পারেন। একাধিক কর্মসূচি একসঙ্গে চললেও কোনটিতে বেশি মনোযোগ দরকার তা এই তালিকা থেকেই বোঝা যায়।", en: "This page lists the education programs the NGO runs, each with its schools and its stated targets. It shows where a program is active, how many institutions are attached, and how much of the target has been met. An administrator can open any program to read its details and update them as needed. With several programs running at once, the list makes it clear where attention is most needed." },
  "/dashboard/ngo-admin/reports": { bn: "এই পাতায় দাতাদের জন্য প্রস্তুত করা কর্মসূচি ও প্রতিষ্ঠানভিত্তিক রিপোর্ট দেখা যায়। প্রতিটি রিপোর্টে কর্মসূচির অগ্রগতি, আওতাভুক্ত প্রতিষ্ঠান ও শিক্ষার্থীর চিত্র তুলে ধরা হয়। প্রশাসক রিপোর্ট দেখে যাচাই করে নেন এবং দাতার কাছে উপস্থাপনের জন্য প্রস্তুত করতে পারেন। নিয়মিত রিপোর্ট রাখলে অর্থায়নের হিসাব ও অর্জনের প্রমাণ একসঙ্গে সংরক্ষিত থাকে। প্রতিটি রিপোর্ট নির্দিষ্ট সময়ের কর্মকাণ্ড ধরে তৈরি হয়, তাই আগের সময়ের সঙ্গে তুলনা করা সহজ হয় এবং অগ্রগতির ধরন স্পষ্ট থাকে।", en: "Program and institution reports prepared for donors are available on this page. Each report sets out a program's progress together with the institutions and learners it covers. An administrator reviews them and gets them ready for presentation to a donor. Keeping these reports current means both the account of funds and the evidence of results are held in one place." },
  "/dashboard/ngo-admin/reports/beneficiary-reach": { bn: "এই পর্দায় জেলা ধরে দেখা যায় কতজন শিক্ষার্থী ও কতগুলো স্কুল পর্যন্ত কার্যক্রম পৌঁছেছে। জেলাভিত্তিক সংখ্যা পাশাপাশি বসিয়ে দেখলে কোন এলাকায় উপস্থিতি বেশি আর কোথায় কম, তা স্পষ্ট হয়। ব্যবহারকারী জেলা বেছে নিয়ে বিস্তারিত সংখ্যা দেখতে পারেন। সম্পদ ও সহায়তা কোথায় বেশি দরকার, তা নির্ধারণে এই চিত্র সহায়ক। শিক্ষার্থী ও স্কুলের সংখ্যা আলাদা করে দেখানো থাকায় দুই ধরনের আওতা মিলিয়ে বোঝা যায়।", en: "This page shows, district by district, how many learners and how many schools the work has reached. Placing the district figures side by side makes it plain where presence is strong and where it is weak. A user can select a district to see the detail behind the numbers. The picture helps decide where resources and support are most needed." },
  "/dashboard/ngo-admin/reports/institution-coverage": { bn: "এই পর্দায় দেখা যায় প্রতিটি কর্মসূচি কতগুলো প্রতিষ্ঠানে পৌঁছেছে। কর্মসূচি অনুযায়ী প্রতিষ্ঠানের সংখ্যা ও তালিকা একসাথে থাকায় আওতা কোথায় ঘন এবং কোথায় পাতলা, তা বোঝা যায়। ব্যবহারকারী কর্মসূচি বেছে নিয়ে সংশ্লিষ্ট প্রতিষ্ঠানগুলো দেখতে পারেন। নতুন এলাকায় সম্প্রসারণের পরিকল্পনা করার সময় এই তথ্য সিদ্ধান্ত নিতে সাহায্য করে। কোন কর্মসূচি কোন জেলায় কত প্রতিষ্ঠানে পৌঁছেছে, তাও এখান থেকে বোঝা যায়।", en: "This page shows how many institutions each programme has reached. With the count and the list of institutions grouped by programme, it becomes clear where coverage is dense and where it is thin. A user can select a programme and see the institutions attached to it. The information supports decisions when planning expansion into new areas." },
  "/dashboard/ngo-admin/reports/learning-outcomes": { bn: "এই রিপোর্টে কর্মসূচি ও কোহোর্ট ধরে শিক্ষার ফলাফল দেখা যায়। কোন কোহোর্ট কেমন এগিয়েছে এবং কোন কর্মসূচিতে ফলাফল প্রত্যাশার কাছাকাছি বা দূরে, তা তুলনা করে বোঝা যায়। ব্যবহারকারী নির্দিষ্ট কর্মসূচি বা কোহোর্ট বেছে নিয়ে বিস্তারিত ফলাফল দেখতে পারেন। শিক্ষা দল এই তুলনা দেখে পাঠদান পদ্ধতি ও সহায়তা কোথায় বদলানো দরকার তা ঠিক করে। ফলাফলের এই তুলনা শিক্ষার্থীর শেখার ধারাবাহিকতা যাচাই করতেও কাজে লাগে।", en: "This report presents learning outcomes broken down by programme and cohort. It allows a reader to compare how cohorts have moved and which programmes sit close to or far from expectations. A user can pick a particular programme or cohort to see the outcome detail. The education team uses the comparison to decide where the teaching approach and support need to change." },
  "/dashboard/ngo-admin/reports/program-impact": { bn: "এই রিপোর্টে কর্মসূচি ধরে ধরে প্রভাবের সারসংক্ষেপ দেখা যায়। কোন কর্মসূচি কতটা পরিবর্তন এনেছে এবং তার আওতায় কী পরিমাণ কাজ হয়েছে, তা একসাথে মিলিয়ে দেখা সম্ভব হয়। ব্যবহারকারী একটি নির্দিষ্ট কর্মসূচি বেছে নিয়ে তার চিত্র অন্যগুলোর সঙ্গে তুলনা করতে পারেন। ব্যবস্থাপনা পর্ষদ ও দাতাদের কাছে অগ্রগতি তুলে ধরার সময় এই সারসংক্ষেপ কাজে লাগে। প্রতিটি কর্মসূচির সংখ্যা একই কাঠামোয় দেখানো হয়, ফলে একটির সঙ্গে অন্যটি মেলানো সহজ হয়।", en: "This report gives a summary of impact, programme by programme. It lets a reader see together how much change each programme has brought and how much work has been done under it. A user can select one programme and compare its picture with the others. The summary is useful when presenting progress to a management board or to donors." },
  "/dashboard/ngo-admin/schools": { bn: "এই পাতায় প্রতিটি কর্মসূচির আওতাভুক্ত স্কুলগুলোর তালিকা দেখা যায়, সঙ্গে থাকে অবস্থান ও বর্তমান অবস্থা। কোন স্কুল কোন এলাকায় আছে, কোন কর্মসূচির অধীনে চলছে এবং সক্রিয় কি না তা একসঙ্গে বোঝা যায়। প্রশাসক অবস্থান অনুযায়ী স্কুল খুঁজে নিয়ে সংশ্লিষ্ট তথ্য দেখতে পারেন। এতে কোন এলাকায় কর্মসূচির বিস্তার বেশি আর কোথায় ঘাটতি আছে তা সহজে বোঝা যায়। স্কুলের অবস্থা বদলালে তালিকাতেই তা প্রতিফলিত হয়, তাই পুরনো তথ্য নিয়ে বিভ্রান্তি হয় না।", en: "The schools covered by each program are listed here with their location and current status. Each row shows where the school sits, which program it runs under, and whether it is active. An administrator can locate a school and open its details. Reading the list by location shows where a program has reach and where coverage is thin." },
  "/dashboard/ngo-admin/settings": { bn: "এই পাতায় প্রতিষ্ঠানের মূল সেটিংসগুলো দেখা যায় ও পরিবর্তন করা যায়। প্রতিষ্ঠানের পরিচিতি, চলতি সেশন, গ্রেডিং পদ্ধতি এবং যোগাযোগের বিবরণ এখানে নির্ধারিত হয়। প্রশাসক এই মানগুলো ঠিক করলে পুরো সিস্টেমে সেগুলোই অনুসরণ করা হয়, তাই শুরুতে একবার ভালোভাবে যাচাই করে নেওয়া প্রয়োজন। কোনো তথ্য বদলালে তার প্রভাব সম্পর্কিত রেকর্ডেও পড়ে, তাই পরিবর্তনের আগে ভেবে নেওয়া উচিত। সেটিংসে করা পরিবর্তন সব ব্যবহারকারীর কাজে প্রভাব ফেলে, তাই তা সংরক্ষণের আগে যাচাই করা ভালো।", en: "The organisation's core settings are viewed and changed here. Identity details, the running session, the grading method and communication details are all set on this page. Because the rest of the system follows these values, they are worth checking carefully rather than changing casually. A change here also affects the records that depend on it. Because the effect is organisation wide, changes are checked before saving." },
  "/dashboard/ngo-admin/teachers": { bn: "এই পাতায় কর্মসূচির প্রতিষ্ঠানগুলোতে কর্মরত শিক্ষকদের তালিকা দেখা যায়। কোন শিক্ষক কোন প্রতিষ্ঠানে পড়াচ্ছেন, কোন কর্মসূচির সঙ্গে যুক্ত এবং তাঁর ভূমিকা কী তা এখানে উল্লেখ থাকে। প্রশাসক এই তালিকা দেখে প্রতিষ্ঠানভিত্তিক জনবল পরিস্থিতি বুঝতে পারেন এবং কোথায় শিক্ষকের প্রয়োজন আছে তা নির্ধারণ করতে পারেন। শিক্ষকদের তথ্য এক জায়গায় থাকায় যোগাযোগ ও সমন্বয়ও সহজ হয়। শিক্ষকের ভূমিকা ও প্রতিষ্ঠান মিলিয়ে দেখলে জনবল পরিকল্পনা সহজ হয়।", en: "Teachers working at the program institutions are listed here. Each entry shows which institution a teacher serves, the program they are attached to, and their role. The list lets an administrator judge staffing at each site and see where teachers are still needed. Keeping teacher records in one place also makes contact and coordination simpler. Teacher records also support planning how staff are spread across sites." },
  "/dashboard/parent/ai-pathshala/ai-tutor": { bn: "চ্যাটভিত্তিক এই টিউটর শুধু অনুমোদিত লেসন কনটেন্ট থেকে উত্তর দেয়, তাই বাইরের অনির্ভরযোগ্য উৎসের উপর নির্ভর করতে হয় না। প্রশ্ন লিখলে লেসনের ভেতরের তথ্য ধরে উত্তর তৈরি হয়। কোন লেসন থেকে উত্তর এসেছে তা বোঝার সুযোগ থাকায় যাচাই করা সহজ। পড়াশোনায় সহায়তার পাশাপাশি অনুমোদিত পাঠ্যক্রমের সীমা মেনে চলা নিশ্চিত হয়। লেসনে উত্তর না থাকলে টিউটর নিজে থেকে অনুমান করে কিছু বানায় না, বরং অনুমোদিত সীমার ভেতরেই থাকে।", en: "A chat-based tutor that answers only from approved lesson content, so replies stay inside the reviewed syllabus rather than drawing on outside sources. The user types a question and receives an answer grounded in the lesson material. Because the answer follows the approved content, it is easy to check against what the class is actually studying. Support at home therefore remains consistent with what teachers deliver." },
  "/dashboard/parent/ai-pathshala/assessment-results": { bn: "সংযুক্ত সন্তানের অ্যাসেসমেন্ট ফলাফল এখানে একসাথে দেখা যায়, প্রতিটি অ্যাসেসমেন্টে প্রাপ্ত নম্বরসহ। ফলাফল দেখে বোঝা যায় কোন বিষয়ে সন্তান ভালো করছে আর কোথায় সহায়তা দরকার। সময়ের সাথে ফলাফলের ধারা মিলিয়ে দেখলে উন্নতি বা পিছিয়ে পড়া স্পষ্ট হয়। অভিভাবক হিসেবে এই তথ্য শিক্ষকের সাথে আলোচনার ভিত্তি হিসেবে ব্যবহার করা যায়। একই সন্তানের একাধিক ফলাফল পাশাপাশি দেখে বোঝা যায় কোন বিষয়ে ধারাবাহিক দুর্বলতা চলছে।", en: "Assessment results for the linked child are gathered in one place, with the marks obtained in each assessment. Reading them shows which subjects the child handles well and where help is needed. Set against each other over time, the results make improvement or decline visible instead of a string of isolated scores. Parents can take the same figures into a conversation with the teacher." },
  "/dashboard/parent/ai-pathshala/assessments": { bn: "অ্যাসেসমেন্টের তালিকা এবং প্রত্যেক শিক্ষার্থীর প্রাপ্ত নম্বর এখানে দেখা যায়। প্রতিটি অ্যাসেসমেন্টে কোন ক্লাস ও টপিক জড়িত তা বোঝা যায়, ফলে ফলাফলের পটভূমি স্পষ্ট থাকে। শিক্ষার্থীভিত্তিক নম্বর মিলিয়ে দেখে কে কোথায় এগিয়ে বা পিছিয়ে তা নির্ধারণ করা যায়। অভিভাবক হিসেবে সন্তানের অবস্থান বুঝে পরবর্তী পদক্ষেপ নেওয়ার সুযোগ এখান থেকেই তৈরি হয়। প্রয়োজনে ফলাফলের বিস্তারিত দেখে কোন অংশে নম্বর কমেছে তাও যাচাই করা যায়।", en: "Lists the assessments in use together with the marks each student obtained. Every assessment shows the class and topic it covers, so a score can be read in its proper context rather than as a bare number. Comparing marks across students shows who is ahead and who has fallen behind. For a parent this is the starting point for deciding what support the child needs next." },
  "/dashboard/parent/ai-pathshala/lesson-planner": { bn: "দিন-ভিত্তিক এই প্ল্যানার দেখায় কোন দিনে কোন লেসন বা টপিক পড়ানো হবে, যা শিক্ষক ক্লাসে অনুসরণ করতে পারেন। প্রতিটি দিনের পরিকল্পনায় বিষয় ও ক্রম সাজানো থাকে, ফলে পাঠদান এলোমেলো হয় না। অভিভাবক হিসেবে এই সময়সূচি দেখে সন্তানের প্রস্তুতি নেওয়া যায় এবং কোন অংশ আসছে তা আগেই জানা যায়। এতে শ্রেণিকক্ষের পাঠ্যক্রম ও বাড়ির পড়াশোনার মধ্যে সমন্বয় সহজ হয়। কোন সপ্তাহে পাঠ বেশি জমে আছে তাও আগেই বোঝা যায়, ফলে অভিভাবক ও শিক্ষার্থী উভয়ের প্রস্তুতি নেওয়া সহজ হয়।", en: "The day-by-day planner sets out which lesson or topic falls on which date, in the order teachers follow in class. Each day carries its subject and sequence, so instruction stays on a planned track rather than drifting. Parents can use the same schedule to prepare a child in advance and to see what is coming next. This keeps classroom teaching and home study working from one timetable." },
  "/dashboard/parent/ai-pathshala/lessons": { bn: "ক্লাস ও বিষয় অনুযায়ী সাজানো কাঠামোবদ্ধ এআই লেসন এখানে দেখা যায়। প্রতিটি লেসন নির্দিষ্ট ক্লাস ও বিষয়ের সাথে যুক্ত, তাই অভিভাবক সহজেই বুঝতে পারেন সন্তান কী পড়ছে। লেসন খুলে বিষয়বস্তু দেখা যায় এবং কোনগুলো সম্পন্ন হয়েছে তা বোঝা যায়। এই তালিকাই এআই পাঠশালার কুইজ, অ্যাসেসমেন্ট ও অগ্রগতি হিসাবের ভিত্তি। কোন লেসন কোন বিষয়ের অধীনে পড়ছে তা দেখে বোঝা যায় পাঠ্যক্রমের ক্রম ঠিক আছে কি না, আর সন্তানের পড়ার গতি কোথায় দাঁড়িয়ে আছে।", en: "Structured AI lessons are listed here, organised by class and subject so the syllabus is easy to follow. Each lesson is tied to a specific class and subject, which makes clear what the child is studying at any point. Opening a lesson shows its content and whether it has been completed. This list is the base the quizzes, assessments and topic progress figures are built on." },
  "/dashboard/parent/ai-pathshala/progress": { bn: "টপিক ধরে মাস্টারি অগ্রগতি এখানে দেখানো হয়, অর্থাৎ কোন বিষয়ে দখল কতটা তৈরি হয়েছে তা বোঝা যায়। লগইন করা ব্যবহারকারীর নিজের অগ্রগতিই এই পাতায় দেখা যায়, তাই প্রতিবার আলাদা করে প্রসঙ্গ মেলাতে হয় না। যে টপিকগুলোতে দুর্বলতা আছে সেগুলো আলাদা করে চোখে পড়ে। এই চিত্রই পরে স্টাডি প্ল্যান ও সতর্কবার্তা তৈরির ভিত্তি হিসেবে কাজ করে। এই চিত্র সময়ের সাথে বদলায়, তাই নিয়মিত দেখলে উন্নতির গতি বোঝা যায় এবং দুর্বলতা জমে থাকতে দেখা যায় না।", en: "Topic-wise mastery progress is shown here, so it is clear how well each topic has actually been grasped. The page covers the progress of the user who is logged in, which means the figures always belong to the right learner. Topics still showing weakness stand out from the rest. This view is what the study plan and the weak topic alerts are later built on." },
  "/dashboard/parent/ai-pathshala/quizzes": { bn: "এআই-জেনারেটেড কুইজের তালিকা এখানে দেখা যায়, প্রতিটি কুইজ নির্দিষ্ট লেসন বা টপিকের সাথে যুক্ত। শিক্ষার্থী জমা দেওয়ার সাথে সাথেই উত্তর যাচাই হয়ে ফলাফল তৈরি হয়, তাই আলাদা মূল্যায়নের অপেক্ষা করতে হয় না। কোন কুইজে কত নম্বর এসেছে তা দেখা যায় এবং দুর্বল বিষয়গুলো চিহ্নিত হয়। এই ফলাফলই পরে অগ্রগতি ও স্টাডি প্ল্যান তৈরিতে ব্যবহার হয়। কোন প্রশ্নে বেশি ভুল হচ্ছে তা দেখে সংশ্লিষ্ট লেসনের অংশটি আবার পড়ার পরামর্শ দেওয়া যায়।", en: "AI-generated quizzes are listed here, each linked to the lesson or topic it was built from. Answers are checked as soon as a student submits, so a score is available without waiting for separate marking. The list shows how each attempt scored and brings out the areas that went wrong. Those results then feed the progress figures and the study plan." },
  "/dashboard/parent/ai-pathshala/reports": { bn: "এআই পাঠশালা গ্রুপের ভেতরের রিপোর্টগুলো এখানে পাওয়া যায়, যা লেসন, কুইজ ও অগ্রগতির তথ্য একসাথে দেখায়। প্রতিটি রিপোর্ট নির্দিষ্ট প্রশ্নের উত্তর দেয়, তাই আলাদা করে হিসাব কষতে হয় না। রিপোর্ট দেখে বোঝা যায় কোন ক্লাস বা টপিকে ফলাফল কেমন এবং কোথায় হস্তক্ষেপ দরকার। অভিভাবক ও শিক্ষকের জন্য এটি অগ্রগতি নিয়ে আলোচনার সাধারণ ভিত্তি তৈরি করে। কোন রিপোর্ট কোন সময়ের তথ্য নিয়ে তৈরি তা উল্লেখ থাকে, তাই পুরোনো ও নতুন হিসাব মিশে যায় না।", en: "Holds the reports that sit inside the AI Pathshala group, drawing lesson, quiz and progress information together. Each report answers a particular question, so no separate tallying is needed before a decision. They show how a class or topic is performing and where intervention is warranted. Parents and teachers can work from the same view when discussing a child." },
  "/dashboard/parent/ai-pathshala/study-activity": { bn: "সন্তান প্রতিদিন কত সময় এবং কতবার পড়েছে তার হিসাব এখানে দেখা যায়। প্রতিদিনের কার্যক্রমের পাশাপাশি সাম্প্রতিক দিনগুলোর ধারা মিলিয়ে বোঝা যায় পড়াশোনার অভ্যাস কেমন চলছে। কম পড়ার দিনগুলো আলাদা করে চোখে পড়ে, ফলে সময়মতো অভিভাবকীয় নজর দেওয়া যায়। এই তথ্য পড়ার পরিমাণ ও নিয়মিততার চিত্র দেয়, গুণগত মূল্যায়ন নয়। সপ্তাহের কোন দিনগুলোতে পড়া কমেছে তা দেখে সময়ভিত্তিক কারণ খোঁজা যায়, যেমন পরীক্ষা বা অন্য ব্যস্ততা।", en: "Shows how long the child studied each day and how many sessions that involved. Looking at the daily activity alongside the pattern of recent days makes the study habit visible, not just a single figure. Days with little or no reading stand out, so a parent can step in before a gap widens. These are measures of volume and regularity rather than of quality." },
  "/dashboard/parent/ai-pathshala/study-plan": { bn: "সবচেয়ে দুর্বল টপিক চিহ্নিত করে তৈরি করা ব্যক্তিগত স্টাডি প্ল্যান এখানে দেখা যায়। কোন টপিক আগে পড়া দরকার এবং কোন ক্রমে এগোলে দুর্বলতা কমবে তা পরিকল্পনায় সাজানো থাকে। পরিকল্পনাটি একজন ব্যবহারকারীর জন্য তৈরি, তাই প্রত্যেকের প্রয়োজন অনুযায়ী আলাদা পথ থাকে। এই ক্রম অনুসরণ করে পড়লে অগ্রগতির গতি ধরে রাখা সহজ হয়। পরিকল্পনার কোন ধাপ শেষ হয়েছে তা চিহ্নিত করা যায়, ফলে প্রতিদিন কী পড়তে হবে তা নিয়ে দ্বিধা থাকে না।", en: "A personal study plan built from the weakest topics is presented here. It sets out which topic to take first and in what order to move so that the gaps close fastest. Because the plan is drawn for one learner, two students do not follow the same route. Working through it in the given order keeps progress steady instead of scattering effort." },
  "/dashboard/parent/attendance": { bn: "এই পেজে সংযুক্ত সন্তানের উপস্থিতির রেকর্ড দেখা যায়। কোন দিনে সন্তান ক্লাসে উপস্থিত ছিল, অনুপস্থিত ছিল বা দেরিতে এসেছে তা তারিখ ধরে দেখা যায়, ফলে নিয়মিত উপস্থিতি নিয়ে অভিভাবকের স্পষ্ট ধারণা তৈরি হয়। দীর্ঘদিনের অনুপস্থিতি চোখে পড়লে সময়মতো শিক্ষকের সঙ্গে আলোচনা করা যায়। স্কুলে যাওয়া নিয়ে সন্তানের সঙ্গে কথা বলার সময়ও এই রেকর্ড সহায়ক হয়। উপস্থিতির ধারা নিয়মিত দেখলে সন্তানের রুটিন নিয়ে আগেই সতর্ক হওয়া যায়।", en: "This page shows the attendance record of the linked child. By date, it shows whether the child was present, absent, or late, which gives the parent a clear picture of regular attendance. If a long absence appears, the teacher can be approached in good time. The record is also useful ground for talking with the child about going to school." },
  "/dashboard/parent/children": { bn: "এই পেজে এই অভিভাবক অ্যাকাউন্টের সঙ্গে যুক্ত সন্তানদের তালিকা দেখা যায়। কোন সন্তান কোন ক্লাসে পড়ছে এবং তাদের সংশ্লিষ্ট তথ্য এক জায়গায় থাকায় প্রতিবার আলাদা করে খোঁজার দরকার হয় না। তালিকা থেকে সন্তান বেছে নিয়ে তার উপস্থিতি, অগ্রগতি ও সম্পর্কিত তথ্য দেখা যায়। একাধিক সন্তান থাকলে একই অ্যাকাউন্টে সবার অবস্থা আলাদা করে বুঝতে সুবিধা হয়। একই অ্যাকাউন্ট থেকে সন্তানদের রেকর্ড দেখা হলে অভিভাবকের কাজ অনেক সহজ হয়।", en: "This page lists the children linked to this parent account. Which class each child attends and their details sit in one place, so nothing has to be looked up separately each time. A parent can select a child from the list and review attendance, progress, and related information. Where there is more than one child, the account keeps each one's position distinct." },
  "/dashboard/parent/link-child": { bn: "এই পেজে স্কুলের দেওয়া কোড ব্যবহার করে অ্যাকাউন্টে আরেক সন্তান যুক্ত করা যায়। নির্ধারিত ঘরে কোডটি লিখলে সন্তানের রেকর্ড যাচাই হয়ে অ্যাকাউন্টের সঙ্গে সংযুক্ত হয়, ফলে আলাদা অ্যাকাউন্ট খোলার দরকার হয় না। সংযোগ সফল হলে সন্তানটি তালিকায় যুক্ত হয় এবং তার রেকর্ডও অভিভাবকের কাছে দেখা যায়। কোডটি সঠিক না হলে সংযোগ সম্পন্ন হয় না, তাই স্কুলের দেওয়া কোড হুবহু মিলিয়ে নেওয়া দরকার। একই স্কুলে পড়া অন্য সন্তানকেও একইভাবে যুক্ত করা যায়।", en: "This page lets a parent link another child to the account using a code issued by the school. Once the code is entered, the child's record is verified and attached, so no second account is needed. When the link succeeds the child appears in the children list and their records become available to the parent. An incorrect code will not link, so it should be matched exactly as the school gave it." },
  "/dashboard/parent/notifications": { bn: "অভিভাবকের জন্য জারি করা সব ঘোষণা, নোটিশ ও সতর্কবার্তা এখানে এক জায়গায় দেখা যায়। অপঠিত আইটেম আলাদা করে চিহ্নিত থাকে, তাই জরুরি বার্তা বাদ পড়ার ঝুঁকি কম। প্রতিটি এন্ট্রি খুললে পূর্ণ বার্তা, তারিখ ও প্রেরকের বিবরণ পাওয়া যায়। পড়া নোটিশ এক এক করে বা একসাথে সরিয়ে তালিকা পরিষ্কার রাখা যায়। রুটিন সার্কুলার থেকে জরুরি নিরাপত্তা নির্দেশনা পর্যন্ত সব যোগাযোগের নির্ভরযোগ্য রেকর্ড এটি।", en: "All announcements, notices and alerts issued to guardians appear in one list, with unread items marked so nothing urgent is missed. Opening an entry shows the full message, its date and who sent it. Notices already read can be cleared one by one or in bulk to keep the view on pending items. It holds routine circulars as well as urgent safety instructions, giving parents a dependable record of school communication." },
  "/dashboard/parent/parent-insights": { bn: "এই পেজে সন্তানের পড়াশোনা নিয়ে সাপ্তাহিক ভিত্তিতে সহজ ভাষায় অন্তর্দৃষ্টি দেওয়া হয়। জটিল পরিভাষা ছাড়া বলা হয় সন্তান কোন বিষয়ে ভালো করছে, কোথায় পিছিয়ে পড়ছে এবং অভিভাবক হিসেবে কীভাবে সহায়তা করা যায়। এই সারসংক্ষেপ পড়ে বাড়িতে পড়াশোনার পরিবেশ সাজানো সহজ হয়। সপ্তাহের পর সপ্তাহ পরিবর্তন দেখলে সন্তানের অগ্রগতিও ধারাবাহিকভাবে বোঝা যায়। সাপ্তাহিক অন্তর্দৃষ্টি সহজ ভাষায় লেখা, তাই একবার পড়েই বোঝা যায়।", en: "This page offers weekly insights into the child's studies in plain language. Without heavy terminology it says what the child is doing well in, where they are falling behind, and how a parent can help at home. Reading the summary makes it easier to set up a study routine. Following it week after week also shows whether progress is steady." },
  "/dashboard/parent/profile": { bn: "অভিভাবক অ্যাকাউন্টের নিজস্ব তথ্য এখানে দেখা যায়, যেমন নাম, যোগাযোগের বিবরণ ও অ্যাকাউন্ট-সংক্রান্ত খুঁটিনাটি। যে তথ্যগুলো নিজে পরিবর্তন করা যায় সেগুলো সম্পাদনা করে সংরক্ষণ করা যায়, আর স্কুল-নিয়ন্ত্রিত তথ্য কেবল দেখা যায়। ভুল বা পুরোনো তথ্য থাকলে সংশোধন করে রাখলে যোগাযোগ ও নোটিশ প্রাপ্তি নির্ভুল থাকে। কোন যোগাযোগের বিবরণ স্কুল ব্যবহার করছে তা যাচাই করার জায়গাও এটি। নিজের ভূমিকা ও সংযুক্ত সন্তানের তথ্যও এখানে যাচাই করা যায়, তাই আলাদা পাতা খোঁজার দরকার নেই।", en: "Shows the guardian account details held by the system, including name, contact information and account particulars. Fields the guardian controls can be edited and saved directly, while school-managed fields stay read-only for reference. Keeping this information current means notices and messages reach the right person without delay. It is also where you confirm which contact details the school is actually using." },
  "/dashboard/parent/reports/attendance-summary": { bn: "সংযুক্ত সন্তানের উপস্থিতির সারসংক্ষেপ এখানে দেখা যায়, উপস্থিত, অনুপস্থিত ও ছুটির হিসাব একসাথে। নির্দিষ্ট সময়ের পরিসরে উপস্থিতির ধারা দেখে নিয়মিত অনুপস্থিতির ধরন বোঝা যায়। কোনো সময়ে উপস্থিতি কম থাকলে তা আলাদা করে চোখে পড়ে। অভিভাবক হিসেবে এই সারাংশ স্কুলের সাথে আলোচনার সময় নির্ভরযোগ্য ভিত্তি দেয়। উপস্থিতির হার সারসংক্ষেপে দেখানো হয়, তাই দীর্ঘ তালিকা না পড়েও সামগ্রিক অবস্থা বোঝা যায় এবং কোনো ছুটির কারণ উল্লেখ থাকলে তাও দেখা যায়।", en: "A summary of the linked child's attendance, bringing present, absent and leave days together in one view. Read across a chosen period, the pattern tells more than the totals: it shows whether absences are occasional or habitual. Spans with thin attendance stand out on their own. Parents can rely on these figures when raising attendance with the school." },
  "/dashboard/parent/reports/linked-child-progress": { bn: "সংযুক্ত সন্তানের অগ্রগতি একটি স্ক্রিনে সাজিয়ে দেখানো হয়, তাই বিভিন্ন পাতা ঘুরে তথ্য খোঁজার দরকার হয় না। কোন টপিকে দখল তৈরি হয়েছে আর কোনটিতে পিছিয়ে আছে তা একসাথে বোঝা যায়। সাম্প্রতিক ফলাফল ও কার্যক্রমের ধারা পাশাপাশি দেখে পরিস্থিতির পূর্ণ চিত্র পাওয়া যায়। একাধিক সন্তান সংযুক্ত থাকলে প্রত্যেকের অবস্থা আলাদাভাবে যাচাই করা যায়। শিক্ষকের সাথে আলোচনার সময় এই একক দৃশ্যপট ধরে রাখলে একই তথ্য নিয়ে বিভ্রান্তি কমে।", en: "Places the linked child's progress on a single screen, so there is no need to hunt across pages for related figures. Topics already mastered and topics still lagging can be read together. Recent results and activity sit alongside each other, giving a fuller picture than either would alone. Where more than one child is linked, each can be checked separately." },
  "/dashboard/parent/reports/teacher-interventions": { bn: "শিক্ষক সন্তানের জন্য যে সহায়তা পরিকল্পনা খুলেছেন তা এখানে দেখা যায়। প্রতিটি ইন্টারভেনশনে কোন সমস্যার জন্য, কী পদক্ষেপ নেওয়া হচ্ছে এবং কে দেখছে তা উল্লেখ থাকে। অভিভাবক এই তথ্য দেখে বাড়িতেও একই ধরনের সহায়তা চালিয়ে যেতে পারেন। ফলে শ্রেণিকক্ষের পদক্ষেপ ও বাড়ির প্রচেষ্টার মধ্যে মিল তৈরি হয়। শিক্ষক পরবর্তী ধাপে কী করবেন তা এই তালিকা থেকেই বোঝা যায়, তাই অভিভাবক উদ্যোগটি কতদূর গেছে তা জানতে পারেন এবং প্রয়োজনে মতামত দিতে পারেন।", en: "Shows the support plans a teacher has opened for the child. Each intervention records what the difficulty was, what steps are being taken and who is following it. A parent who can see this can carry on similar support at home instead of unknowingly working against it. The result is one effort shared between classroom and household." },
  "/dashboard/parent/reports/weak-topic-alerts": { bn: "সন্তান কোনো টপিকে পিছিয়ে পড়লে এই পাতায় সতর্কবার্তা তৈরি হয়। প্রতিটি সতর্কবার্তায় কোন টপিক, কোন ক্লাস এবং কতটা দুর্বলতা দেখা দিয়েছে তা উল্লেখ থাকে। সতর্কতা আগে থেকেই পেলে সময়মতো বাড়তি সহায়তা দেওয়া যায়, ফলাফল খারাপ হওয়ার পরে নয়। তালিকা দেখে বোঝা যায় কোন বিষয়গুলোতে নিয়মিত নজর দরকার। প্রতিটি সতর্কবার্তা কোন লেসন বা অ্যাসেসমেন্ট থেকে এসেছে তা মিলিয়ে দেখা যায়, ফলে সিদ্ধান্তটি অনুমান নয়, ফলাফলের ভিত্তিতে তৈরি।", en: "Alerts appear on this page when a child begins to fall behind in a topic. Each alert records which topic, which class and how far the weakness has gone. Warning early allows extra support to be arranged in time rather than after a poor result has been recorded. Reading the list shows which subjects need attention on a continuing basis." },
  "/dashboard/parent/reports/weekly-parent-insight": { bn: "এই সপ্তাহে সন্তানের পড়াশোনা ও কার্যক্রম নিয়ে যে অন্তর্দৃষ্টি তৈরি হয়েছে তা এখানে সারসংক্ষেপে দেওয়া হয়। সপ্তাহের অগ্রগতি, অংশগ্রহণ এবং লক্ষণীয় পরিবর্তনগুলো একসাথে দেখে বোঝা যায় পরিস্থিতি কেমন চলছে। প্রতিদিনের হিসাব না দেখে সাপ্তাহিক চিত্র পেলে অভিভাবক দ্রুত সিদ্ধান্ত নিতে পারেন। কোনো দিক উদ্বেগজনক হলে তা আলাদা করে চোখে পড়ে। গত সপ্তাহের তুলনায় কী বদলেছে তা দেখলে বোঝা যায় সন্তানের রুটিনে কোনো পরিবর্তন দরকার কি না।", en: "Summarises what the week shows about the child's study and activity. Weekly progress, participation and any noticeable shift are read together, which gives a clearer sense of direction than any single day. With a week at a glance a parent can decide quickly instead of checking figures every evening. Where something is going wrong, it is meant to be visible before it becomes serious." },
  "/dashboard/parent/support": { bn: "স্কুলে দেখা কোনো সমস্যা, প্রশ্ন বা অভিযোগ এখান থেকে সরাসরি জানানো যায় এবং তার অগ্রগতি অনুসরণ করা যায়। প্রতিটি অনুরোধের অবস্থা, কে দেখছে এবং কী উত্তর এসেছে তা একই জায়গায় থাকে। উত্তর এলে তা এখানেই পড়া যায়, প্রয়োজনে একই সূত্রে পরবর্তী মন্তব্য যোগ করা যায়। ফলে ফোন বা ব্যক্তিগত যোগাযোগের উপর নির্ভর না করেই অভিভাবক সহায়তা পেতে পারেন। প্রতিটি অনুরোধ নিষ্পত্তি হলে তা বন্ধ হিসেবে চিহ্নিত হয়, ফলে পুরোনো বিষয় তালিকায় জমে থাকে না।", en: "Guardians raise a problem, question or complaint with the school here and follow how it is handled. Every request keeps its status, the person handling it and any reply in one place. Replies can be read in the same thread and followed up with further comments when something is unclear. This gives parents a documented route to support instead of relying on phone calls or chance conversations." },
  "/dashboard/parent/teacher-messages": { bn: "এই পেজে সন্তানের শিক্ষকদের সঙ্গে আদান-প্রদান করা বার্তাগুলো দেখা যায়। কে কখন কী লিখেছেন তা একই জায়গায় থাকায় আলোচনার ধারাবাহিকতা বজায় থাকে এবং আগের কথাগুলো আবার মনে করতে সুবিধা হয়। এখান থেকে শিক্ষককে বার্তা পাঠিয়ে সন্তানের পড়াশোনা বা উপস্থিতি নিয়ে সরাসরি কথা বলা যায়। লিখিত বার্তা থাকায় গুরুত্বপূর্ণ বিষয় পরে যাচাই করাও সহজ হয়। শিক্ষক ও অভিভাবক উভয়ের জন্যই একই কথোপকথন এক জায়গায় সংরক্ষিত থাকে।", en: "This page shows the messages exchanged with the child's teachers. Who wrote what and when is kept in the same place, so a conversation keeps its thread and earlier points can be recalled. From here a parent can send a message to a teacher and discuss the child's studies or attendance directly. Having the exchange in writing also makes important points easy to check later." },
  "/dashboard/parent/tutor-data": { bn: "এই পেজে দেখা যায় এআই টিউটর এই সন্তান সম্পর্কে কী তথ্য পড়েছে এবং কেন সেই তথ্য ব্যবহার করেছে। কোন ধরনের রেকর্ড টিউটরের কাছে গেছে তা জানলে অভিভাবক বুঝতে পারেন উত্তরগুলো কীসের ভিত্তিতে তৈরি হচ্ছে। এই স্বচ্ছতা থাকলে প্রযুক্তিটি কীভাবে কাজ করছে তা নিয়ে আস্থা তৈরি হয় এবং প্রয়োজনে প্রশ্ন করার সুযোগ থাকে। সন্তানের তথ্যের ওপর অভিভাবকের নিয়ন্ত্রণ বজায় রাখার জন্যও পেজটি গুরুত্বপূর্ণ।", en: "This page shows what the AI tutor has read about this child and why it used that information. Seeing which kinds of records reach the tutor helps a parent understand what the answers are built on. That transparency supports trust in how the tool works and leaves room to ask questions where something seems unclear. It also keeps the parent in control of the child's information." },
  "/dashboard/student/ai-pathshala/ai-tutor": { bn: "পড়ার সময় প্রশ্ন জাগলে এই পাতার চ্যাট টিউটরের কাছে জিজ্ঞাসা করা যায়। এটি কেবল অনুমোদিত লেসন কনটেন্ট থেকে উত্তর দেয়, তাই উত্তরগুলো পাঠ্যবই ও ক্লাসের সঙ্গে মিলে যায়। কোনো প্রশ্নের উত্তর না থাকলে সেটি জানিয়ে দেয়, বানিয়ে কিছু বলে না। আটকে যাওয়া অংশ দ্রুত বুঝে নিতে শিক্ষার্থীরা এই টিউটর ব্যবহার করে। যে লেসন থেকে উত্তর এসেছে, সেটি খুলে মূল অংশটি পড়ে নেওয়া যায়। ক্লাসে যা পড়ানো হয়েছে তার সঙ্গে মিলিয়ে দেখলে বোঝা সহজ হয়।", en: "When a question comes up while reading, the chat tutor on this page can be asked. It answers only from approved lesson content, so the replies stay aligned with the text and the class. If a question has no answer there, it says so rather than making something up. Students use the tutor to get past a stuck portion quickly. The lesson behind an answer can be opened and read in its original form." },
  "/dashboard/student/ai-pathshala/assessments": { bn: "নিজের অংশ নেওয়া অ্যাসেসমেন্ট ও তার প্রাপ্ত নম্বর এই পাতায় দেখা যায়। কোন অ্যাসেসমেন্টে কত নম্বর এসেছে এবং কোথায় কম পড়েছে, তা একসাথে বোঝা যায়। ফল দেখে দুর্বল অংশ চিহ্নিত করে পরেরবারের প্রস্তুতি সাজানো যায়। শিক্ষার্থীরা নিজের অগ্রগতি বুঝতে ও শিক্ষকের সঙ্গে আলোচনার আগে এই তথ্য দেখে নেয়। একাধিক অ্যাসেসমেন্টের ফল পাশাপাশি দেখে উন্নতির ধারা বোঝা যায়। কোন বিষয়ে নম্বর কম আসছে, তা দেখে সেই বিষয়ে বেশি মনোযোগ দেওয়া যায়।", en: "The assessments the student took and the marks obtained are shown on this page. It brings together what was scored in each assessment and where the score fell short. Reading the result makes it easier to mark the weak part and prepare differently next time. Students check this before discussing progress with a teacher. Comparing several results shows the direction of improvement over time." },
  "/dashboard/student/ai-pathshala/lesson-planner": { bn: "দিন ধরে সাজানো লেসন প্ল্যান এই পাতায় দেখা যায়। কোন দিনে কোন ক্লাসে কী পড়ানো হবে তা আগেই জানা যায়, ফলে ক্লাসের আগে প্রস্তুতি নেওয়া সহজ হয়। পড়া এগোলে পরিকল্পনাও বদলায়, তাই হালনাগাদ তথ্যই দেখা হয়। কোন অংশ এখনো বাকি আছে তা বুঝে নিজের পড়া সাজিয়ে নিতে এই প্ল্যান কাজে লাগে। কোন বিষয়ে কতটা এগোনো হয়েছে, তা দেখে পিছিয়ে থাকা অংশে মন দেওয়া যায়। ক্লাসের আগে পরের দিনের অংশ পড়ে রাখলে পাঠ বুঝতে সুবিধা হয়।", en: "Day-by-day lesson plans are visible on this page. What will be taught in which class on which day is known in advance, which makes preparation before class easier. The plan shifts as teaching moves along, so what is shown is current. Seeing which part is still pending helps in arranging one's own reading. Reading the next day's portion in advance makes the lesson easier to follow." },
  "/dashboard/student/ai-pathshala/lessons": { bn: "নিজের ক্লাস ও বিষয় অনুযায়ী সাজানো কাঠামোবদ্ধ এআই লেসন এই পাতায় পাওয়া যায়। যেসব লেসন নিজের জন্য প্রযোজ্য, সেগুলোই তালিকায় আসে, তাই অপ্রয়োজনীয় কিছু খুঁজতে হয় না। প্রতিটি লেসন খুলে ধাপে ধাপে পড়া যায় এবং পড়ার সময় প্রস্তুতি নেওয়া সহজ হয়। ক্লাসের পড়া বোঝা ও রিভিশনে এই লেসনগুলো কাজে লাগে। লেসনের ভেতরের কনটেন্ট অনুমোদিত, তাই পড়ার সময় ভুল তথ্যের ভয় থাকে না। পড়া শেষে সেই বিষয়ের কুইজ দিয়ে নিজেকে যাচাই করা যায়।", en: "Structured AI lessons arranged for the student's own class and subjects are available here. Only the lessons that apply to that student appear in the list, so there is nothing extra to sift through. Each lesson opens for reading step by step. These lessons help in understanding class work and in revision. Once a lesson is read, a quiz on the same topic can be used to test oneself." },
  "/dashboard/student/ai-pathshala/progress": { bn: "এই পেজে লগইন করা শিক্ষার্থী নিজের টপিকভিত্তিক মাস্টারি অগ্রগতি দেখতে পায়। প্রতিটি টপিকের সঙ্গে তার বর্তমান দক্ষতার মাত্রা ও অগ্রগতির ধারা দেখানো হয়, যাতে কোন বিষয়ে সে কতটা এগিয়েছে তা স্পষ্ট বোঝা যায়। শিক্ষার্থী তালিকা ধরে নিজের শক্ত ও দুর্বল জায়গা আলাদা করে পরবর্তী অনুশীলনের সিদ্ধান্ত নিতে পারে। পেজটি কেবল নিজের অগ্রগতির জন্য তৈরি, তাই সময়ের সঙ্গে মাস্টারি কীভাবে বাড়ছে বা কোথায় স্থির রয়েছে তাও বোঝা যায়।", en: "This page shows the signed-in student how mastery is developing topic by topic. Each topic shows the current level of understanding and the direction progress is taking. The student can work through the list to separate strong areas from weaker ones and decide what to practise next. It is a personal view built around the logged-in user, so the picture reflects that student's own learning." },
  "/dashboard/student/ai-pathshala/quizzes": { bn: "নিজের জন্য তৈরি এআই কুইজের তালিকা এই পাতায় থাকে। জমা দেওয়ার সঙ্গে সঙ্গেই উত্তর যাচাই হয়ে যায়, ফলে ফলের জন্য অপেক্ষা করতে হয় না। কোন প্রশ্নে ভুল হয়েছে তা দেখে বোঝা যায় কোন অংশে আরও পড়া দরকার। ক্লাসের আগে বা পরে নিজের বোঝাপড়া যাচাই করতে শিক্ষার্থীরা এই কুইজ ব্যবহার করে। কোন বিষয়ের কুইজ কতটা সহজ বা কঠিন মনে হয়েছে, তাও বোঝা যায়। বারবার ভুল হওয়া প্রশ্নগুলো আলাদা করে দেখে সেগুলোতে বেশি সময় দেওয়া যায়।", en: "The AI quizzes made for the student are listed on this page. Answers are checked the moment they are submitted, so there is no wait for a result. Seeing which questions went wrong points to the part that needs more reading. Students use these quizzes before or after class to test their own understanding. Questions missed repeatedly can be singled out and given more time." },
  "/dashboard/student/ai-pathshala/study-plan": { bn: "এই পেজে শিক্ষার্থীর সবচেয়ে দুর্বল টপিকগুলোকে ভিত্তি করে তৈরি একটি ব্যক্তিগত স্টাডি প্ল্যান দেখানো হয়। প্ল্যানে কোন টপিক কোন ক্রমে পড়া উচিত এবং প্রতিটির জন্য কী ধরনের অনুশীলন দরকার তা সাজিয়ে দেওয়া হয়, যাতে প্রস্তুতি এলোমেলো না হয়ে ধাপে ধাপে এগোয়। শিক্ষার্থী নিজের প্ল্যান দেখে বুঝতে পারে কোন অংশে আগে মনোযোগ দিতে হবে এবং পড়ার সময় সেই অনুযায়ী ভাগ করতে পারে। দুর্বলতা কমলে প্ল্যানের অগ্রাধিকারও বদলে যায়।", en: "This page presents a personal study plan built from the topics the student is weakest in. The plan sets out which topic to take first, in what order to work through the rest, and what kind of practice each one needs, so preparation moves step by step instead of at random. The student can follow the plan to decide how to divide study time. As weaker topics improve, the priorities in the plan shift accordingly." },
  "/dashboard/student/notifications": { bn: "নিজের জন্য আসা ঘোষণা ও সতর্কবার্তার তালিকা এই পাতায় দেখা যায়। প্রতিটি বার্তা খুলে পুরোটা পড়া যায় এবং কোনটি সদ্য এসেছে তা আলাদা করে বোঝা যায়। ক্লাস, পরীক্ষা বা ছুটির মতো বিষয়ে জরুরি বার্তা যাতে চোখ এড়িয়ে না যায়, সেদিকে নজর রাখা যায়। পড়া হয়ে গেলে পুরোনো বার্তার ভেতরেও ফিরে দেখা যায়। কোন বার্তা কবে এসেছে, তা সময় দেখে বোঝা যায়। যা পড়া হয়ে গেছে, তা আর অপঠিত হিসেবে দেখায় না।", en: "Announcements and alerts meant for the student are listed on this page. Each message opens for a full read, and items that have just arrived stand apart from older ones. Attention can be kept on urgent notices about class, examinations or holidays. Anything already read can be revisited later. The time on each message shows when it arrived, and read notices stop counting as new." },
  "/dashboard/student/profile": { bn: "শিক্ষার্থীর নিজের প্রোফাইল এই পাতায় দেখা যায়। যে তথ্য শিক্ষার্থী রেকর্ডে লেখা থাকে, যেমন ভর্তি নম্বর, ক্লাস, সেকশন ও রোল, তা এখানেই প্রতিফলিত হয়। ভুল কিছু থাকলে সংশোধনের অনুরোধ করা যায়, আর ঠিকানা বা যোগাযোগের তথ্য নিজে হালনাগাদ করা যায়। নিজের তথ্য সঠিক রাখতে শিক্ষার্থী এই পাতা ব্যবহার করে। প্রতিটি তথ্য শিক্ষার্থী রেকর্ডের সঙ্গে মিলে যায়, তাই ভুল সংশোধন হলে দুই জায়গাতেই ঠিক হয়। অভিভাবকের যোগাযোগের নম্বরও এখানে দেখা যায়।", en: "The student's own profile appears on this page. Details held in the student record, such as the admission number, class, section and roll, are reflected here. Anything wrong can be flagged for correction, and address or contact information can be updated directly. Students use this page to keep their details accurate. Guardian contact details are visible here too, alongside the student's own." },
  "/dashboard/student/reports/mastery-progress": { bn: "এই পেজে টার্ম জুড়ে শিক্ষার্থীর মাস্টারি অগ্রগতির চিত্র দেখা যায়। কোন টপিকে সময়ের সঙ্গে দক্ষতা বাড়ছে আর কোথায় স্থবিরতা আছে তা টপিক ধরে দেখানো হয়, ফলে পুরো টার্মের পড়াশোনার ফলাফল এক জায়গায় বোঝা যায়। শিক্ষার্থী নিজের উন্নতির ধারা দেখে আত্মবিশ্বাস পায় এবং যে বিষয়ে এখনো ঘাটতি আছে সেখানে বেশি সময় দিতে পারে। শিক্ষকের সঙ্গে অগ্রগতি নিয়ে আলোচনার সময়ও এই রিপোর্ট কাজে লাগে।", en: "This page shows how the student's mastery has moved across the term. It traces topic by topic where understanding is rising over time and where it has stalled, so the outcome of the whole term can be read in one place. Seeing the trend helps the student take confidence from real improvement and give more time to the areas still weak. The report is also useful when progress is discussed with the teacher." },
  "/dashboard/student/reports/my-ai-sessions": { bn: "এই রিপোর্টে শিক্ষার্থীর নিজের এআই টিউটর সেশনগুলোর তালিকা দেখা যায়। প্রতিটি সেশন কবে হয়েছে, কোন বিষয় বা টপিক নিয়ে প্রশ্ন করা হয়েছে এবং কী ধরনের সহায়তা পাওয়া গেছে তা এক জায়গায় সাজানো থাকে। শিক্ষার্থী পুরোনো সেশন খুঁজে দেখে আগের ব্যাখ্যা আবার পড়তে পারে, ফলে একই প্রশ্ন বারবার করার প্রয়োজন কমে। এতে নিজের শেখার ধারা এবং যে বিষয়গুলো নিয়ে বেশি কৌতূহল রয়েছে তাও সহজে বোঝা যায়।", en: "This report lists the AI tutor sessions belonging to the signed-in student. For each session it shows when it took place, which topic was discussed, and what kind of help was given. The student can look back at earlier sessions to re-read explanations, which reduces the need to ask the same question again. Over time the list also makes the student's learning pattern and areas of interest easier to see." },
  "/dashboard/student/reports/my-quiz-attempts": { bn: "এই পেজে শিক্ষার্থীর প্রতিটি কুইজ চেষ্টার রেকর্ড স্কোর ও সময়সহ দেখানো হয়। কোন কুইজে সে কত নম্বর পেয়েছে, কত সময় লেগেছে এবং কতবার চেষ্টা করেছে তা এক নজরে বোঝা যায়। শিক্ষার্থী নিজের ফলাফল পাশাপাশি রেখে দেখতে পারে কোন বিষয়ে উন্নতি হচ্ছে আর কোথায় এখনো দুর্বলতা আছে। এই তালিকা পড়াশোনার গতি বোঝার পাশাপাশি পরবর্তী প্রস্তুতির পরিকল্পনা করতেও সহায়তা করে। শিক্ষকের সঙ্গে ফলাফল নিয়ে আলোচনার সময়ও এই রেকর্ড দেখা যেতে পারে।", en: "This page records every quiz attempt made by the student together with the score and the time taken. It shows the marks each quiz earned, the time taken, and the number of attempts, so each outcome is visible at a glance. The student can compare results to see which subjects are improving and where weakness remains. The list also supports planning the next round of preparation." },
  "/dashboard/student/reports/recommended-practice": { bn: "এই পেজে শিক্ষার্থীর জন্য প্রস্তাবিত পরবর্তী অনুশীলনগুলো দেখানো হয়। তার সাম্প্রতিক ফলাফল ও দুর্বল টপিকের ভিত্তিতে কোন অনুশীলন এখন সবচেয়ে কাজে লাগবে তা আগে সাজিয়ে দেওয়া হয়, যাতে শিক্ষার্থীকে নিজে খুঁজতে না হয়। তালিকা থেকে একটি অনুশীলন বেছে নিয়ে শুরু করা যায় এবং সেটি শেষ হলে নতুন প্রস্তাব দেখা যায়। এতে পড়াশোনার ধারাবাহিকতা বজায় রাখা সহজ হয়। যে অনুশীলনগুলো বারবার প্রয়োজন হচ্ছে সেগুলো তালিকায় আলাদা করে চোখে পড়ে।", en: "This page shows the practice the student is recommended to take next. Recommendations are arranged from recent results and weak topics, so the exercises most likely to help appear first and the student does not have to search for them. The student can pick one from the list and begin, and fresh suggestions appear once it is completed. This keeps study moving without long gaps between sessions." },
  "/dashboard/student/reports/weak-topics": { bn: "এই রিপোর্টে দেখানো হয় এই শিক্ষার্থীর কোন টপিকগুলোতে দুর্বলতা রয়েছে এবং কোনগুলো আবার অনুশীলন করা দরকার। তালিকাটি শিক্ষার্থীর নিজের ফলাফলের ভিত্তিতে তৈরি হয়, তাই প্রতিটি শিক্ষার্থীর জন্য এটি আলাদা। শিক্ষার্থী এখান থেকে সবচেয়ে বেশি সমস্যার টপিক আগে বেছে নিয়ে অনুশীলন শুরু করতে পারে এবং ধীরে ধীরে বাকিগুলোতে যেতে পারে। নিয়মিত দেখলে বোঝা যায় কোন দুর্বলতা কাটছে আর কোনটি এখনো মনোযোগ চাইছে।", en: "This report shows which topics the student is weak in and which ones need further practice. The list is generated from that student's own results, so it differs from one learner to another. The student can start with the topic causing the most difficulty and work down from there. Reviewing it regularly shows which weaknesses are fading and which still need attention." },
  "/dashboard/teacher/ai-pathshala/ai-tutor": { bn: "এই পেজে শিক্ষকের জন্য এআই টিউটর চ্যাট পাওয়া যায়, যা কেবল অনুমোদিত লেসন কনটেন্ট থেকে উত্তর দেয়। প্রশ্ন করলে উত্তরটি সেই অনুমোদিত লেসনের ভিত্তিতেই আসে, তাই ক্লাসে ব্যবহারের আগে বিষয়বস্তুর নির্ভরযোগ্যতা যাচাই করা সহজ হয়। শিক্ষক এখানে নানা ধরনের প্রশ্ন করে দেখতে পারেন কোন ব্যাখ্যা শিক্ষার্থীর জন্য বেশি উপযুক্ত হবে। এতে পাঠ্যবিষয়ের বাইরের তথ্য উত্তরে মিশে যাওয়ার ঝুঁকি কমে। উত্তরগুলো পড়ে বোঝা যায় কোন অংশে আরও ব্যাখ্যা যোগ করা দরকার।", en: "This page gives the teacher a chat with the AI tutor that answers only from approved lesson content. Replies are grounded in those approved lessons, which makes it easier to check the material before using it in class. The teacher can test different kinds of questions to see which explanations would suit students. This limits the chance of material outside the syllabus slipping into an answer." },
  "/dashboard/teacher/ai-pathshala/assessments": { bn: "এই পেজে অ্যাসেসমেন্টগুলোর তালিকা এবং প্রত্যেক শিক্ষার্থীর প্রাপ্ত নম্বর দেখা যায়। শিক্ষক বুঝতে পারেন কোন অ্যাসেসমেন্টে কে কেমন করেছে এবং পুরো ক্লাসের ফলাফল কোন দিকে যাচ্ছে। নম্বর একই জায়গায় থাকায় আলাদা শিট মিলিয়ে নেওয়ার দরকার হয় না। এই তথ্য দেখে দুর্বল শিক্ষার্থী চিহ্নিত করা যায় এবং পরবর্তী ক্লাসে কোন অংশ আবার পড়ানো দরকার তা ঠিক করা যায়। ফলাফল দেখে শিক্ষার্থীর সঙ্গে আলাদা করে কথা বলার সময়ও এই তথ্য কাজে লাগে।", en: "This page lists the assessments together with the marks each student received. The teacher can see how a class performed on a given assessment and which direction overall results are taking. Having the marks in one place removes the need to reconcile separate sheets. This view helps identify students who need support and decide which part of the material should be taught again." },
  "/dashboard/teacher/ai-pathshala/assignments": { bn: "এই পেজে বরাদ্দকৃত ক্লাসের জন্য দেওয়া হোমওয়ার্ক ও অ্যাসাইনমেন্টগুলো দেখা যায়। কোন ক্লাসে কী দেওয়া হয়েছে এবং তা কোন বিষয়ের সঙ্গে সম্পর্কিত, তা এক নজরে বোঝা যায়, ফলে শিক্ষক সহজেই তালিকা ধরে এগোতে পারেন। কোন অ্যাসাইনমেন্ট চলমান আর কোনটি শেষ হয়েছে তাও দেখা যায়। এতে ক্লাসে দেওয়া কাজের হিসাব গুছিয়ে রাখা সহজ হয় এবং শিক্ষার্থীদের কাছে কী গেছে সে নিয়েও স্পষ্ট ধারণা থাকে। এতে একই ক্লাসের কাজগুলো একসঙ্গে দেখে ধারাবাহিকতা রক্ষা করা সহজ হয়।", en: "This page shows the homework and assignments set for the assigned classes. It is easy to see what has been given to which class and which subject it relates to, so the teacher can work through the list in order. The teacher can check which assignments are still running and which are finished. This keeps the record of class work organised and gives a clear view of what has reached the students." },
  "/dashboard/teacher/ai-pathshala/classes": { bn: "এই পেজে এই শিক্ষককে বরাদ্দ করা ক্লাস ও সেকশনগুলোর তালিকা দেখা যায়। কোন শ্রেণির কোন সেকশন তাঁর দায়িত্বে আছে তা এক জায়গায় পরিষ্কার থাকে, ফলে বিভ্রান্তি ছাড়া সঠিক ক্লাস বেছে নেওয়া যায়। বরাদ্দ বদলালে তালিকাও সেই অনুযায়ী হালনাগাদ হয়। অন্য পেজে ক্লাস বাছাই করার সময় এই তালিকাই ভিত্তি হিসেবে কাজ করে, তাই শিক্ষার্থী, হাজিরা ও ফলাফল সবই সঠিক ক্লাসের সঙ্গে যুক্ত থাকে। তালিকা দেখে এক নজরেই বোঝা যায় এই শিক্ষকের কাজের পরিধি কতটা বিস্তৃত।", en: "This page lists the classes and sections assigned to this teacher. Which section of which class falls under the teacher's responsibility is kept clear in one place, so the right class can be selected without confusion. The list is updated when an allocation changes. Selections made on other pages draw on this list, which keeps students, attendance, and results tied to the correct class." },
  "/dashboard/teacher/ai-pathshala/content": { bn: "এই পেজে সেই লেসন কনটেন্টগুলো দেখা যায় যা শিক্ষক ব্যবহার করতে বা ক্লাসে যুক্ত করতে পারেন। তালিকা থেকে বিষয় ও ক্লাস অনুযায়ী প্রয়োজনীয় অংশ বেছে নেওয়া যায়, ফলে নতুন করে উপকরণ বানানোর দরকার কমে। শিক্ষক কোন কনটেন্ট আগে ব্যবহার করেছেন তা দেখে প্রস্তুতির পরিকল্পনা করতে পারেন। উপযুক্ত কনটেন্ট ক্লাসে যুক্ত করলে পাঠদান ও অনুশীলন একই সূত্রে গাঁথা থাকে। শিক্ষক নিজের ক্লাসের প্রয়োজনে সবচেয়ে উপযুক্ত কনটেন্ট বেছে নিয়ে কাজ শুরু করতে পারেন।", en: "This page shows the lesson content a teacher can use or add to a class. From the list, material can be chosen by subject and class, which reduces the need to build new resources from scratch. The teacher can see what has been used before and plan preparation accordingly. Attaching suitable content to a class keeps teaching and practice built on the same material." },
  "/dashboard/teacher/ai-pathshala/interventions": { bn: "এই পেজে পিছিয়ে পড়া শিক্ষার্থীদের জন্য তৈরি সহায়তা পরিকল্পনা দেখা যায়। কোন শিক্ষার্থীর জন্য কী ধরনের অতিরিক্ত সহায়তা দরকার এবং সেই পরিকল্পনা কোন পর্যায়ে আছে তা এক জায়গায় থাকে। শিক্ষক পরিকল্পনা দেখে বুঝতে পারেন কার জন্য কোন পদক্ষেপ নেওয়া হয়েছে এবং এরপর কী করতে হবে। এতে দুর্বল শিক্ষার্থীদের প্রতি নজর রাখা সহজ হয় এবং সহায়তা দেওয়ার কাজটি এলোমেলো না হয়ে ধারাবাহিক থাকে। সহায়তা পরিকল্পনার অবস্থা দেখে আগামী সপ্তাহের জন্য অগ্রাধিকার ঠিক করা যায়।", en: "This page shows the support plans created for students who have fallen behind. It records what kind of additional help a student needs and what stage that plan has reached. The teacher can see which steps have been taken for whom and what should follow. Keeping this in one place means weaker students stay in view and support is delivered steadily rather than in scattered efforts." },
  "/dashboard/teacher/ai-pathshala/lesson-planner": { bn: "এই পেজে শিক্ষক দিনভিত্তিক লেসন প্ল্যান দেখতে ও সাজাতে পারেন। কোন দিনে কোন বিষয় বা টপিক পড়ানো হবে তা আগেই ভাগ করে নেওয়া যায়, ফলে ক্লাসের সময় কাজ গুছিয়ে এগোনো সহজ হয়। শিক্ষক প্ল্যান দেখে নিশ্চিত হতে পারেন নির্বাচিত ক্লাসের জন্য কোন দিনে কী প্রস্তুত রাখা দরকার। শিক্ষাবর্ষের মাঝপথে পাঠ্যসূচি কতদূর এগিয়েছে তা বোঝার জন্যও এই পরিকল্পনা কাজে লাগে। শিক্ষক নিজের মতো করে দিনের ক্রম সাজিয়ে নিতে পারেন, ফলে পরিকল্পনা বাস্তব সময়সূচির সঙ্গে মিলিয়ে নেওয়া সহজ হয়।", en: "This page lets the teacher view and arrange a day-by-day lesson plan. It sets out which subject or topic is to be taught on which day, so class time can be used in an organised way. The teacher can check the plan to confirm what needs to be ready for the selected class on a given day. It is also a simple way to see how far through the syllabus the term has actually moved." },
  "/dashboard/teacher/ai-pathshala/lessons": { bn: "এই পেজে ক্লাস ও বিষয়ভিত্তিক কাঠামোবদ্ধ এআই লেসনগুলো দেখা যায়। প্রতিটি লেসন নির্দিষ্ট ক্লাস ও বিষয়ের সঙ্গে যুক্ত থাকে, ফলে শিক্ষক বুঝতে পারেন কোন ক্লাসে কোন লেসন প্রযোজ্য। লেসন খুলে তার বিষয়বস্তু দেখে নেওয়া যায় এবং ক্লাসে ব্যবহারের আগে প্রস্তুতি নেওয়া যায়। সাজানো কাঠামোর কারণে একই বিষয়ের লেসনগুলো খুঁজে পাওয়া এবং ধারাবাহিকভাবে অনুসরণ করা সহজ হয়। প্রয়োজন হলে একই বিষয়ের আগের ও পরের লেসন মিলিয়ে দেখাও সহজ।", en: "This page shows the structured AI lessons organised by class and subject. Each lesson is tied to a specific class and subject, so the teacher can tell which lessons apply where. A lesson can be opened to review its content and to prepare before it is used in class. Because the lessons are arranged in a clear structure, related material for the same subject is easy to find and follow in sequence." },
  "/dashboard/teacher/ai-pathshala/progress": { bn: "এই পেজে টপিক ধরে মাস্টারি অগ্রগতির চিত্র দেখা যায়, যা লগইন করা ব্যবহারকারীর নিজের অ্যাকাউন্টের সঙ্গে যুক্ত। প্রতিটি টপিকে দক্ষতা কতটা দাঁড়িয়েছে এবং সময়ের সঙ্গে তা কীভাবে বদলাচ্ছে তা একসঙ্গে দেখানো হয়। শিক্ষক হিসেবে এখান থেকে বোঝা যায় কোন টপিকগুলোতে বেশি মনোযোগ দেওয়া দরকার এবং ক্লাসে কোন অংশ আবার আলোচনা করা উচিত। ধারাবাহিকভাবে দেখলে অগ্রগতির ধারা স্পষ্ট থাকে। শিক্ষক এই চিত্র ধরে ক্লাসের পরবর্তী পদক্ষেপ ঠিক করতে পারেন।", en: "This page shows mastery progress topic by topic for the account that is currently signed in. For each topic it presents the current level of mastery and how that level has changed over time. From a teacher's position, this makes it clear which topics deserve more attention and which parts of the class need revisiting. Watching it consistently keeps the direction of progress visible." },
  "/dashboard/teacher/ai-pathshala/quizzes": { bn: "এই পেজে এআই-জেনারেটেড কুইজগুলো দেখা যায়, যা শিক্ষার্থী জমা দেওয়ার সঙ্গে সঙ্গেই যাচাই হয়ে যায়। শিক্ষক কুইজের প্রশ্ন ও গঠন দেখে নিতে পারেন এবং কোন ক্লাস বা বিষয়ের জন্য সেটি উপযুক্ত কি না তা বুঝতে পারেন। যাচাই স্বয়ংক্রিয়ভাবে হওয়ায় প্রতিটি উত্তর আলাদা করে দেখার দরকার হয় না, ফলে মূল্যায়নের সময় কম লাগে। শিক্ষার্থীদের ফলাফল দেখে বোঝা যায় কোন প্রশ্নে বেশি ভুল হচ্ছে। প্রয়োজন হলে আগের কুইজগুলো দেখে নতুন কুইজ কেমন হবে তা ঠিক করা যায়।", en: "This page shows the AI-generated quizzes, which are checked as soon as a student submits an answer. The teacher can review the questions and structure and judge whether a quiz suits a particular class or subject. Because marking happens automatically, there is no need to go through every answer by hand, which shortens the assessment workload. Looking at the results shows which questions are producing the most mistakes." },
  "/dashboard/teacher/ai-pathshala/study-plan": { bn: "এই পেজে সবচেয়ে দুর্বল টপিক থেকে তৈরি করা ব্যক্তিগত স্টাডি প্ল্যান দেখা যায়। প্ল্যানে বলা থাকে কোন টপিক আগে ধরতে হবে এবং কোন ক্রমে অনুশীলন করলে দুর্বলতা দ্রুত কমবে। শিক্ষক হিসেবে এই প্ল্যান দেখে বোঝা যায় কোথায় ঘাটতি রয়েছে এবং সেই অনুযায়ী প্রস্তুতি বা ক্লাসের পরিকল্পনা সাজানো যায়। অগ্রগতি বাড়ার সঙ্গে প্ল্যানের অগ্রাধিকারও হালনাগাদ হয়। প্ল্যানটি দেখে শিক্ষার্থীর সঙ্গে পরবর্তী পড়াশোনার বিষয়ে আলোচনাও করা যায়।", en: "This page shows a personal study plan built from the weakest topics. It sets out which topic to tackle first and in what order practice should follow for weakness to fall fastest. Seen from a teacher's side, the plan indicates where the gaps lie and helps shape preparation or class planning around them. As mastery improves, the priorities in the plan are updated." },
  "/dashboard/teacher/ai-pathshala/tutor-dataset": { bn: "এই পেজে শিক্ষকের দৃষ্টিতে সেই ডেটাসেট দেখা যায়, যা থেকে এআই টিউটর উত্তর তৈরি করে। কোন উৎস বা লেসন কনটেন্ট টিউটরের ভিত্তি হিসেবে ব্যবহৃত হচ্ছে তা জানলে উত্তরগুলোর সীমা ও নির্ভরযোগ্যতা নিয়ে স্পষ্ট ধারণা তৈরি হয়। শিক্ষক দেখে নিতে পারেন তাঁর ক্লাসের জন্য প্রয়োজনীয় বিষয়বস্তু ডেটাসেটে আছে কি না। এই স্বচ্ছতা থাকলে ক্লাসে টিউটর ব্যবহারের আগে প্রস্তুতি নেওয়া সহজ হয়। কোন অংশে তথ্য কম আছে তা বুঝলে সেই বিষয়ে কনটেন্ট যোগ করার পরিকল্পনাও করা যায়।", en: "This page shows, from the teacher's point of view, the dataset the AI tutor draws its answers from. Knowing which sources or lesson content underpin the tutor gives a clear sense of what those answers can and cannot cover. The teacher can check whether the material needed for their classes is represented in the dataset. That transparency makes it easier to prepare before the tutor is used with students." },
  "/dashboard/teacher/analytics": { bn: "এই পেজে এই শিক্ষকের নিজের ক্লাসের ওপর সীমিত পরিসরের বিশ্লেষণ দেখানো হয়। ক্লাসের শিক্ষার্থীদের ফলাফল ও অগ্রগতির সারসংক্ষেপ এক জায়গায় পাওয়া যায়, যাতে পুরো ক্লাসের অবস্থা দ্রুত বোঝা যায়। শিক্ষক এই চিত্র দেখে বুঝতে পারেন কোথায় বাড়তি মনোযোগ দরকার এবং কোন বিষয়ে ক্লাস ভালো করছে। বিশ্লেষণটি নির্দিষ্ট ক্লাসের মধ্যে সীমাবদ্ধ, তাই প্রত্যেকে কেবল নিজের দায়িত্বের অংশটুকুই দেখেন। এতে শিক্ষক নিজের ক্লাসের অবস্থা নিয়ে সহজে ধারণা রাখতে পারেন।", en: "This page provides a limited analysis of the classes assigned to this teacher. It summarises results and progress for the students in those classes, so the state of the class is grasped quickly. The teacher can use this view to judge where extra attention is needed and which subjects the class is handling well. It stays within the teacher's own classes, so each teacher sees only their own share." },
  "/dashboard/teacher/attendance": { bn: "এই পেজে শিক্ষক তাঁর বরাদ্দকৃত ক্লাসের হাজিরা নিতে ও দেখতে পারেন। নির্দিষ্ট ক্লাস ও তারিখ বেছে নিয়ে প্রতিটি শিক্ষার্থীর উপস্থিতি লিখে রাখা যায়, আর আগের দিনের রেকর্ডও একই জায়গা থেকে দেখা যায়। এতে হাজিরার হিসাব আলাদা খাতায় রাখার দরকার কমে এবং কোনো শিক্ষার্থী দীর্ঘদিন অনুপস্থিত থাকলে তা দ্রুত চোখে পড়ে। নিয়মিত হাজিরা নিলে ক্লাসের সামগ্রিক উপস্থিতির চিত্রও পরিষ্কার হয়। হাজিরার রেকর্ড পরে যাচাই করার সময়ও এই পেজ ভিত্তি হিসেবে কাজ করে।", en: "This page lets the teacher record and review attendance for the assigned classes. After choosing a class and a date, attendance can be marked for each student, and earlier records can be reviewed from the same screen. Keeping the register here removes the need for a separate paper record and makes prolonged absence stand out quickly. Regular marking also builds a clear picture of overall attendance for the class." },
  "/dashboard/teacher/notifications": { bn: "এই পেজে শিক্ষক ভূমিকার জন্য প্রযোজ্য ঘোষণা ও সতর্কবার্তাগুলো দেখা যায়। স্কুলের পক্ষ থেকে পাঠানো জরুরি নোটিশ, সময়সূচি সংক্রান্ত বার্তা বা মনোযোগ দরকার এমন তথ্য এখানে একসঙ্গে জমা থাকে, ফলে আলাদা জায়গায় খোঁজার দরকার হয় না। শিক্ষক তালিকা দেখে বুঝতে পারেন কোনটি নতুন আর কোনটি আগে পড়া হয়েছে। নিয়মিত দেখলে কোনো গুরুত্বপূর্ণ নির্দেশনা বাদ পড়ার আশঙ্কা কমে। কোনো বার্তা পড়া হয়ে গেলে তা তালিকায় আলাদা করে চেনা যায়।", en: "This page shows the announcements and alerts that apply to the teacher role. Notices from the school, schedule-related messages, and items needing attention are collected in one place, so there is no need to search elsewhere for them. The teacher can scan the list to tell which items are new and which have already been read. Checking it regularly reduces the chance of missing an important instruction." },
  "/dashboard/teacher/profile": { bn: "এই পেজে শিক্ষকের নিজের প্রোফাইল দেখা যায়, যার তথ্য ইনস্ট্রাক্টর রেকর্ডে সংরক্ষিত থাকে। নাম, যোগাযোগ ও সংশ্লিষ্ট পেশাগত তথ্য এখানে এক জায়গায় থাকে, তাই স্কুলের রেকর্ডের সঙ্গে মিলিয়ে দেখা সহজ হয়। শিক্ষক যাচাই করতে পারেন তাঁর তথ্য হালনাগাদ আছে কি না, কারণ এই তথ্যই প্রশাসনিক কাজে ব্যবহৃত হয়। ভুল বা পুরোনো কিছু চোখে পড়লে সংশ্লিষ্ট কর্তৃপক্ষের মাধ্যমে তা ঠিক করানো যায়। তথ্য হালনাগাদ থাকলে স্কুলের যোগাযোগ ও প্রশাসনিক কাজেও বিঘ্ন কম হয়।", en: "This page shows the teacher's own profile, whose details are held in the instructor record. Name, contact details, and related professional information sit in one place, which makes it easy to compare against the school's records. The teacher can confirm that the information is current, since these details are used for administrative work. If something is wrong or out of date, it can be corrected through the relevant office." },
  "/dashboard/teacher/reports/ai-tutor-sessions": { bn: "এই রিপোর্টে এই শিক্ষকের শিক্ষার্থীদের সঙ্গে হওয়া এআই টিউটর সেশনগুলো দেখা যায়। কোন শিক্ষার্থী কী নিয়ে প্রশ্ন করেছে এবং কতগুলো সেশন হয়েছে তা এক জায়গায় পাওয়া যায়, ফলে বোঝা যায় শিক্ষার্থীরা কোথায় বেশি সহায়তা খুঁজছে। এই তথ্য দেখে ঠিক করা যায় ক্লাসে কোন বিষয় আবার ব্যাখ্যা করা দরকার। শেখার আগ্রহ ও সমস্যার ধরন বোঝার জন্যও সেশনগুলো কাজে লাগে। শিক্ষক এই তালিকা দেখে ক্লাসের পরবর্তী আলোচনার বিষয় ঠিক করতে পারেন।", en: "This report shows the AI tutor sessions held by this teacher's students. It brings together which student asked about what and how many sessions took place, so it is clear where students are seeking the most help. That view helps decide which subject should be explained again in class. The sessions also reveal the kind of difficulties students meet and what they are curious about." },
  "/dashboard/teacher/reports/assigned-classes": { bn: "এই রিপোর্টে এই শিক্ষককে বরাদ্দ করা ক্লাসগুলোর তালিকা সংখ্যাসহ দেখা যায়। কোন শ্রেণি ও সেকশন তাঁর দায়িত্বে আছে এবং সেই হিসাবে মোট কতগুলো ক্লাস তাঁর নামে রয়েছে তা এক নজরে বোঝা যায়। শিক্ষক এই সংখ্যা দেখে নিজের কাজের পরিধি বুঝতে পারেন এবং সময় ভাগ করে নিতে পারেন। প্রশাসনিক আলোচনা বা দায়িত্ব বণ্টনের সময়ও এই রিপোর্ট প্রমাণ হিসেবে কাজে লাগে। নিজের দায়িত্বের পরিধি বুঝে নেওয়ার সবচেয়ে সরল রিপোর্ট এটি।", en: "This report lists the classes assigned to this teacher along with the count. It shows which classes and sections are the teacher's responsibility and how many classes are recorded under their name in total. The teacher can use that number to judge the extent of the workload and divide time sensibly. The report is also useful as a reference in administrative discussion or when duties are shared out." },
  "/dashboard/teacher/reports/intervention-plans": { bn: "এই রিপোর্টে সহায়তা পরিকল্পনাগুলো তাদের অবস্থা অনুযায়ী দেখা যায়, যেমন খোলা, চলমান ও সমাপ্ত। কোন পরিকল্পনা এখনো শুরু হয়নি, কোনটি চলছে এবং কোনটি শেষ হয়েছে তা আলাদা করে বুঝতে পারলে কাজের অগ্রগতি পরিষ্কার হয়। শিক্ষক চলমান পরিকল্পনাগুলোতে নজর রাখতে পারেন এবং শেষ হওয়া পরিকল্পনার ফলাফল যাচাই করতে পারেন। এতে সহায়তা কার্যক্রম ফেলে রাখা বা ভুলে যাওয়ার সম্ভাবনা কমে। কোন পরিকল্পনা দীর্ঘদিন একই অবস্থায় আছে তা দেখে দ্রুত পদক্ষেপ নেওয়া যায়।", en: "This report groups support plans by their state, covering open, ongoing, and completed plans. Separating plans that have not started, those in progress, and those already finished makes the state of the work clear. The teacher can keep an eye on the ongoing ones and check the outcome of those completed. This reduces the risk of support being left aside or forgotten." },
  "/dashboard/teacher/reports/quiz-completion": { bn: "এই রিপোর্টে দেখানো হয় কতজন শিক্ষার্থী কুইজ শেষ করেছে। কোন কুইজে সম্পন্ন করার হার কেমন তা দেখে বোঝা যায় ক্লাস কতটা এগিয়েছে এবং কোথায় থেমে আছে। শিক্ষক কম সম্পন্ন হওয়া কুইজগুলো চিহ্নিত করে কারণ খুঁজতে পারেন এবং প্রয়োজনে সময় বাড়ানো বা বিষয়টি আবার বুঝিয়ে দেওয়ার সিদ্ধান্ত নিতে পারেন। এই তথ্য ক্লাসের অংশগ্রহণ বোঝার সহজ মাপকাঠি হিসেবে কাজ করে। কোন ক্লাসের কতজন শিক্ষার্থী এখনো কুইজ শুরু করেনি তা বোঝার সুযোগও এখানে আছে।", en: "This report shows how many students have completed a quiz. The completion rate for each quiz indicates how far a class has moved and where it has stalled. The teacher can pick out the quizzes with low completion, look into the reason, and decide whether to allow more time or explain the material again. It is a straightforward measure of how engaged the class is." },
  "/dashboard/teacher/reports/student-mastery": { bn: "এই রিপোর্টে ক্লাসের প্রত্যেক শিক্ষার্থীর মাস্টারি অবস্থা দেখা যায়। কোন শিক্ষার্থী কোন টপিকে কতটা আয়ত্ত করেছে তা পাশাপাশি রেখে দেখলে ক্লাসের ভেতরের পার্থক্য স্পষ্ট হয়। শিক্ষক এই তুলনা দেখে বুঝতে পারেন কার জন্য অতিরিক্ত সহায়তা দরকার এবং কার জন্য আরও কঠিন অনুশীলন উপযুক্ত। নির্দিষ্ট শিক্ষার্থীর দিকে নজর দেওয়ার সময় এই রিপোর্ট দ্রুত সিদ্ধান্ত নিতে সাহায্য করে। ক্লাসের সামগ্রিক মাস্টারি চিত্র এক জায়গায় থাকায় শিক্ষকের পরিকল্পনা সহজ হয়।", en: "This report shows the mastery position of each student in the class. Placing students side by side topic by topic makes the spread within the class visible. From that comparison the teacher can judge who needs additional support and who would benefit from harder practice. When attention turns to a particular student, the report supports a quick decision." },
  "/dashboard/teacher/reports/weak-topic-report": { bn: "এই রিপোর্টে দেখানো হয় ক্লাস সবচেয়ে বেশি যেসব টপিকে সমস্যায় পড়েছে। একক শিক্ষার্থীর বদলে পুরো ক্লাসের দুর্বলতা একসঙ্গে দেখা যায়, ফলে কোন অংশটি সবাই মিলে বুঝতে পারছে না তা দ্রুত ধরা পড়ে। শিক্ষক সেই টপিকগুলো আগে নিয়ে আবার আলোচনা করতে পারেন বা বাড়তি অনুশীলন দেওয়ার সিদ্ধান্ত নিতে পারেন। এতে পুরো ক্লাসের ফলাফল উন্নত করার পরিকল্পনা সহজ হয়। শিক্ষক চাইলে ক্লাসে ওই টপিকগুলো নিয়ে সংক্ষিপ্ত পুনরালোচনা করতে পারেন।", en: "This report shows the topics the class has struggled with most. Weakness is presented for the whole class rather than one student at a time, so a part that nobody has understood stands out quickly. The teacher can bring those topics back for another explanation or set extra practice. Planning to lift the class result becomes easier when the shared difficulty is named plainly." },
  "/dashboard/teacher/students": { bn: "এই পেজে এই শিক্ষকের বরাদ্দকৃত ক্লাসের শিক্ষার্থীদের তালিকা দেখা যায়। কোন ক্লাস বা সেকশনে কে পড়ে, তার নাম ও সংশ্লিষ্ট তথ্য একসঙ্গে সাজানো থাকে, ফলে শিক্ষক সহজেই নির্দিষ্ট শিক্ষার্থী খুঁজে নিতে পারেন। তালিকা থেকে শিক্ষার্থী বেছে নিয়ে তার অগ্রগতি ও কার্যক্রম দেখার পথ খোলা থাকে। নতুন ক্লাস বরাদ্দ পাওয়ার পর কারা তাঁর অধীনে এসেছে তা বোঝার জন্যও এই পেজ কাজে লাগে। শিক্ষার্থীর সংখ্যা ও ক্লাসভিত্তিক ভাগও তালিকা থেকেই বোঝা যায়।", en: "This page lists the students in the classes assigned to this teacher. Names and related details are grouped by class and section, so the teacher can locate a particular student without hunting through separate records. From the list a student can be selected to review their progress and activity. It is also the quickest way to see who has come under the teacher's responsibility after a new class allocation." },
};

/**
 * Long description for a route, falling back to the short one-line summary
 * shipped with the route catalogue.
 */
export function routeDescription(
  path: string,
  fallback: RoleRouteItem["description"],
): { bn: string; en: string } {
  return ROLE_ROUTE_DESCRIPTIONS[path] ?? fallback;
}
